function loadP(txt){P.cod.length=P.desc.length=P.vl.length=P.n.length=0;pIdx.clear();
  txt.split("\n").forEach(l=>{if(!l)return;const [c,d,v]=l.split("\t");if(!c||pIdx.has(c))return;pIdx.set(c,P.cod.length);P.cod.push(c);P.desc.push(d||"");P.vl.push(parseFloat(v)||0);P.n.push(norm(d||""));});}
const E={id:[],cod:[],qt:[],pt:[]}, eIdx=new Map(), eByProd=new Map();
function loadE(txt){E.id.length=E.cod.length=E.qt.length=E.pt.length=0;eIdx.clear();eByProd.clear();
  txt.split("\n").forEach(l=>{if(!l)return;const [id,c,q]=l.split("\t");if(!id||eIdx.has(id))return;const i=E.id.length;E.id.push(id);E.cod.push(c||"");E.qt.push(parseInt(q,10)||0);E.pt.push(id.split("-"));eIdx.set(id,i);if(c&&!eByProd.has(c))eByProd.set(c,i);});}
loadP(RAW.p);loadE(RAW.e);
const C={mat:[],nome:[],fun:[],n:[]}, cIdx=new Map();
function addC(m,n,f){m=String(m||"").trim();if(!m)return -1;if(cIdx.has(m)){const i=cIdx.get(m);if(n){C.nome[i]=n;C.n[i]=norm(n);}if(f&&(!C.fun[i]||!/ROTINA/.test(f)))C.fun[i]=f;return i;}
  const i=C.mat.length;C.mat.push(m);C.nome.push(n||"");C.fun.push(f||"");C.n.push(norm(n||""));cIdx.set(m,i);return i;}
function loadC(txt){C.mat.length=C.nome.length=C.fun.length=C.n.length=0;cIdx.clear();txt.split("\n").forEach(l=>{if(!l)return;const [m,n,f]=l.split("\t");addC(m,n,f);});}
function aplicarExtras(){try{(JSON.parse(localStorage.getItem("audcd_colab_extra")||"[]")).forEach(x=>addC(x.m,x.n,x.f));}catch(e){}}
loadC(RAW.c);

const BRL=new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"});
const VL4=new Intl.NumberFormat("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});
const $=id=>document.getElementById(id);
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const LIM=25;

function addrText(pi){const e=eByProd.get(P.cod[pi]);return (e!=null?"Picking "+E.id[e]:"Sem endereço na 8022")+" · R$ "+VL4.format(P.vl[pi])+"/un";}
function searchProd(q){
  const s=norm(q).trim(); if(!s) return []; const out=[];
  if(/^\d+$/.test(s)){if(pIdx.has(s))out.push(pIdx.get(s));for(let i=0;i<P.cod.length&&out.length<LIM;i++) if(P.cod[i]!==s&&P.cod[i].startsWith(s)) out.push(i);}
  else{const w=s.split(/\s+/);for(let i=0;i<P.n.length&&out.length<LIM;i++){const n=P.n[i];if(w.every(x=>n.includes(x)))out.push(i);}}
  return out.map(i=>({key:i,t:P.cod[i]+" – "+P.desc[i],s:addrText(i)}));
}
const fmtAddr=id=>id?String(id).split("-").map(x=>/^\d+$/.test(x)?String(+x):x).join("-"):"";
const unz=v=>v==null||v===""?"":(/^\d+$/.test(String(v))?String(+v):v);
function searchAddr(q){
  const ps=q.split(/[^0-9]+/).filter(Boolean); if(!ps.length) return []; const out=[],seen=new Set();
  const n=Math.min(ps.length,4);
  for(const exact of [true,false]){
    for(let i=0;i<E.id.length&&out.length<LIM;i++){
      if(seen.has(i))continue; const a=E.pt[i]; let ok=true;
      for(let k=0;k<n;k++){const pre=(k===n-1)&&!exact; if(pre?!a[k].startsWith(ps[k]):a[k]!==ps[k]){ok=false;break;}}
      if(ok){out.push(i);seen.add(i);}
    }
  }
  const res=out.map(i=>({key:i,t:E.id[i],s:addrSub(i)}));
  if(ps.length===4){const id=ps.map(x=>String(+x)).join("-");if(!eIdx.has(id))res.unshift({key:"new:"+id,t:id,s:"Endereço não está na 8022 – usar mesmo assim"});}
  return res;
}
function addrSub(i){if(!E.cod[i])return "Endereço fora da base 8022";const pi=pIdx.get(E.cod[i]);return pi!=null?"Cadastrado: "+E.cod[i]+" – "+P.desc[pi]:"Cadastrado: produto "+E.cod[i];}
function ensureAddr(k){if(typeof k!=="string"||!k.startsWith("new:"))return k;const id=k.slice(4);if(eIdx.has(id))return eIdx.get(id);
  const i=E.id.length;E.id.push(id);E.cod.push("");E.qt.push(0);E.pt.push(id.split("-"));eIdx.set(id,i);return i;}
function searchColab(q){
  const s=norm(q).trim(); if(!s) return []; const out=[];
  if(/^\d+$/.test(s)){if(cIdx.has(s))out.push(cIdx.get(s));for(let i=0;i<C.mat.length&&out.length<LIM;i++) if(C.mat[i]!==s&&C.mat[i].includes(s)) out.push(i);}
  else{const w=s.split(/\s+/);for(let i=0;i<C.n.length&&out.length<LIM;i++){if(w.every(x=>C.n[i].includes(x)))out.push(i);}}
  return out.map(i=>({key:i,t:C.nome[i],s:"Matrícula "+C.mat[i]+" · "+C.fun[i]}));
}
function picker(root,opt){
  root.innerHTML='<div class="pk-in"><input class="in" type="search" autocomplete="off" enterkeyhint="search" placeholder="'+esc(opt.ph)+'"'+(opt.mode?' inputmode="'+opt.mode+'"':'')+'><ul class="pk-list" role="listbox"></ul></div><div class="chosen" hidden><div><div class="t"></div><div class="s"></div></div><button type="button" class="link">Trocar</button></div>';
  const wrap=root.querySelector(".pk-in"),inp=root.querySelector("input"),ul=root.querySelector("ul"),ch=root.querySelector(".chosen");
  let t=null,items=[],val=null;
  function render(){const q=inp.value;items=opt.search(q);if(!q.trim()){ul.innerHTML="";return;}
    const novo=opt.search===searchColab||!!opt.novo;
    ul.innerHTML=(items.length?items.map((it,k)=>'<li role="option" data-k="'+k+'"><span class="t">'+esc(it.t)+'</span><span class="s">'+esc(it.s)+'</span></li>').join(""):(novo?'':'<li class="none">Nada encontrado para “'+esc(q)+'”</li>'))+
      (novo?'<li class="pk-new" data-new="1"><span class="t">＋ Cadastrar novo colaborador</span><span class="s">'+(items.length?'Não está na lista? ':'Nada encontrado para “'+esc(q)+'”. ')+'Cadastre matrícula, nome e função.</span></li>':'');}
  inp.addEventListener("input",()=>{clearTimeout(t);t=setTimeout(render,110);});
  inp.addEventListener("keydown",e=>{if(e.key==="Enter"&&items.length){e.preventDefault();choose(items[0]);}});
  ul.addEventListener("click",e=>{const nw=e.target.closest("li[data-new]");if(nw){novoColab(inp.value,it=>choose(it));return;}const li=e.target.closest("li[data-k]");if(li)choose(items[+li.dataset.k]);});
  ch.querySelector("button").addEventListener("click",()=>{set(null);inp.focus();opt.onPick&&opt.onPick(null);});
  function choose(it){set(it.key,it);opt.onPick&&opt.onPick(it.key);}
  function set(key,it){val=key;inp.value="";ul.innerHTML="";if(key==null){wrap.hidden=false;ch.hidden=true;return;}
    if(!it&&opt.describe)it=opt.describe(key);ch.querySelector(".t").textContent=it.t;ch.querySelector(".s").textContent=it.s;wrap.hidden=true;ch.hidden=false;}
  return {get value(){return val;},set,clear(){set(null);},focus(){inp.focus();}};
}
const descProd=i=>({t:P.cod[i]+" – "+P.desc[i],s:addrText(i)});
const descAddr=i=>({t:E.id[i],s:addrSub(i)});
const descColab=i=>({t:C.nome[i],s:"Matrícula "+C.mat[i]+" · "+C.fun[i]});

function rackHTML(ai,cap,cls,extra){
  const [r,p,n,a]=E.id[ai].split("-");
  return '<div class="rack '+(cls||"")+'"><div class="rack-cap">'+esc(cap)+'</div><div class="rack-grid"><div><small>Rua</small><b>'+r+'</b></div><div><small>Prédio</small><b>'+p+'</b></div><div><small>Nível</small><b>'+n+'</b></div><div><small>Apto</small><b>'+a+'</b></div></div>'+(extra?'<div class="rack-body">'+extra+'</div>':'')+'</div>';
}

const pad=n=>String(n).padStart(2,"0");
const fmtDT=d=>pad(d.getDate())+"/"+pad(d.getMonth()+1)+"/"+d.getFullYear()+" "+pad(d.getHours())+":"+pad(d.getMinutes())+":"+pad(d.getSeconds());
const fmtD=iso=>{if(!iso)return "";const [y,m,d]=iso.split("-");return d+"/"+m+"/"+y;};
const todayISO=()=>{const d=new Date();return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());};
function newId(pre){const d=new Date();return pre+"-"+String(d.getFullYear()).slice(2)+pad(d.getMonth()+1)+pad(d.getDate())+"-"+pad(d.getHours())+pad(d.getMinutes())+pad(d.getSeconds())+"-"+Math.random().toString(36).slice(2,6);}
let toastT=null;
function toast(m){const t=$("toast");t.textContent=m;t.classList.add("show");clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove("show"),3200);}
const store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch(e){return false;}}};
function setErr(fid,msg){const f=$(fid);if(!f)return;f.classList.toggle("bad",!!msg);let e=f.querySelector(":scope>.err");if(msg){if(!e){e=document.createElement("div");e.className="err";f.appendChild(e);}e.textContent=msg;}else if(e)e.remove();}
function compress(file){return new Promise((res,rej)=>{const url=URL.createObjectURL(file),img=new Image();
  img.onload=()=>{let max=900,q=.6,out="";const cv=document.createElement("canvas");
    for(let k=0;k<6;k++){const sc=Math.min(1,max/Math.max(img.width,img.height));cv.width=Math.round(img.width*sc);cv.height=Math.round(img.height*sc);cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);out=cv.toDataURL("image/jpeg",q);if(out.length<65000)break;max=Math.round(max*.8);q=Math.max(.4,q-.06);}
    URL.revokeObjectURL(url);res(out);};
  img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error("img"));};img.src=url;});}

const IDB=(function(){let dbp=null;
  function open(){if(dbp)return dbp;dbp=new Promise((res,rej)=>{try{const r=indexedDB.open("audcd",1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains("hist"))d.createObjectStore("hist",{keyPath:"ID_Auditoria"});if(!d.objectStoreNames.contains("kv"))d.createObjectStore("kv");};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);}catch(e){rej(e);}});return dbp;}
  function tx(st,mode,fn){return open().then(d=>new Promise((res,rej)=>{const x=d.transaction(st,mode);const s=x.objectStore(st);const out=fn(s);x.oncomplete=()=>res(out&&out.result!==undefined?out.result:undefined);x.onerror=()=>rej(x.error);x.onabort=()=>rej(x.error);}));}
  return {all:()=>tx("hist","readonly",s=>s.getAll()),put:r=>tx("hist","readwrite",s=>s.put(r)),del:id=>tx("hist","readwrite",s=>s.delete(id)),
    get:k=>tx("kv","readonly",s=>s.get(k)),set:(k,v)=>tx("kv","readwrite",s=>s.put(v,k)),rm:k=>tx("kv","readwrite",s=>s.delete(k))};})();
const HIST=new Map();
function histPut(r){HIST.set(r.ID_Auditoria,r);return IDB.put(r).catch(()=>{toast("Não foi possível gravar no histórico do aparelho.");});}
