function refreshRuas(){RUAS.clear();E.pt.forEach(a=>RUAS.add(a[0]));}
let mode="prod";
function searchAddrRua(q){if(!S)return searchAddr(q);const ps=q.split(/[^0-9]+/).filter(Boolean);return searchAddr([S.rua].concat(ps).join("."));}
const rEnd=picker($("r-end"),{ph:"Prédio.nível.apto – ex.: 35.1.1",mode:"decimal",search:q=>searchAddrRua(q),describe:descAddr,onPick:k=>{
  if(k==null){R.prod=null;R.addr=null;R.addrManual=false;rProd.clear();rAddr.clear();paint();return;}
  k=ensureAddr(k);rEnd.set(k);
  const pi=E.cod[k]?pIdx.get(E.cod[k]):null;
  if(pi==null){R.prod=null;rProd.clear();R.addr=k;R.addrManual=true;rAddr.set(k);setMode("prod");
    toast("Endereço "+E.id[k]+" sem item cadastrado na 8022. Pesquise o item na base 286.");paint();rProd.focus();return;}
  R.prod=pi;R.addr=k;R.addrManual=eByProd.get(E.cod[k])!==k;rProd.set(pi);if(R.addrManual)rAddr.set(k);paint();}});
function setMode(m){mode=m;document.querySelectorAll(".mini button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.m===m));
  $("r-prod").hidden=m!=="prod";$("r-end").hidden=m!=="end";$("r-prod-l").textContent=m==="end"?(S?"Endereço na rua "+S.rua:"Endereço auditado"):(R.flags.erro?"Item encontrado fora do lugar":"Produto auditado");}
document.querySelectorAll(".mini button").forEach(b=>b.addEventListener("click",()=>{if(b.dataset.m===mode)return;setMode(b.dataset.m);(mode==="end"?rEnd:rProd).focus();}));
document.querySelectorAll(".tg[data-k]").forEach(b=>b.addEventListener("click",()=>{const k=b.dataset.k;R.flags[k]=!R.flags[k];b.setAttribute("aria-pressed",R.flags[k]);
  if(k==="erro"){
    if(R.flags.erro&&mode==="end"&&R.addr!=null){const f=R.addr;setMode("prod");R.prod=null;rProd.clear();R.addr=f;R.addrManual=true;rAddr.set(f);toast("Pesquise o item que estava no endereço "+E.id[f]+".");rProd.focus();}
    else{R.addr=null;R.addrManual=false;rAddr.clear();if(!R.flags.erro&&mode==="end")rEnd.clear();}
    setMode(mode);}
  paint();paintFotos();}));
const anyNC=()=>{const f=R.flags;return f.erro||f.venc||f.saldo||f.avaria;};
const picking=()=>R.prod==null?null:(eByProd.has(P.cod[R.prod])?eByProd.get(P.cod[R.prod]):null);
function auditedAddr(){if(R.flags.erro)return R.addr;return R.addrManual?R.addr:picking();}
function paint(){if(window.QW&&QW.r)QW.r.refresh();
  const pi=R.prod,pk=picking(),el=$("r-rack");
  if(pi==null){el.innerHTML="";}
  else{
    const info='<div class="d">'+esc(P.desc[pi])+'</div><div class="m"><span>Cód. '+esc(P.cod[pi])+'</span><span>R$ '+VL4.format(P.vl[pi])+'/un</span>'+(pk!=null&&E.qt[pk]?'<span>'+E.qt[pk]+' un/cx</span>':'')+'</div>';
    let h=pk!=null?rackHTML(pk,R.flags.erro?"Endereço correto do item (picking)":"Endereço de picking",null,info):(R.addr!=null&&!R.flags.erro?rackHTML(R.addr,"Endereço auditado – item sem endereço na 8022",null,info):'<div class="rack empty">Item sem endereço na base 8022 (pode estar sem saldo). Informe abaixo o endereço auditado.</div>');
    if(R.flags.erro&&R.addr!=null) h+=rackHTML(R.addr,"Onde o item foi encontrado","found",'<div class="m">'+(function(){const x=pIdx.get(E.cod[R.addr]);return x!=null?"Cadastrado aqui: "+esc(E.cod[R.addr])+" – "+esc(P.desc[x]):"";})()+'</div>');
    el.innerHTML=h;
    if(!R.flags.erro&&pk!=null&&!R.addrManual){const b=document.createElement("button");b.type="button";b.className="link";b.textContent="Auditou outro endereço? Trocar";b.onclick=()=>{R.addrManual=true;R.addr=null;rAddr.clear();paint();rAddr.focus();};el.appendChild(b);}
  }
  const showAddr=pi!=null&&(R.flags.erro||R.addrManual||pk==null);
  $("r-addr-f").hidden=!showAddr;
  $("r-addr-l").textContent=R.flags.erro?"Endereço onde o item foi encontrado":"Endereço auditado";
  const f=R.flags,nc=anyNC();
  $("sub-venc").hidden=!f.venc;$("sub-avaria").hidden=!f.avaria;
  $("r-nc").hidden=!nc;
  const v=$("r-verdict");v.className="verdict "+(nc?"nc":"ok");v.textContent=nc?"Não conformidade – status Aberta":"Endereço conforme";
  const hints=[];if(f.erro)hints.push("quantas unidades do item estavam no lugar errado");if(f.saldo)hints.push("quantas unidades faltam");if(f.avaria)hints.push("quantas unidades estão avariadas");if(f.venc)hints.push("quantas unidades estão próximas do vencimento");
  const ad=auditedAddr(),qt=pk!=null?E.qt[pk]:0;
  $("r-qtd-h").textContent=(hints.length?"Informe "+hints.join("; ")+".":"")+(qt?" 1 caixa = "+qt+" un.":"");
  const q=Math.max(0,parseInt($("r-qtd").value,10)||0),vl=pi!=null?P.vl[pi]:0;
  $("r-valor").textContent=BRL.format(q*vl);$("r-money-calc").textContent=q+" un × R$ "+VL4.format(vl);
}
$("r-qtd").addEventListener("input",paint);
document.querySelectorAll("[data-step]").forEach(b=>b.addEventListener("click",()=>{const i=$("r-qtd");i.value=Math.max(0,(parseInt(i.value,10)||0)+ +b.dataset.step);paint();}));
const MAXF=3;
function paintFotos(){const box=$("r-fotos");box.innerHTML=R.fotos.map((src,i)=>'<div class="ph-it"><img src="'+src+'" alt="Foto '+(i+1)+' do endereço"><button type="button" data-i="'+i+'" aria-label="Remover foto '+(i+1)+'">×</button></div>').join("");
  box.querySelectorAll("button").forEach(b=>b.onclick=()=>{R.fotos.splice(+b.dataset.i,1);paintFotos();});
  const full=R.fotos.length>=MAXF;$("r-cam").hidden=full;$("r-gal").hidden=full;
  $("r-foto-h").textContent=full?"Limite de 3 fotos. Remova uma para trocar.":(Object.values(R.flags).some(Boolean)?"Obrigatória: tire ao menos uma foto da não conformidade.":"Obrigatória em toda não conformidade.");}
async function addFoto(e){const f=e.target.files[0];e.target.value="";if(!f||R.fotos.length>=MAXF)return;
  try{R.fotos.push(await compress(f));paintFotos();setErr("r-foto-f","");}catch(x){toast("Não foi possível ler a foto. Tente novamente.");}}
$("r-foto").addEventListener("change",addFoto);$("r-foto-g").addEventListener("change",addFoto);
paint();

function reset(){
  rProd.clear();rAddr.clear();rRep.clear();rEnd.clear();if(S&&cIdx.has(S.rep))rRep.set(cIdx.get(S.rep));R.prod=null;R.addr=null;R.addrManual=false;R.fotos=[];
  Object.keys(R.flags).forEach(k=>R.flags[k]=false);document.querySelectorAll(".tg[data-k]").forEach(b=>b.setAttribute("aria-pressed","false"));
  $("r-venc").value="";$("r-tipo").value="";$("r-qtd").value="";if(window.QW&&QW.r)QW.r.reset();$("r-obs").value="";$("r-foto").value="";paintFotos();
  document.querySelectorAll("#v-ruas .field.bad").forEach(f=>setErr(f.id,""));setMode(S?"end":mode);paint();
}
$("r-save").addEventListener("click",async()=>{
  if(!auditor){$("sheet").hidden=false;return;}
  const errs=[],chk=(c,f,m)=>{setErr(f,c?m:"");if(c)errs.push(f);};
  const f=R.flags,nc=anyNC(),q=parseInt($("r-qtd").value,10)||0,ad=auditedAddr(),pk=picking(),venc=$("r-venc").value;
  chk(R.prod==null,"r-prod-f","Escolha o produto.");
  chk(R.prod!=null&&ad==null,"r-addr-f",f.erro?"Informe onde o item foi encontrado.":"Escolha o endereço auditado.");
  chk(f.erro&&ad!=null&&pk!=null&&ad===pk,"r-addr-f","Este é o endereço correto do item. Informe onde ele foi encontrado.");
  chk(nc&&rRep.value==null,"r-rep-f","Informe o repositor da rua.");
  chk(nc&&q<=0,"r-qtd-f","Informe as unidades encontradas.");
  chk(f.venc&&!venc,"r-venc-f","Informe a data de vencimento.");
  chk(f.venc&&venc&&venc<todayISO(),"r-venc-f","A data não pode ser anterior a hoje.");
  chk(f.avaria&&!$("r-tipo").value,"r-tipo-f","Escolha o tipo de avaria.");
  chk(nc&&!R.fotos.length,"r-foto-f",f.avaria?"Tire ao menos uma foto da avaria.":"Tire ao menos uma foto da não conformidade.");
  chk(f.avaria&&$("r-tipo").value==="Outro"&&!$("r-obs").value.trim(),"r-obs-f","Descreva a avaria na observação.");
  if(errs.length){$(errs[0]).scrollIntoView({block:"center",behavior:"smooth"});toast("Revise os campos marcados.");return;}
  const now=new Date(),[rua,pre,niv,apt]=E.id[ad].split("-"),vl=P.vl[R.prod],qq=nc?q:0,ri=rRep.value;
  const rec={ID_Auditoria:newId("AR"),DataHora:fmtDT(now),ts:now.getTime(),Matricula_Auditor:auditor,Nome_Auditor:nomeAud(),_aba:"ruas",
    Produto:P.cod[R.prod],Descricao_Produto:P.desc[R.prod],Endereco:E.id[ad],Rua:rua,Predio:pre,Nivel:niv,Apto:apt,
    Erro_Produto:f.erro,Endereco_Correto:pk!=null?E.id[pk]:"",Prox_Vencimento:f.venc,Data_Vencimento:f.venc?fmtD(venc):"",
    Sem_Saldo:f.saldo,Avaria:f.avaria,Tipo_Avaria:f.avaria?$("r-tipo").value:"",Foto_Avaria:R.fotos.length?R.fotos.length+(R.fotos.length>1?" fotos":" foto")+" no formulário HTML":"",
    Qtd_Divergencia_Un:qq,Vl_Ult_Entrada:vl,Valor_Divergencia:Math.round(qq*vl*100)/100,Observacao:$("r-obs").value.trim(),Possui_NC:nc,
    Matricula_Colaborador_NC:nc?C.mat[ri]:"",Nome_Colaborador_NC:nc?C.nome[ri]:"",Funcao_Colaborador_NC:nc?C.fun[ri]:"",
    Status_NC:nc?"Aberta":"Conforme",Responsavel_Tratativa:"",Acao_Corretiva:"",Data_Resolucao:"",Ultima_Atualizacao:fmtDT(now),foto:"",fotos:R.fotos.slice(),
    ID_Sessao:S?S.id:"",Sessao:S?{id:S.id,rua:S.rua,rep:S.rep,repNome:S.repNome,repFun:S.repFun,aud:S.aud,audNome:S.audNome}:null};
  $("r-save").disabled=true;const ok=await saveRec(rec);$("r-save").disabled=false;
  reset();window.scrollTo(0,0);renderSess();
  toast((ok||dbState==="off"?"Endereço "+fmtAddr(rec.Endereco)+" salvo":"Salvo neste aparelho, envio pendente")+(nc?" – NC de "+BRL.format(rec.Valor_Divergencia)+".":" – conforme."));
  if(nc&&!S) openPrint(rec); else if(S) (mode==="end"?rEnd:rProd).focus();
});

// base compartilhada
function saveQueue(){if(!store.set("audcd_fila",queue)){queue.forEach(x=>{x.rec.foto="";x.rec.fotos=[];});store.set("audcd_fila",queue);toast("Pouco espaço no aparelho: fotos guardadas foram descartadas.");}paintPend();}
function paintPend(){const n=queue.length,b=$("nav-pend");if(dbState==="off"){b.hidden=true;$("pend-box").innerHTML="";return;}b.hidden=!n;b.textContent=n;
  $("pend-box").innerHTML=n?'<div class="block"><h3>'+n+' registro'+(n>1?'s':'')+' aguardando envio</h3><p class="note" style="margin-top:0">Ficam guardados neste aparelho até a base compartilhada aceitar.</p><button type="button" class="btn full" id="flush">Enviar agora</button></div>':"";
  const fb=$("flush");if(fb)fb.onclick=flush;}
async function saveRec(rec){
  rec._sheet=false;await histPut(rec);sheetSync();
  if(db&&canWrite){try{const c=Object.assign({},rec);delete c._sheet;await db.collection("ruas").doc(rec.ID_Auditoria).set(c);renderRecords();return true;}catch(e){if(e&&e.code==="invalid_argument"){canWrite=false;paintConn();}}}
  if(db){queue.push({col:"ruas",rec});saveQueue();}
  renderRecords();return dbState==="off";
}
let flushing=false;
async function flush(){
  if(!db||flushing||!queue.length)return;
  flushing=true;const rest=[];
  for(const it of queue){try{await db.collection("ruas").doc(it.rec.ID_Auditoria).set(it.rec);}catch(e){rest.push(it);if(e&&e.code==="invalid_argument")canWrite=false;}}
  const sent=queue.length-rest.length;queue=rest;saveQueue();flushing=false;paintConn();renderRecords();
  if(sent)toast(sent+" registro"+(sent>1?"s enviados":" enviado")+".");
}
function paintConn(){const dot=$("connDot"),m=$("conn-msg");
  if(dbState==="on"&&canWrite){dot.className="dot on";m.textContent="Conectado à base compartilhada. Todos os auditores veem estes registros.";}
  else if(dbState==="on"){dot.className="dot off";m.textContent="Você pode ver os registros, mas não gravar. Peça ao dono do formulário acesso de Colaborador.";}
  else if(dbState==="off"){dot.className="dot off";m.textContent="Modo arquivo: os registros ficam salvos neste aparelho e são enviados à planilha Google quando houver internet.";}
  else{dot.className="dot";m.textContent="Conectando à base compartilhada…";}}
window.addEventListener("online",flush);
(async()=>{
  if(!(window.claude&&typeof window.claude.use==="function")){dbState="off";paintConn();paintPend();renderRecords();return;}
  try{db=await window.claude.use("db");}catch(e){db=null;}
  try{downloads=await window.claude.use("downloads");}catch(e){downloads=null;}
  try{const u=await window.claude.use("user");if(u){const w=await u.can("data.write");if(w===false)canWrite=false;}}catch(e){}
  if(!db){dbState="off";paintConn();paintPend();renderRecords();return;}
  dbState="on";paintConn();paintPend();
  db.collection("ruas").orderBy("ts","desc").limit(1000).onSnapshot(s=>{remote.ruas=s.docs.map(d=>d.data());renderRecords();},e=>{if(e&&e.code!=="unavailable"){dbState="off";paintConn();}});
  flush();
})();

// registros
$("f-periodo").onchange=()=>{const d=$("f-periodo").value==="d";$("f-datas").hidden=!d;if(d&&!$("f-de").value){$("f-de").value=todayISO();$("f-ate").value=todayISO();}renderRecords();};
$("f-quem").onchange=renderRecords;$("f-aba").onchange=renderRecords;$("f-tipo").onchange=renderRecords;$("f-de").onchange=()=>{if(!$("f-ate").value||$("f-ate").value<$("f-de").value)$("f-ate").value=$("f-de").value;renderRecords();};$("f-ate").onchange=renderRecords;
const dayStart=iso=>{const [y,m,d]=iso.split("-").map(Number);return new Date(y,m-1,d).getTime();};
function allRecs(){const ids=new Set(),out=[];queue.forEach(x=>{ids.add(x.rec.ID_Auditoria);out.push(Object.assign({_pend:true},x.rec));});HIST.forEach(r=>{if(!ids.has(r.ID_Auditoria)){ids.add(r.ID_Auditoria);out.push(r);}});remote.ruas.forEach(r=>{if(!ids.has(r.ID_Auditoria))out.push(r);});return out.sort((a,b)=>b.ts-a.ts);}
function filtered(){const ab=$("f-aba").value,pv=$("f-periodo").value,eu=$("f-quem").value==="eu",tp=$("f-tipo").value;let from=0,to=Infinity;
  if(pv==="d"){const de=$("f-de").value,ate=$("f-ate").value||de;if(de){from=dayStart(de);to=dayStart(ate)+864e5;}}
  else{const days=+pv;if(days){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(days-1));from=d.getTime();}}
  return (regFonte()==="planilha"?sheetRecs():allRecs()).filter(r=>(ab==="todas"||(r._aba||"ruas")===ab)&&r.ts>=from&&r.ts<to&&(!eu||r.Matricula_Auditor===auditor)&&(tp==="todos"||(tp==="nc"?r.Possui_NC:!r.Possui_NC)));}
function renderRecords(){if(typeof renderSess==="function")try{renderSess();}catch(e){}try{if(!$("v-painel").hidden)renderPainel();}catch(e){}try{paintSync();}catch(e){}
  const pla=regFonte()==="planilha";if(pla&&!REG.rows&&!REG.busy&&!$("v-registros").hidden)setTimeout(carregarReg,0);
  const sl=$("sync-line");if(pla&&sl){sl.hidden=false;sl.style.color="";sl.innerHTML=esc(REG.info||"Planilha Google")+' <button type="button" class="link" id="reg-upd" style="padding:0 4px">Atualizar</button>';$("reg-upd").onclick=()=>carregarReg(true);}
  const all=pla?sheetRecs():allRecs(),t0=new Date();t0.setHours(0,0,0,0);
  const ab=all.filter(r=>r.Possui_NC&&r.Status_NC!=="Resolvida");
  $("s-hoje").textContent=all.filter(r=>r.ts>=t0.getTime()).length;$("s-nc").textContent=ab.length;
  $("s-valor").textContent=BRL.format(ab.reduce((s,r)=>s+(+r.Valor_Divergencia||0),0)).replace(",00","");
  const list=filtered(),L=$("list");
  if(!list.length){L.innerHTML='<div class="empty">Nenhum registro com estes filtros.<br>Ajuste o período ou o tipo.</div>';return;}
  const adm=temPerm("aud_adm");L.innerHTML=list.slice(0,200).map(r=>{let h=r._aba==="retorno"?cardRet(r):r._aba==="cargas"?cardCar(r):r._aba==="aero"?cardAer(r):card(r);if(adm)h=h.replace(/<\/details>$/,'<button type="button" class="btn full rdel" data-id="'+esc(r.ID_Auditoria)+'" data-aba="'+esc(r._aba||"ruas")+'" style="margin-top:8px;color:var(--alert);border-color:var(--alert)">Excluir registro</button></details>');return h;}).join("")+(list.length>200?'<p class="note">Mostrando 200 de '+list.length+'. O CSV inclui todos.</p>':"");
  L.querySelectorAll(".rdel").forEach(b=>b.onclick=()=>excluirRegistro(b.dataset.id,b.dataset.aba));
  L.querySelectorAll(".cgrel").forEach(b=>b.onclick=async()=>{const recs=regBase().filter(x=>x.ID_Sessao===b.dataset.s);if(recs.length){await carregarFotosPlanilha(recs);openCarDoc(recs[0].Sessao||sessaoDe(recs[0],recs),recs);}});
  L.querySelectorAll(".rtrel").forEach(b=>b.onclick=async()=>{const recs=regBase().filter(x=>x.ID_Sessao===b.dataset.s);if(recs.length){await carregarFotosPlanilha(recs);openRetDoc(recs[0].Sessao||sessaoDe(recs[0],recs),recs);}});
  L.querySelectorAll(".rbtn").forEach(b=>b.onclick=async()=>{const recs=regBase().filter(x=>x.ID_Sessao===b.dataset.s);if(recs.length){await carregarFotosPlanilha(recs);openSessDoc(recs[0].Sessao||sessaoDe(recs[0],recs),recs);}});
  L.querySelectorAll(".pbtn").forEach(b=>b.onclick=async()=>{const r=regBase().find(x=>x.ID_Auditoria===b.dataset.id);if(r){await carregarFotosPlanilha([r]);openPrint(r);}});
  L.querySelectorAll(".wbtn").forEach(b=>b.onclick=()=>{const r=allRecs().find(x=>x.ID_Auditoria===b.dataset.id);if(r){openPrint(r);sendWA(r,$("pv-wa"));}});
}
function cardCar(r){const cls=r.Motivo==="Sobras"?"tr":"nc";const fotos=r.fotos||[];
  return '<details class="rec '+cls+'"><summary><div class="top"><span>'+esc(r.DataHora)+' · '+esc(r.Nome_Auditor)+'</span><span>'+esc(r.Motivo)+'</span></div>'+
   '<div class="addr">Box '+esc(r.Box)+' · O.S. '+esc(r.Numero_OS)+'</div><div class="desc">'+esc(r.Codigo_Produto)+' – '+esc(r.Descricao_Produto)+'</div>'+
   '<div class="tags"><span class="tag '+(r.Motivo==="Sobras"?"":"nc")+'">'+esc(r.Motivo)+'</span><span class="tag">'+esc(r.Quantidade)+' un</span><span class="tag">'+BRL.format(+r.Valor_Total||0)+'</span></div></summary>'+
   '<dl><dt>ID</dt><dd>'+esc(r.ID_Auditoria)+'</dd><dt>Conferente</dt><dd>'+esc(r.Nome_Conferente)+' ('+esc(r.Matricula_Conferente)+')</dd>'+(r.Causador?'<dt>Causador</dt><dd>'+esc(r.Causador)+': '+esc(r.Nome_Causador)+' ('+esc(r.Matricula_Causador)+')</dd>':'')+'</dl>'+
   (fotos.length?'<div class="pics">'+fotos.map(s=>'<img src="'+s+'" alt="Foto da sobra">').join("")+'</div>':'')+
   (r.Sessao?'<button type="button" class="btn full cgrel" data-s="'+esc(r.ID_Sessao)+'" style="margin-top:8px">Relatório da carga – O.S. '+esc(r.Numero_OS)+'</button>':'')+'</details>';}
function cardRet(r){const st=r.Status_NC,cls=st==="Conforme"||st==="Resolvida"?"ok":st==="Em Tratativa"?"tr":"nc";const tags=[];if(r.Prox_Vencimento)tags.push("Vence "+r.Data_Vencimento);if(r.Retorno_NC||(r.Possui_NC&&!r.Prox_Vencimento&&!+r.Divergencia_Un))tags.push("Retorno não conforme");
  const fotos=[r.foto_retorno,r.foto_etiqueta].filter(Boolean);
  return '<details class="rec '+cls+'"><summary><div class="top"><span>'+esc(r.DataHora)+' · '+esc(r.Nome_Auditor)+'</span><span>'+esc(st)+'</span></div>'+
   '<div class="addr">Rua '+esc(r.Rua)+'</div><div class="desc">'+esc(r.Produto)+' – '+esc(r.Descricao_Produto)+'</div>'+
   '<div class="tags"><span class="tag '+cls+'">'+esc(st)+'</span>'+tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join("")+
   (r.Qtd_Fisico!=null&&r.Qtd_Fisico!==""?'<span class="tag">Etiq. '+esc(r.Qtd_Etiqueta)+' · Fís. '+esc(r.Qtd_Fisico)+'</span><span class="tag">'+BRL.format(+r.Valor_Total||0)+'</span>':'')+
   (+r.Divergencia_Un?'<span class="tag nc">Dif. '+(r.Divergencia_Un>0?'+':'')+esc(r.Divergencia_Un)+' un · '+BRL.format(+r.Valor_Divergencia||0)+'</span>':'')+'</div></summary>'+
   '<dl><dt>ID</dt><dd>'+esc(r.ID_Auditoria)+'</dd>'+(r.Possui_NC?'<dt>Responsável</dt><dd>'+esc(r.Nome_Colaborador_NC)+' ('+esc(r.Matricula_Colaborador_NC)+')</dd>':'')+(r.Observacao?'<dt>Obs.</dt><dd>'+esc(r.Observacao)+'</dd>':'')+'</dl>'+
   (fotos.length?'<div class="pics">'+fotos.map((s,i)=>'<img src="'+s+'" alt="'+(i?'Etiqueta':'Retorno')+'">').join("")+'</div>':'')+
   (r.Sessao&&r.ID_Sessao?'<button type="button" class="btn full rtrel" data-s="'+esc(r.ID_Sessao)+'" style="margin-top:8px">Relatório do retorno – rua '+esc(r.Sessao.rua)+'</button>':'')+'</details>';}
function card(r){
  const tags=[];if(r.Erro_Produto)tags.push("Lugar errado"+(r.Endereco_Correto?" (correto "+fmtAddr(r.Endereco_Correto)+")":""));if(r.Prox_Vencimento)tags.push("Vence "+r.Data_Vencimento);if(r.Sem_Saldo)tags.push("Sem saldo");if(r.Avaria)tags.push("Avaria: "+r.Tipo_Avaria);
  const st=r.Status_NC,cls=st==="Conforme"||st==="Resolvida"?"ok":st==="Em Tratativa"?"tr":"nc";
  return '<details class="rec '+cls+'"><summary><div class="top"><span>'+esc(r.DataHora)+' · '+esc(r.Nome_Auditor)+'</span><span>'+(r._pend&&dbState!=="off"?"Aguardando envio":esc(st))+'</span></div>'+
   '<div class="addr">'+esc(fmtAddr(r.Endereco))+'</div><div class="desc">'+esc(r.Produto)+' – '+esc(r.Descricao_Produto)+'</div>'+
   '<div class="tags"><span class="tag '+cls+'">'+esc(st)+'</span>'+tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join("")+(r.Possui_NC?'<span class="tag nc">'+esc(r.Qtd_Divergencia_Un)+' un · '+BRL.format(r.Valor_Divergencia||0)+'</span>':'')+'</div></summary>'+
   '<dl><dt>ID</dt><dd>'+esc(r.ID_Auditoria)+'</dd>'+(r.Possui_NC?'<dt>Repositor</dt><dd>'+esc(r.Nome_Colaborador_NC)+' ('+esc(r.Matricula_Colaborador_NC)+')</dd><dt>Cálculo</dt><dd>'+esc(r.Qtd_Divergencia_Un)+' un × R$ '+VL4.format(r.Vl_Ult_Entrada||0)+'</dd>':'')+
   (r.Observacao?'<dt>Obs.</dt><dd>'+esc(r.Observacao)+'</dd>':'')+'</dl>'+((r.fotos&&r.fotos.length)||r.foto?'<div class="pics">'+((r.fotos&&r.fotos.length)?r.fotos:[r.foto]).map((s,i)=>'<img src="'+s+'" alt="Foto '+(i+1)+' de '+esc(fmtAddr(r.Endereco))+'">').join("")+'</div>':'')+(r.Possui_NC?'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px"><button type="button" class="btn pbtn" data-id="'+esc(r.ID_Auditoria)+'">Imprimir NC</button><button type="button" class="btn wbtn" data-id="'+esc(r.ID_Auditoria)+'" style="background:#1E8E4E;border-color:#1E8E4E;color:#fff">PDF no WhatsApp</button></div>':'')+(r.ID_Sessao&&r.Sessao?'<button type="button" class="btn full rbtn" data-s="'+esc(r.ID_Sessao)+'" style="margin-top:8px">Relatório da rua '+esc(r.Sessao.rua)+'</button>':'')+'</details>';
}
const COLS=["ID_Auditoria","DataHora","Matricula_Auditor","Nome_Auditor","Produto","Descricao_Produto","Endereco","Rua","Predio","Nivel","Apto","Erro_Produto","Endereco_Correto","Prox_Vencimento","Data_Vencimento","Sem_Saldo","Avaria","Tipo_Avaria","Foto_Avaria","Qtd_Divergencia_Un","Vl_Ult_Entrada","Valor_Divergencia","Observacao","Possui_NC","Matricula_Colaborador_NC","Nome_Colaborador_NC","Funcao_Colaborador_NC","Status_NC","Responsavel_Tratativa","Acao_Corretiva","Data_Resolucao","Ultima_Atualizacao"];
function cell(v){if(v===true)return "TRUE";if(v===false)return "FALSE";if(typeof v==="number")v=String(v).replace(".",",");v=v==null?"":String(v);return /[;"\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;}
function norm2(r){const o=Object.assign({},r);["Endereco","Endereco_Correto"].forEach(k=>o[k]=fmtAddr(o[k]));["Rua","Predio","Nivel","Apto"].forEach(k=>o[k]=unz(o[k]));
  if(typeof o.Vl_Ult_Entrada==="number")o.Vl_Ult_Entrada=Math.round(o.Vl_Ult_Entrada*100)/100;if(typeof o.Valor_Divergencia==="number")o.Valor_Divergencia=Math.round(o.Valor_Divergencia*100)/100;return o;}
const RET_COLS=["ID_Auditoria","DataHora","Matricula_Auditor","Nome_Auditor","Produto","Descricao_Produto","Rua","Prox_Vencimento","Data_Vencimento","Foto_Retorno","Foto_Etiqueta","Qtd_Etiqueta","Qtd_Fisico","Observacao","Possui_NC","Matricula_Colaborador_NC","Nome_Colaborador_NC","Funcao_Colaborador_NC","Status_NC","Responsavel_Tratativa","ID_Sessao","Vl_Ult_Entrada","Valor_Total","Divergencia_Un","Valor_Divergencia","Numero_OS"];
const CAR_COLS=["ID_Auditoria","DataHora","Matricula_Auditor","Nome_Auditor","Matricula_Conferente","Nome_Conferente","Box","Numero_OS","Codigo_Produto","Descricao_Produto","Quantidade","Motivo","Causador","Matricula_Causador","Nome_Causador","Valor_Total","ID_Sessao"];
function csv(){const ab=$("f-aba").value,cols=ab==="retorno"?RET_COLS:ab==="cargas"?CAR_COLS:ab==="aero"?AER_COLS:COLS;return "\ufeff"+[cols.join(";")].concat(filtered().slice().reverse().map(r=>{const o=norm2(r);return cols.map(c=>cell(o[c])).join(";");})).join("\r\n");}
$("x-ruas").onclick=async()=>{
  if($("f-aba").value==="todas"){toast("Escolha um tipo de auditoria para baixar o CSV.");return;}
  if(!filtered().length){toast("Nenhuma auditoria no período escolhido.");return;}
  const name=({retorno:"Auditoria_Retorno_",cargas:"Auditoria_Cargas_",aero:"Auditoria_Aero_"}[$("f-aba").value]||"Auditoria_Ruas_")+todayISO()+".csv",data=csv();
  if(downloads){try{await downloads.save({filename:name,data:new Blob([data],{type:"text/csv"})});return;}catch(e){if(e&&e.code==="declined")return;if(e&&e.code==="rate_limited"){toast("Aguarde um instante e tente de novo.");return;}}}
  if(!window.claude){try{const u=URL.createObjectURL(new Blob([data],{type:"text/csv;charset=utf-8"}));const l=document.createElement("a");l.href=u;l.download=name;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);toast("CSV baixado.");return;}catch(e){}}
  const a=$("copy-area");a.innerHTML='<label class="lbl" for="cp">Copie o conteúdo abaixo e cole no Google Planilhas (Dados → Dividir texto em colunas, separador ponto e vírgula).</label><textarea class="in copybox" id="cp" readonly></textarea><button type="button" class="btn full" id="cpb" style="margin-top:8px">Copiar</button>';
  $("cp").value=data.slice(1);
  $("cpb").onclick=async()=>{try{await navigator.clipboard.writeText($("cp").value);toast("Copiado.");}catch(e){$("cp").select();toast("Selecionado: use Copiar do teclado.");}};
};
