// atualização das bases
const nz=s=>norm(String(s==null?"":s)).replace(/[^A-Z0-9]/g,"");
function cellStr(v){if(v==null)return "";if(typeof v==="number")return Number.isInteger(v)?String(v):String(v);return String(v).trim();}
function cellNum(v){if(typeof v==="number")return v;const s=String(v==null?"":v).trim();if(!s)return 0;const n=s.includes(",")?parseFloat(s.replace(/\./g,"").replace(",",".")):parseFloat(s);return isNaN(n)?0:n;}
function findHeader(rows,need){for(let i=0;i<Math.min(rows.length,40);i++){const h=(rows[i]||[]).map(nz);if(need.every(f=>h.some(f)))return {i,h};}return null;}
const XLSX_URL="lib/xlsx.full.min.js";
async function readSheet(file){if(!window.XLSX){try{await loadScript(XLSX_URL);}catch(e){throw new Error("Para ler o Excel é preciso internet na primeira vez. Conecte e tente de novo.");}}const buf=await file.arrayBuffer();const wb=XLSX.read(buf,{type:"array",dense:true});const ws=wb.Sheets[wb.SheetNames[0]];return XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:""});}
function parse286(rows){
  const isCod=x=>x==="CODIGO"||x==="COD"||x==="CODPROD",isDesc=x=>x==="DESCRICAO"||x==="DESCRICAOPRODUTO",isVl=x=>x.includes("ULT")&&x.includes("ENTRADA");
  const H=findHeader(rows,[isCod,isDesc,isVl]);if(!H)throw new Error("Não encontrei as colunas Código, Descrição e Vl. ult. entrada.");
  const ci=H.h.findIndex(isCod),di=H.h.findIndex(isDesc),vi=H.h.findIndex(isVl);const out=[],seen=new Set();
  for(let r=H.i+1;r<rows.length;r++){const row=rows[r];const c=cellStr(row[ci]).replace(/\.0+$/,"");if(!c||!/^\d+$/.test(c)||seen.has(c))continue;seen.add(c);
    out.push(c+"\t"+cellStr(row[di]).replace(/[\t\n\r]/g," ")+"\t"+(Math.round(cellNum(row[vi])*100)/100).toFixed(2));}
  if(!out.length)throw new Error("Nenhum item encontrado no arquivo.");return out.join("\n");}
function parse8022(rows){
  const f=n=>x=>x===n;const H=findHeader(rows,[f("CODPROD"),f("RUA"),f("PREDIO"),f("NIVEL"),f("APTO")]);
  if(!H)throw new Error("Não encontrei as colunas CODPROD, RUA, PREDIO, NIVEL e APTO.");
  const ix=n=>H.h.indexOf(n),cp=ix("CODPROD"),ru=ix("RUA"),pr=ix("PREDIO"),ni=ix("NIVEL"),ap=ix("APTO"),qt=ix("QTUNITCX");const out=[],seen=new Set();
  for(let r=H.i+1;r<rows.length;r++){const row=rows[r];const p=[row[ru],row[pr],row[ni],row[ap]].map(cellNum);if(p.some(x=>!x&&x!==0)||!cellStr(row[ru]))continue;
    const id=p.map(x=>String(Math.round(x))).join("-");if(seen.has(id))continue;seen.add(id);
    out.push({k:p,l:id+"\t"+cellStr(row[cp]).replace(/\.0+$/,"")+"\t"+(qt>=0?Math.round(cellNum(row[qt])):0)});}
  if(!out.length)throw new Error("Nenhum endereço encontrado no arquivo.");
  out.sort((a,b)=>a.k[0]-b.k[0]||a.k[1]-b.k[1]||a.k[2]-b.k[2]||a.k[3]-b.k[3]);return out.map(x=>x.l).join("\n");}
let BASEINFO={p:null,e:null};
function fmtWhen(ts){return ts?fmtDT(new Date(ts)).slice(0,16):"";}
function paintBases(){if($("bs-n")){$("bs-n").textContent=(typeof SOBRAS!=="undefined"?SOBRAS.length:0).toLocaleString("pt-BR");$("bs-src").textContent=typeof SOBINFO!=="undefined"&&SOBINFO?"Atualizada em "+fmtWhen(SOBINFO.ts)+" ("+SOBINFO.nome+")":"Nenhuma rotina carregada";}
  if($("bq-n")){$("bq-n").textContent=C.mat.length.toLocaleString("pt-BR");$("bq-src").textContent=BASEINFO.c?"Atualizada em "+fmtWhen(BASEINFO.c.ts)+" ("+BASEINFO.c.nome+")":"Base original do formulário";
    $("br-n").textContent=ROTINA.length.toLocaleString("pt-BR");const ds=[...new Set(ROTINA.map(a=>a[0]).filter(Boolean))].sort();$("br-src").textContent=ROTINA.length?(ROTINFO&&ROTINFO.nome?ROTINFO.nome+" · ":"")+(ds.length?ds[0].split("-").reverse().join("/")+(ds.length>1?" a "+ds[ds.length-1].split("-").reverse().join("/"):""):""):"Nenhuma rotina carregada";}
  $("b286-n").textContent=P.cod.length.toLocaleString("pt-BR");$("b8022-n").textContent=E.id.length.toLocaleString("pt-BR");
  $("b286-src").textContent=BASEINFO.p?"Atualizada em "+fmtWhen(BASEINFO.p.ts)+" ("+BASEINFO.p.nome+")":"Base original do formulário";
  $("b8022-src").textContent=BASEINFO.e?"Atualizada em "+fmtWhen(BASEINFO.e.ts)+" ("+BASEINFO.e.nome+")":"Base original do formulário";paintSync();}
async function onBaseFile(kind,input){const file=input.files[0];input.value="";if(!file)return;const msg=$(kind==="p"?"b286-msg":"b8022-msg");
  msg.style.color="";msg.textContent="Lendo "+file.name+"… isso pode levar alguns segundos.";
  await new Promise(r=>setTimeout(r,50));
  try{const rows=await readSheet(file);const txt=kind==="p"?parse286(rows):parse8022(rows);
    const info={ts:Date.now(),nome:file.name};
    if(kind==="p"){loadP(txt);}else{loadE(txt);refreshRuas();}
    BASEINFO[kind]=info;try{await IDB.set("base_"+kind,{txt,info});}catch(e){}
    const n=kind==="p"?P.cod.length:E.id.length;msg.textContent="Base atualizada: "+n.toLocaleString("pt-BR")+(kind==="p"?" itens.":" endereços.");paintBases();paint();toast("Base "+(kind==="p"?"286":"8022")+" atualizada.");
  }catch(e){msg.style.color="var(--alert)";msg.textContent=(e&&e.message)||"Não foi possível ler o arquivo.";}}
$("b286-file").addEventListener("change",e=>onBaseFile("p",e.target));
$("b8022-file").addEventListener("change",e=>onBaseFile("e",e.target));
$("b-reset").onclick=async()=>{if(!confirm("Voltar às bases originais do formulário?"))return;loadP(RAW.p);loadE(RAW.e);refreshRuas();BASEINFO={p:null,e:null};
  loadC(RAW.c);aplicarExtras();reposRotina();BASEINFO.c=null;
  try{await IDB.rm("base_p");await IDB.rm("base_e");await IDB.rm("base_c");}catch(e){}$("b286-msg").textContent="";$("b8022-msg").textContent="";paintBases();toast("Bases originais restauradas.");};
(async()=>{
  try{const bp=await IDB.get("base_p");if(bp&&bp.txt){loadP(bp.txt);BASEINFO.p=bp.info;}}catch(e){}
  try{const be=await IDB.get("base_e");if(be&&be.txt){loadE(be.txt);refreshRuas();BASEINFO.e=be.info;}}catch(e){}
  try{const all=await IDB.all();(all||[]).forEach(r=>HIST.set(r.ID_Auditoria,r));}catch(e){}
  if(!(window.claude&&typeof window.claude.use==="function")&&queue.length){for(const x of queue){x.rec._sheet=false;await histPut(x.rec);}queue=[];saveQueue();}
  paintBases();renderRecords();sheetSync();
})();

// ---------- Painel de ruas ----------
const QUADRO_DEF=[["10003193","2,3"],["10003615","4"],["10001781","5,6,7"],["10003748","8,9"],["10003942","10,11"],["10003787","11,12"],["10003850","16,17"],["10003995","18,19"],["10002347","20,22"],["10003643","23"],["10003932","24"],["10003928","25,26"],["10003902","27,28"],["10003936","29,30"],["10004015","31,32"],["10003930","34,35"],["10003961","36,37"],["10003639","38,39,40"],["10003413","41,42"],["10003925","43,44"],["10003316","45,46"]];
const parseRuas=s=>String(s||"").split(/[^0-9]+/).filter(Boolean).map(x=>String(+x));
let QUADRO=store.get("audcd_quadro",null)||QUADRO_DEF.map(([m,r])=>({mat:m,ruas:parseRuas(r)}));
let QUADRO_PLANILHA=false;
function aplicarQuadroPlanilha(q){if(!Array.isArray(q)||!q.length)return;const L=q.map(x=>({mat:String(x[0]||"").trim(),nome:String(x[1]||"").trim(),ruas:parseRuas(x[3])})).filter(x=>x.mat&&x.ruas.length);if(!L.length)return;QUADRO=L;QUADRO_PLANILHA=true;store.set("audcd_quadro",QUADRO);}
function saveQuadro(){store.set("audcd_quadro",QUADRO);}
function repsDaRua(rua){rua=String(rua);return QUADRO.filter(q=>q.ruas.includes(rua)).map(q=>q.mat);}
const nomeC=m=>{if(cIdx.has(m))return C.nome[cIdx.get(m)];const q=QUADRO.find(x=>x.mat===m);return q&&q.nome?q.nome:m;};
const curto=n=>{const p=String(n).trim().split(/\s+/);return p.length>1?p[0]+" "+p[p.length-1]:String(n);};
let RUA_TOT=null;
function ruaTotMap(){if(RUA_TOT&&RUA_TOT._n===E.id.length)return RUA_TOT;const m={};E.pt.forEach((a,i)=>{if(!RUAS_FORA.has(a[0]))m[a[0]]=(m[a[0]]||0)+1;});Object.defineProperty(m,"_n",{value:E.id.length,enumerable:false});RUA_TOT=m;return m;}
const pbool=v=>v===true||/^(TRUE|VERDADEIRO|SIM|1)$/i.test(String(v==null?"":v).trim());
const pnum=v=>{if(typeof v==="number")return v;const s=String(v==null?"":v).replace(/[^\d,.-]/g,"");if(!s)return 0;return s.includes(",")?parseFloat(s.replace(/\./g,"").replace(",","."))||0:parseFloat(s)||0;};
function pts(v,fb){if(typeof v==="number")return v;const s=String(v||"");let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ ,T]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if(m)return new Date(+m[3],+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0)).getTime();const t=Date.parse(s);return isNaN(t)?(fb||0):t;}
const PESO={erro:6,venc:3,avaria:4,saldo:2};
const RUAS_FORA=new Set(["14","15","21","31","50","51","52","53","54"]);
function pesoRec(o){let p=0;if(pbool(o.Erro_Produto))p+=PESO.erro;if(pbool(o.Prox_Vencimento))p+=PESO.venc;if(pbool(o.Avaria))p+=PESO.avaria;if(pbool(o.Sem_Saldo))p+=PESO.saldo;return p||(pbool(o.Possui_NC)?1:0);}
function normRec(o){const end=fmtAddr(o.Endereco||"");const rua=unz(o.Rua)||end.split("-")[0]||"";
  return {id:String(o.ID_Auditoria||""),ts:o.ts?+o.ts:pts(o.DataHora,pts(o.Recebido_Em)),rua:String(rua),end,nc:pbool(o.Possui_NC),sess:String(o.ID_Sessao||""),
    mat:String(o.Matricula_Colaborador_NC||""),val:pnum(o.Valor_Divergencia),qtd:pnum(o.Qtd_Divergencia_Un),aud:o.Nome_Auditor||"",peso:pesoRec(o)};}
let PAINEL_ROWS=null,PAINEL_INFO="",painelMode="mes",ruaSel=null,painelBusy=false;
function painelRecs(){const m=new Map();(PAINEL_ROWS||[]).forEach(o=>{const r=normRec(o);if(r.id&&r.ts)m.set(r.id,r);});return [...m.values()];}
function ciclos(recs){const by={};
  recs.forEach(r=>{if(!r.rua||RUAS_FORA.has(r.rua))return;const d=new Date(r.ts);const day=d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());const k=r.rua+"|"+(r.sess||day);(by[k]=by[k]||{rua:r.rua,recs:[]}).recs.push(r);});
  const T=ruaTotMap(),pr={};
  Object.values(by).forEach(c=>{const ends=new Set(),nce=new Set(),pe={};let val=0,ts=Infinity,te=0;const auds=new Set();
    c.recs.forEach(r=>{ends.add(r.end);if(r.nc){nce.add(r.end);val+=r.val;pe[r.end]=Math.max(pe[r.end]||0,r.peso||1);}ts=Math.min(ts,r.ts);te=Math.max(te,r.ts);if(r.aud)auds.add(r.aud);});
    const tot=Math.max(T[c.rua]||0,ends.size)||1,pontos=Object.values(pe).reduce((a,b)=>a+b,0);Object.assign(c,{ts,te,aud:ends.size,nc:nce.size,pontos,tot,val,q:Math.max(0,1-pontos/tot),cob:Math.min(1,ends.size/tot),auditores:[...auds]});
    (pr[c.rua]=pr[c.rua]||[]).push(c);});
  Object.values(pr).forEach(a=>a.sort((x,y)=>x.ts-y.ts));return pr;}
function prever(vals){const v=vals.filter(x=>x!=null).slice(-6);if(!v.length)return null;if(v.length<2)return v[0];const n=v.length;let sx=0,sy=0,sxy=0,sxx=0;
  v.forEach((y,x)=>{sx+=x;sy+=y;sxy+=x*y;sxx+=x*x;});const b=(n*sxy-sx*sy)/(n*sxx-sx*sx||1),a=(sy-b*sx)/n;return Math.max(0,Math.min(1,a+b*n));}
function periodKey(ts,mode){const d=new Date(ts);if(mode==="mes")return d.getFullYear()+"-"+pad(d.getMonth()+1);const m=new Date(d.getFullYear(),d.getMonth(),d.getDate());m.setDate(m.getDate()-((m.getDay()+6)%7));return m.getFullYear()+"-"+pad(m.getMonth()+1)+"-"+pad(m.getDate());}
const MESES=["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];
function perLabel(k,mode){const p=k.split("-");return mode==="mes"?MESES[+p[1]-1]+"/"+p[0].slice(2):p[2]+"/"+p[1];}
function porPeriodo(pr,mode){const P={};Object.values(pr).forEach(cs=>{const last={};cs.forEach(c=>{last[periodKey(c.ts,mode)]=c;});
  Object.entries(last).forEach(([k,c])=>{const x=P[k]=P[k]||{k,nc:0,pt:0,tot:0,ruas:0,val:0};x.nc+=c.nc;x.pt+=c.pontos||0;x.tot+=c.tot;x.ruas++;x.val+=c.val;});});
  return Object.values(P).sort((a,b)=>a.k<b.k?-1:1).map(p=>(p.q=Math.max(0,1-p.pt/p.tot),p));}
const qClass=q=>{if(q==null)return "q-na";q*=100;return q>=98?"q5":q>=95?"q4":q>=90?"q3":q>=80?"q2":"q1";};
const pct=q=>q==null?"–":(Math.round(q*1000)/10).toLocaleString("pt-BR",{minimumFractionDigits:1})+"%";
const pp=d=>(d>0?"+":"")+(Math.round(d*1000)/10).toLocaleString("pt-BR",{minimumFractionDigits:1})+" p.p.";
function seta(d){if(d==null)return "";return Math.abs(d)<0.0005?"=":d>0?"▲":"▼";}
function chartSVG(per,prevq,mode){const L=per.slice(-8);if(!L.length)return '<div class="empty">Ainda não há auditorias para comparar.</div>';
  const it=L.map(p=>({lab:perLabel(p.k,mode),q:p.q,sub:p.ruas+(p.ruas>1?" ruas":" rua")})).concat(prevq!=null?[{lab:"Previsão",q:prevq,f:true}]:[]);
  const mn=Math.min(...it.map(i=>i.q));const lo=Math.max(0,Math.min(0.9,Math.floor((mn-0.02)*20)/20));
  const W=340,H=190,pl=34,pb=34,pt=18,bw=(W-pl-4)/it.length,y=q=>pt+(1-(q-lo)/(1-lo))*(H-pt-pb);
  let s='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Qualidade por período">';
  [lo,(lo+1)/2,1].forEach(g=>{s+='<line x1="'+pl+'" x2="'+W+'" y1="'+y(g)+'" y2="'+y(g)+'" stroke="currentColor" stroke-opacity=".15"/><text x="'+(pl-4)+'" y="'+(y(g)+3)+'" font-size="9" text-anchor="end">'+Math.round(g*100)+'%</text>';});
  it.forEach((i,k)=>{const x=pl+k*bw+4,w=Math.max(6,bw-8),yy=y(Math.max(i.q,lo)),h=H-pb-yy;
    s+=i.f?'<rect x="'+x+'" y="'+yy+'" width="'+w+'" height="'+h+'" rx="3" fill="none" stroke="var(--brand)" stroke-width="1.5" stroke-dasharray="4 3"/>'
          :'<rect class="c-'+qClass(i.q)+'" x="'+x+'" y="'+yy+'" width="'+w+'" height="'+h+'" rx="3"/>';
    s+='<text x="'+(x+w/2)+'" y="'+(yy-4)+'" font-size="9" text-anchor="middle" font-weight="600" style="fill:var(--ink)">'+pct(i.q).replace(",0%","%")+'</text>';
    s+='<text x="'+(x+w/2)+'" y="'+(H-pb+13)+'" font-size="9" text-anchor="middle">'+i.lab+'</text>';
    if(i.sub)s+='<text x="'+(x+w/2)+'" y="'+(H-pb+24)+'" font-size="8" text-anchor="middle">'+i.sub+'</text>';});
  return s+'</svg>';}
function ranking(pr){return QUADRO.map(q=>({q,ru:q.ruas.filter(r=>!RUAS_FORA.has(r))})).filter(o=>o.ru.length).map(({q,ru})=>{let nc=0,pt=0,tot=0,val=0,ppt=0,ptot=0,aud=0,last=0;
    ru.forEach(r=>{const cs=pr[r];if(!cs||!cs.length)return;const c=cs[cs.length-1];aud++;nc+=c.nc;pt+=c.pontos||0;tot+=c.tot;val+=c.val;last=Math.max(last,c.te);const p=cs[cs.length-2];if(p){ppt+=p.pontos||0;ptot+=p.tot;}});
    return {mat:q.mat,nome:nomeC(q.mat),ruas:ru,aud,q:tot?Math.max(0,1-pt/tot):null,pq:ptot?Math.max(0,1-ppt/ptot):null,nc,val,tot,last};})
  .sort((a,b)=>(a.q==null)-(b.q==null)||(b.q||0)-(a.q||0)||a.val-b.val);}
function renderPainel(){
  const box=$("painel");if(!box)return;
  const recs=painelRecs(),pr=ciclos(recs),T=ruaTotMap();
  const ruasAll=[...new Set(Object.keys(T).concat(QUADRO.flatMap(q=>q.ruas)).concat(Object.keys(pr)))].filter(r=>!RUAS_FORA.has(r)).sort((a,b)=>a-b);
  let nc=0,tot=0,val=0,aud=0,ruasBase=Object.keys(T).length;
  ruasAll.forEach(r=>{const cs=pr[r];if(!cs)return;const c=cs[cs.length-1];nc+=c.nc;tot+=c.tot;val+=c.val;aud++;});
  const qg=tot?1-nc/tot:null,per=porPeriodo(pr,painelMode),prevq=prever(per.map(p=>p.q));
  const lastP=per[per.length-1],prevP=per[per.length-2];
  const semRep=Object.keys(T).filter(r=>!repsDaRua(r).length).sort((a,b)=>a-b);
  let h='<div class="src"><span id="pn-info">'+esc(PAINEL_INFO||"Carregando a base do Google Sheets…")+'</span><button type="button" class="btn sm" id="pn-upd">Atualizar</button></div>';
  const pend=sheetPending();if(pend)h+='<p class="note" style="margin:-4px 0 10px">'+(pend>1?pend+' lançamentos deste aparelho ainda não chegaram à planilha e entram no painel assim que forem enviados.':'1 lançamento deste aparelho ainda não chegou à planilha e entra no painel assim que for enviado.')+'</p>';
  if(!PAINEL_ROWS){box.innerHTML=h+'<div class="empty">O painel é alimentado pela base do Google Sheets.<br>'+(navigator.onLine?'Toque em Atualizar para carregar.':'Conecte-se à internet para carregar a primeira vez.')+'</div>';$("pn-upd").onclick=()=>carregarPainel(true);return;}
  h+='<div class="kpis"><div class="kpi"><b class="'+qClass(qg)+'-t">'+pct(qg)+'</b><span>qualidade geral (último ciclo de cada rua)</span></div>'+
     '<div class="kpi"><b>'+aud+' / '+ruasBase+'</b><span>ruas auditadas</span></div>'+
     '<div class="kpi"><b>'+nc+'</b><span>endereços com NC (último ciclo)</span></div>'+
     '<div class="kpi"><b>'+BRL.format(val).replace(",00","")+'</b><span>valor em divergência</span></div></div>';
  // mapa
  h+='<div class="block"><h3>Mapa de ruas <small>toque numa rua</small></h3><div class="rgrid">'+ruasAll.map(r=>{const cs=pr[r]||[],c=cs[cs.length-1],p=cs[cs.length-2],d=c&&p?c.q-p.q:null;
      return '<button type="button" class="rq '+qClass(c?c.q:null)+(ruaSel===r?' sel':'')+'" data-r="'+r+'" aria-label="Rua '+r+' qualidade '+(c?pct(c.q):'sem auditoria')+'"><i>'+seta(d)+'</i><b>'+r+'</b><span>'+(c?pct(c.q):'—')+'</span></button>';}).join("")+'</div>'+
    '<div class="leg"><span><i class="q5"></i>≥ 98%</span><span><i class="q4"></i>95–98%</span><span><i class="q3"></i>90–95%</span><span><i class="q2"></i>80–90%</span><span><i class="q1"></i>&lt; 80%</span><span><i class="q-na"></i>sem auditoria</span></div>'+
    '<p class="note">Qualidade = 1 − (pontos das ocorrências ÷ endereços da rua na 8022). Pesos: picking errado 6, avaria 4, vencimento 3, sem saldo 2. ▲▼ comparam com a auditoria anterior da rua.</p><div id="pn-rua"></div></div>';
  // evolução
  h+='<div class="block"><h3>Evolução e previsão</h3><div class="seg" role="group" aria-label="Agrupar por"><button type="button" data-pm="semana" aria-pressed="'+(painelMode==="semana")+'">Por semana</button><button type="button" data-pm="mes" aria-pressed="'+(painelMode==="mes")+'">Por mês</button></div>'+
     '<div class="chart">'+chartSVG(per,prevq,painelMode)+'</div>'+
     (lastP?'<p class="note" style="margin-top:6px">'+(prevP?'Período atual '+pct(lastP.q)+' ('+pp(lastP.q-prevP.q)+' vs anterior). ':'Primeiro período registrado. ')+
       (prevq!=null?'Previsão para o próximo período: <b>'+pct(prevq)+'</b>'+(lastP?', tendência '+(prevq>lastP.q+0.0005?'de melhora':prevq<lastP.q-0.0005?'de piora':'estável')+'.':'.'):'')+' A previsão usa a tendência dos últimos 6 períodos.</p>':'')+'</div>';
  // ranking
  const rk=ranking(pr);
  h+='<div class="block"><h3>Ranking de repositores <small>último ciclo das ruas</small></h3>'+rk.map((x,i)=>{const pos=x.q==null?'–':(i+1)+'º';const d=x.q!=null&&x.pq!=null?x.q-x.pq:null;
      return '<div class="rk"><div class="pos">'+pos+'</div><div><div class="nm">'+esc(curto(x.nome))+'</div><div class="sm">Ruas '+x.ruas.join(", ")+' · '+x.aud+' de '+x.ruas.length+' auditada'+(x.ruas.length>1?'s':'')+'</div>'+
        '<div class="bar"><i class="'+qClass(x.q)+'" style="width:'+(x.q==null?0:Math.round(x.q*100))+'%"></i></div>'+
        '<div class="sm">'+(x.q==null?'Sem auditoria ainda':x.nc+' NC · '+BRL.format(x.val)+(d!=null?' · '+seta(d)+' '+pp(d):''))+'</div></div><div class="qv '+qClass(x.q)+'-t">'+pct(x.q)+'</div></div>';}).join("")+
     (semRep.length?'<p class="note">Ruas sem repositor no quadro: '+semRep.join(", ")+'.</p>':'')+'</div>';
  // quadro
  if(QUADRO_PLANILHA){h+='<details class="block" id="pn-quadro"><summary style="cursor:pointer;font-weight:600;color:var(--brand)">Quadro de repositores ('+QUADRO.length+')</summary><p class="note">Vem da aba <b>Quadro_Repositores</b> da planilha. Para mudar ruas ou repositores, edite lá e toque em Atualizar.</p>'+
     QUADRO.map(q=>'<div class="qe" style="grid-template-columns:1fr auto"><div><b>'+esc(curto(nomeC(q.mat)))+'</b><div style="color:var(--muted);font-size:.78rem">'+esc(q.mat)+'</div></div><div>Ruas '+esc(q.ruas.join(", "))+'</div></div>').join("")+'</details>';
    const wo=$("pn-quadro")&&$("pn-quadro").open;box.innerHTML=h;if(wo)$("pn-quadro").open=true;bindPainel(box,pr,T);return;}
  h+='<details class="block" id="pn-quadro"><summary style="cursor:pointer;font-weight:600;color:var(--brand)">Quadro de repositores ('+QUADRO.length+')</summary><p class="note">Ruas de cada repositor, separadas por vírgula. Usado no ranking e para preencher o repositor ao iniciar uma rua.</p>'+
     QUADRO.map((q,i)=>'<div class="qe"><div><b>'+esc(curto(nomeC(q.mat)))+'</b><div class="sm" style="color:var(--muted);font-size:.78rem">'+esc(q.mat)+'</div></div><input class="in" data-qi="'+i+'" value="'+esc(q.ruas.join(", "))+'" inputmode="numeric" aria-label="Ruas de '+esc(nomeC(q.mat))+'"><button type="button" class="btn sm" data-qx="'+i+'" aria-label="Remover">×</button></div>').join("")+
     '<div class="field"><label>Adicionar repositor</label><div id="qa-pick"></div><input class="in" id="qa-ruas" placeholder="Ruas, ex.: 13, 14" inputmode="numeric" style="margin-top:6px"><button type="button" class="btn full" id="qa-add" style="margin-top:6px">Adicionar ao quadro</button></div>'+
     '<button type="button" class="btn full" id="qa-reset" style="margin-top:8px">Restaurar quadro padrão</button></details>';
  const wasOpen=$("pn-quadro")&&$("pn-quadro").open;
  box.innerHTML=h;if(wasOpen)$("pn-quadro").open=true;
  bindPainel(box,pr,T);
  box.querySelectorAll("[data-qi]").forEach(inp=>inp.onchange=()=>{QUADRO[+inp.dataset.qi].ruas=parseRuas(inp.value);saveQuadro();renderPainel();toast("Quadro atualizado.");});
  box.querySelectorAll("[data-qx]").forEach(b=>b.onclick=()=>{const q=QUADRO[+b.dataset.qx];if(!confirm("Remover "+curto(nomeC(q.mat))+" do quadro?"))return;QUADRO.splice(+b.dataset.qx,1);saveQuadro();renderPainel();});
  const qp=picker($("qa-pick"),{ph:"Matrícula ou nome",search:searchColab,describe:descColab});
  $("qa-add").onclick=()=>{if(qp.value==null){toast("Escolha o colaborador.");return;}const m=C.mat[qp.value],ru=parseRuas($("qa-ruas").value);if(!ru.length){toast("Informe as ruas.");return;}
    const ex=QUADRO.find(q=>q.mat===m);if(ex)ex.ruas=[...new Set(ex.ruas.concat(ru))];else QUADRO.push({mat:m,ruas:ru});saveQuadro();renderPainel();toast("Repositor adicionado ao quadro.");};
  $("qa-reset").onclick=()=>{if(!confirm("Voltar ao quadro padrão de repositores?"))return;QUADRO=QUADRO_DEF.map(([m,r])=>({mat:m,ruas:parseRuas(r)}));saveQuadro();renderPainel();};
}
function bindPainel(box,pr,T){
  box.querySelectorAll(".rq").forEach(b=>b.onclick=()=>{ruaSel=ruaSel===b.dataset.r?null:b.dataset.r;renderPainel();if(ruaSel)$("pn-rua").scrollIntoView({block:"nearest",behavior:"smooth"});});
  box.querySelectorAll("[data-pm]").forEach(b=>b.onclick=()=>{painelMode=b.dataset.pm;renderPainel();});
  $("pn-upd").onclick=()=>carregarPainel(true);
  // detalhe da rua
  if(ruaSel){const r=ruaSel,cs=pr[r]||[],reps=repsDaRua(r).map(m=>curto(nomeC(m))).join(" e ")||"sem repositor no quadro";const pv=prever(cs.map(c=>c.q));
    $("pn-rua").innerHTML='<div class="block" style="margin:12px 0 0;border-color:var(--brand)"><h3>Rua '+esc(r)+' <small>'+(T[r]||0)+' endereços na 8022</small></h3><p class="note" style="margin-top:0">Repositor: <b>'+esc(reps)+'</b></p>'+
      (cs.length?'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Data</th><th class="n">Audit.</th><th class="n">NC</th><th class="n">Qualid.</th><th class="n">Δ</th></tr></thead><tbody>'+
        cs.slice().reverse().map((c,i,a)=>{const p=a[i+1];const d=p?c.q-p.q:null;return '<tr><td>'+fmtDT(new Date(c.ts)).slice(0,10)+'</td><td class="n">'+c.aud+' <small>('+pct(c.cob).replace(/,\d%$/,"%")+')</small></td><td class="n">'+c.nc+'</td><td class="n"><b>'+pct(c.q)+'</b></td><td class="n">'+(d==null?'–':seta(d)+' '+pp(d).replace(" p.p.",""))+'</td></tr>';}).join("")+
        '</tbody></table></div><p class="note">Previsão para a próxima auditoria: <b>'+pct(pv)+'</b>. Valor em divergência no último ciclo: '+BRL.format(cs[cs.length-1].val)+'.</p>':'<p class="note">Rua ainda não auditada.</p>')+'</div>';}
}
async function carregarPainel(manual){
  if(painelBusy)return;
  if(!SHEET_URL||window.claude){PAINEL_INFO=window.claude?"Pelo link do Claude o painel não acessa a planilha. Use o site.":"Planilha não configurada.";renderPainel();return;}
  if(!navigator.onLine){PAINEL_INFO=PAINEL_ROWS?"Sem internet: mostrando a última cópia da planilha.":"Sem internet.";renderPainel();return;}
  painelBusy=true;const inf=$("pn-info");if(inf)inf.textContent="Atualizando com a planilha…";
  try{const r=await fetch(SHEET_URL+(SHEET_URL.includes("?")?"&":"?")+"acao=registros&token="+encodeURIComponent((LOGIN&&LOGIN.token)||"")+"&t="+Date.now(),{cache:"no-store"});const j=await r.json();
    if(j&&j.ok&&Array.isArray(j.registros)){PAINEL_ROWS=j.registros.map(row=>{const o={};j.colunas.forEach((c,i)=>o[c]=row[i]);return o;});aplicarQuadroPlanilha(j.quadro);
      PAINEL_INFO="Planilha Google ("+PAINEL_ROWS.length+" lançamentos) · "+fmtDT(new Date()).slice(0,16);IDB.set("painel_cache",{rows:PAINEL_ROWS,info:PAINEL_INFO,quadro:j.quadro||null}).catch(()=>{});
      if(manual)toast("Painel atualizado com a planilha.");}
    else PAINEL_INFO="O Apps Script precisa da versão 5 para alimentar o painel (veja as instruções).";
  }catch(e){PAINEL_INFO=PAINEL_ROWS?"Sem conexão com a planilha: mostrando a última cópia.":"Sem conexão com a planilha.";}
  painelBusy=false;renderPainel();
}
IDB.get("painel_cache").then(c=>{if(c&&c.rows&&!PAINEL_ROWS){PAINEL_ROWS=c.rows;aplicarQuadroPlanilha(c.quadro);PAINEL_INFO="Última cópia da planilha: "+String(c.info||"").split("· ").pop();}}).catch(()=>{});
setInterval(()=>{if(!$("v-painel").hidden&&navigator.onLine&&!document.hidden)carregarPainel();},120000);

// administração de acessos
const PERM_NOME={aud_rua:"Ruas",aud_ret:"Retorno",aud_car:"Cargas",aud_adm:"Administração"};
const PERM_DESC={aud_rua:"Auditoria de ruas",aud_ret:"Auditoria de retorno",aud_car:"Auditoria de cargas",aud_adm:"Esta tela"};
let ADM={lista:null,perms:["aud_rua","aud_ret","aud_car","aud_adm"],filtro:"",novo:false,msg:"",busy:false};
async function admPost(body){const r=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify(Object.assign({token:LOGIN&&LOGIN.token},body)),redirect:"follow",cache:"no-store"});
  let j=null;try{j=await r.json();}catch(e){throw new Error("O Apps Script não respondeu. Confira se a versão 7 está implantada.");}if(!j.ok)throw new Error(j.erro||"Erro na planilha.");return j;}
async function carregarAdmin(){const box=$("adm");if(!temPerm("aud_adm")){box.innerHTML='<div class="empty">Sem permissão de administração.</div>';return;}
  if(DEMO){box.innerHTML='<div class="empty">A administração funciona pelo site, com login.</div>';return;}
  if(!navigator.onLine){box.innerHTML='<div class="empty">A administração precisa de internet para ler a aba Permissionamento.</div>';return;}
  if(!ADM.lista)box.innerHTML='<div class="empty">Carregando usuários da planilha…</div>';
  try{const j=await admPost({acao:"admin_listar"});ADM.lista=j.usuarios||[];if(j.permissoes&&j.permissoes.length)ADM.perms=j.permissoes;ADM.msg="";}catch(e){ADM.msg=e.message;}
  renderAdmin();}
function swHTML(per,on,st){return '<button type="button" class="sw" data-p="'+esc(per)+'" aria-pressed="'+on+'"><span>'+esc(PERM_NOME[per]||per)+'<small>'+(st==="Bloqueado"?"bloqueado":on?"liberado":"sem acesso")+'</small></span><i aria-hidden="true"></i></button>';}
function cardUsuario(u,idx){const ativo=Object.values(u.perms).some(s=>s==="Ativo");const nome=u.nome||(cIdx.has(u.matricula)?C.nome[cIdx.get(u.matricula)]:"");
  const perms=[...new Set(ADM.perms.concat(Object.keys(u.perms)))];
  return '<div class="block au" data-i="'+idx+'"><div class="au-h"><div><b>'+esc(nome||"Sem nome no quadro")+'</b><small>'+(u.matricula===LOGIN.mat?"você · ":"")+Object.keys(u.perms).length+' linha'+(Object.keys(u.perms).length>1?'s':'')+' na planilha</small></div><span class="chip '+(ativo?'on':'off')+'">'+(ativo?'Ativo':'Bloqueado')+'</span></div>'+
    '<div class="au-f"><div><label>Login (matrícula)</label><input class="in" data-f="mat" inputmode="numeric" value="'+esc(u.matricula)+'"></div>'+
    '<div><label>Senha</label><div class="pw"><input class="in" data-f="sen" type="password" value="'+esc(u.senha)+'" autocomplete="off"><button type="button" data-f="ver" aria-label="Mostrar senha">ver</button></div></div></div>'+
    '<div class="sws">'+perms.map(p=>swHTML(p,u.perms[p]==="Ativo",u.perms[p])).join("")+'</div>'+
    '<div class="au-b"><button type="button" class="btn" data-f="tudo">'+(ativo?'Bloquear tudo':'Liberar acessos')+'</button><button type="button" class="save" data-f="salvar" style="min-height:48px;font-size:1.15rem;margin:0" disabled>Salvar</button></div></div>';}
function renderAdmin(){const box=$("adm");if(!ADM.lista){box.innerHTML='<div class="empty">'+esc(ADM.msg||"Não foi possível carregar.")+'<br><button type="button" class="btn" id="adm-rt" style="margin-top:10px">Tentar de novo</button></div>';$("adm-rt").onclick=carregarAdmin;return;}
  const f=norm(ADM.filtro||"");const L=ADM.lista.map((u,i)=>[u,i]).filter(([u])=>!f||u.matricula.includes(f)||norm(u.nome||(cIdx.has(u.matricula)?C.nome[cIdx.get(u.matricula)]:"")).includes(f));
  let h='<button type="button" class="save" id="adm-fech" style="margin:0 0 12px">Fechamento das auditorias (KPIs e gráficos)</button>'+(ADM.msg?'<p class="err" style="margin:0 0 10px">'+esc(ADM.msg)+'</p>':'')+
    '<div class="adm-top"><input class="in" id="adm-q" type="search" placeholder="Buscar matrícula ou nome" value="'+esc(ADM.filtro)+'"><button type="button" class="btn" id="adm-novo">+ Novo</button></div>'+
    '<p class="note" style="margin:-4px 0 10px">'+ADM.lista.length+' usuário'+(ADM.lista.length!==1?'s':'')+'. As alterações são gravadas na aba <b>Permissionamento</b>. Bloquear mantém a linha na planilha com Status = Bloqueado.</p>';
  if(ADM.novo)h+='<div class="block au dirty" id="adm-new"><div class="au-h"><b>Novo usuário</b></div><div class="field" style="margin:0 0 8px"><label>Colaborador</label><div id="an-pick"></div></div>'+
    '<div class="au-f"><div><label>Login (matrícula)</label><input class="in" id="an-mat" inputmode="numeric"></div><div><label>Senha</label><input class="in" id="an-sen" autocomplete="off"></div></div>'+
    '<div class="sws">'+ADM.perms.map(p=>swHTML(p,false,"")).join("")+'</div>'+
    '<div class="au-b"><button type="button" class="btn" id="an-x">Cancelar</button><button type="button" class="save" id="an-ok" style="min-height:48px;font-size:1.15rem;margin:0">Criar acesso</button></div></div>';
  h+=L.length?L.map(([u,i])=>cardUsuario(u,i)).join(""):'<div class="empty">Nenhum usuário encontrado.</div>';
  box.innerHTML=h;
  $("adm-fech").onclick=()=>go("fechamento");
  $("adm-q").oninput=e=>{ADM.filtro=e.target.value;const pos=e.target.selectionStart;renderAdmin();const q=$("adm-q");q.focus();try{q.setSelectionRange(pos,pos);}catch(x){}};
  $("adm-novo").onclick=()=>{ADM.novo=true;renderAdmin();$("an-mat").focus();};
  if(ADM.novo){const nb=$("adm-new");const pk=picker($("an-pick"),{ph:"Buscar no quadro (opcional)",search:searchColab,describe:descColab,onPick:k=>{if(k!=null){$("an-mat").value=C.mat[k];const s="aud"+C.mat[k].slice(-4);if(!$("an-sen").value)$("an-sen").value=s;}}});
    nb.querySelectorAll(".sw").forEach(b=>b.onclick=()=>{b.setAttribute("aria-pressed",b.getAttribute("aria-pressed")!=="true");b.querySelector("small").textContent=b.getAttribute("aria-pressed")==="true"?"liberado":"sem acesso";});
    $("an-x").onclick=()=>{ADM.novo=false;renderAdmin();};
    $("an-ok").onclick=()=>{const perms={};nb.querySelectorAll(".sw").forEach(b=>perms[b.dataset.p]=b.getAttribute("aria-pressed")==="true");
      salvarUsuario({original:"",matricula:$("an-mat").value,senha:$("an-sen").value,perms},$("an-ok"));};}
  box.querySelectorAll(".au[data-i]").forEach(card=>{const u=ADM.lista[+card.dataset.i];const bt=card.querySelector('[data-f="salvar"]');
    const marcar=()=>{card.classList.add("dirty");bt.disabled=false;};
    card.querySelectorAll("input").forEach(i=>i.addEventListener("input",marcar));
    card.querySelector('[data-f="ver"]').onclick=e=>{const i=card.querySelector('[data-f="sen"]');const v=i.type==="password";i.type=v?"text":"password";e.target.textContent=v?"ocultar":"ver";e.target.style.fontSize=v?".62rem":"";};
    card.querySelectorAll(".sw").forEach(b=>b.onclick=()=>{const on=b.getAttribute("aria-pressed")!=="true";b.setAttribute("aria-pressed",on);b.querySelector("small").textContent=on?"liberado":(u.perms[b.dataset.p]?"bloqueado":"sem acesso");marcar();});
    card.querySelector('[data-f="tudo"]').onclick=()=>{const algum=[...card.querySelectorAll(".sw")].some(b=>b.getAttribute("aria-pressed")==="true");
      if(algum){card.querySelectorAll(".sw").forEach(b=>{b.setAttribute("aria-pressed","false");b.querySelector("small").textContent=u.perms[b.dataset.p]?"bloqueado":"sem acesso";});}
      else{Object.keys(u.perms).forEach(p=>{const b=card.querySelector('.sw[data-p="'+p+'"]');if(b){b.setAttribute("aria-pressed","true");b.querySelector("small").textContent="liberado";}});}
      marcar();};
    bt.onclick=()=>{const perms={};card.querySelectorAll(".sw").forEach(b=>perms[b.dataset.p]=b.getAttribute("aria-pressed")==="true");
      salvarUsuario({original:u.matricula,matricula:card.querySelector('[data-f="mat"]').value,senha:card.querySelector('[data-f="sen"]').value,perms},bt);};});
}
async function salvarUsuario(d,bt){d.matricula=String(d.matricula||"").replace(/\D/g,"");d.senha=String(d.senha||"").trim();
  if(!d.matricula){toast("Informe a matrícula.");return;}if(d.senha.length<4){toast("A senha precisa ter ao menos 4 caracteres.");return;}
  if(!d.original&&!Object.values(d.perms).some(Boolean)){toast("Libere ao menos um acesso.");return;}
  if(d.original&&d.original!==d.matricula&&!confirm("Trocar o login "+d.original+" por "+d.matricula+"? O usuário vai precisar entrar de novo."))return;
  if(!navigator.onLine){toast("Sem internet: não dá para salvar agora.");return;}
  const old=bt.textContent;bt.disabled=true;bt.textContent="Salvando…";
  try{await admPost(Object.assign({acao:"admin_salvar"},d));toast(d.original?"Acesso atualizado na planilha.":"Usuário criado na planilha.");ADM.novo=false;
    if(d.original===LOGIN.mat)setTimeout(revalidar,300);await carregarAdmin();}
  catch(e){toast(e.message);bt.disabled=false;bt.textContent=old;}}

// ---------- Fechamento (administração, computador) ----------
const hojeISO=()=>todayISO();
const iniMesISO=()=>{const d=new Date();return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-01";};
let FECH={tipo:"ruas",de:iniMesISO(),ate:hojeISO(),dados:null,info:"",busy:false,margem:6};
const BLOCOS=[["A",1,20],["B",21,30],["C",31,40],["D",41,50],["E",51,60]];
const fxCls=q=>q==null?"na":q>=.95?"ot":q>=.85?"rg":q>=.70?"at":"cr";
const FXC={ot:"#16A34A",rg:"#CA8A04",at:"#EA580C",cr:"#DC2626",na:"#94A3B8"};
const pc1=q=>q==null?"—":(Math.round(q*1000)/10).toLocaleString("pt-BR",{minimumFractionDigits:1})+"%";
const pc0=q=>q==null?"—":Math.round(q*100)+"%";
const fdISO=iso=>{if(!iso)return "";const [y,m,d]=iso.split("-");return d+"/"+m+"/"+y;};
const BRL0=v=>BRL.format(v||0);
function fxRows(blk){if(!blk||!Array.isArray(blk.registros)||!blk.colunas)return [];return blk.registros.map(r=>{const o={};blk.colunas.forEach((c,i)=>o[c]=r[i]);o.ts=pts(o.DataHora,pts(o.Recebido_Em));return o;}).filter(o=>o.ID_Auditoria&&o.ts);}
function fxPeriodo(){const de=FECH.de?dayStart(FECH.de):0,ate=FECH.ate?dayStart(FECH.ate)+864e5:Infinity;return [de,ate];}
function fxNoPeriodo(blk){const [de,ate]=fxPeriodo();return fxRows(blk).filter(o=>o.ts>=de&&o.ts<ate);}
const fxDia=ts=>{const d=new Date(ts);return pad(d.getDate())+"/"+pad(d.getMonth()+1);};
const fxDiaKey=ts=>{const d=new Date(ts);return d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate());};

/* ---- componentes ---- */
function fxHead(tit,n){return '<div class="fx-h"><div><h1>'+esc(tit)+'</h1><p>Período: <b>'+fdISO(FECH.de)+' a '+fdISO(FECH.ate)+'</b></p></div><div class="r">Gerado: <b>'+fmtDT(new Date())+'</b><br>Total de registros: <b>'+n+'</b></div></div>';}
function fxKpis(list,big){return '<div class="fx-k'+(big?' big':'')+'" style="grid-template-columns:repeat('+list.length+',1fr)">'+list.map(k=>'<div style="border-top-color:'+(k.c||"#1E40AF")+'"><span>'+k.t+'</span><b style="color:'+(k.c||"#1E40AF")+'">'+k.v+'</b>'+(k.s?'<small style="color:'+(k.sc||"#64748B")+'">'+k.s+'</small>':'')+'</div>').join("")+'</div>';}
function fxCard(t,body,extra){return '<div class="fx-c"'+(extra?' style="'+extra+'"':'')+'><h3>'+t+'</h3>'+body+'</div>';}
function fxBars(items,opt){opt=opt||{};if(!items.length)return '<p class="fx-e">Sem dados no período.</p>';
  const max=opt.max||Math.max(...items.map(i=>Math.abs(i.v)),1);
  return '<div class="fx-bars">'+items.map((it,i)=>'<div class="fx-br"><span class="n">'+(i+1)+'</span><span class="l" title="'+esc(it.l)+'">'+esc(it.l)+'</span><span class="t"><i style="width:'+Math.max(1,Math.round(Math.abs(it.v)/max*100))+'%;background:'+(it.c||"#2563EB")+'"></i></span><b style="color:'+(it.tc||it.c||"#1E3A8A")+'">'+it.txt+'</b></div>').join("")+'</div>';}
function fxCols(items){if(!items.length)return '<p class="fx-e">Sem dados no período.</p>';const max=Math.max(...items.map(i=>Math.abs(i.v)),1);
  return '<div class="fx-cols">'+items.map(it=>'<div><b>'+it.txt+'</b><i style="height:'+Math.max(2,Math.round(Math.abs(it.v)/max*100))+'%;background:'+(it.c||"#2563EB")+'"></i><span>'+esc(it.l)+'</span></div>').join("")+'</div>';}
function fxDonut(parts,centro){const tot=parts.reduce((a,p)=>a+p.v,0);if(!tot)return '<p class="fx-e">Sem dados no período.</p>';
  const R=40,C=2*Math.PI*R;let a=0;const segs=parts.filter(p=>p.v>0).map(p=>{const len=p.v/tot*C;const s='<circle r="'+R+'" cx="60" cy="60" fill="none" stroke="'+p.c+'" stroke-width="20" stroke-dasharray="'+len.toFixed(2)+' '+(C-len).toFixed(2)+'" stroke-dashoffset="'+(-a).toFixed(2)+'" transform="rotate(-90 60 60)"/>';a+=len;return s;}).join("");
  return '<div class="fx-don"><svg viewBox="0 0 120 120" width="118" height="118" role="img">'+segs+'<text x="60" y="58" text-anchor="middle" font-size="17" font-weight="700" fill="#0F172A">'+(centro!=null?centro:tot)+'</text><text x="60" y="73" text-anchor="middle" font-size="8" fill="#64748B">total</text></svg><ul>'+
    parts.map(p=>'<li><i style="background:'+p.c+'"></i>'+esc(p.l)+' <b>'+(p.txt||p.v)+'</b> <small>'+Math.round(p.v/tot*100)+'%</small></li>').join("")+'</ul></div>';}
function fxLegenda(){return '<div class="fx-leg"><b>LEGENDA:</b><span class="s-ot">● ≥95% Ótima</span><span class="s-rg">● 85–94% Regular</span><span class="s-at">● 70–84% Atenção</span><span class="s-cr">● &lt;70% Crítica</span><span class="s-na">Não auditada</span></div>';}
function fxMapa(qRua,rotulo){const T=ruaTotMap();const max=Math.max(50,...Object.keys(T).map(Number),...Object.keys(qRua).map(Number));
  return fxLegenda()+BLOCOS.filter(b=>b[1]<=max).map(([nm,a,z])=>{const rs=[];for(let r=a;r<=Math.min(z,max);r++)if(!RUAS_FORA.has(String(r))&&(r<=55||T[String(r)]))rs.push(String(r));if(!rs.length)return "";
    const qs=rs.map(r=>qRua[r]).filter(q=>q!=null);const med=qs.length?qs.reduce((x,y)=>x+y,0)/qs.length:null;
    return '<div class="fx-bl" style="color:'+(med==null?"#64748B":FXC[fxCls(med)])+'">Bloco '+nm+' <span>'+(med==null?"—":pc1(med))+'</span></div><div class="fx-sq">'+
      rs.map(r=>{const q=qRua[r];return '<div class="s-'+fxCls(q)+'"><span>'+r+'</span><small>'+(q==null?"—":pc0(q))+'</small></div>';}).join("")+'</div>';}).join("")+(rotulo?'<p class="fx-e" style="margin-top:8px">'+rotulo+'</p>':'');}
function fxChips(list){return list.length?'<div class="fx-chips">'+list.map(([r,q,extra])=>'<span class="s-'+fxCls(q)+'">Rua '+esc(r)+(extra?' '+esc(extra):'')+' &nbsp;'+pc1(q)+'</span>').join("")+'</div>':'<p class="fx-e">Nenhuma rua abaixo de 85% no período.</p>';}
function blocoDe(r){r=+r;const b=BLOCOS.find(([n,a,z])=>r>=a&&r<=z);return b?b[0]:"";}
function fxTable(head,rows){return rows.length?'<table class="fx-t"><thead><tr>'+head.map(h=>'<th'+(h.n?' class="n"':'')+'>'+h.t+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((c,i)=>'<td'+(head[i].n?' class="n"':'')+'>'+c+'</td>').join("")+'</tr>').join("")+'</tbody></table>':'<p class="fx-e">Sem dados no período.</p>';}
function fxFoot(tit){return '<div class="fx-f"><span>'+esc(tit)+' · Ciclo: '+fdISO(FECH.de)+' a '+fdISO(FECH.ate)+'</span><span>Gerado em '+fmtDT(new Date())+' · Santa Therezinha</span></div>';}
function porDia(rows,fn){const m={};rows.forEach(r=>{const k=fxDiaKey(r.ts);(m[k]=m[k]||{ts:r.ts,rows:[]}).rows.push(r);});return Object.keys(m).sort().slice(-14).map(k=>fn(m[k]));}

/* ---- gráfico de linha ---- */
function fxLine(pts,cor,unid,HH){if(!pts.length)return '<p class="fx-e">Sem dados.</p>';const W=1040,H=HH||170,pl=34,pr=10,pt=18,pb=26,mx=Math.max(...pts.map(p=>p.v),1);
  const x=i=>pl+(pts.length===1?(W-pl-pr)/2:i*(W-pl-pr)/(pts.length-1)),y=v=>pt+(1-v/mx)*(H-pt-pb);
  const grid=[0,.5,1].map(g=>'<line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y(mx*g)+'" y2="'+y(mx*g)+'" stroke="#E2E8F0"/><text x="'+(pl-5)+'" y="'+(y(mx*g)+3)+'" font-size="9" text-anchor="end" fill="#64748B">'+(unid==="%"?Math.round(mx*g*100)+"%":Math.round(mx*g))+'</text>').join("");
  const path=pts.map((p,i)=>(i?"L":"M")+x(i).toFixed(1)+" "+y(p.v).toFixed(1)).join(" ");const area=path+" L"+x(pts.length-1).toFixed(1)+" "+(H-pb)+" L"+x(0).toFixed(1)+" "+(H-pb)+" Z";
  const passo=Math.ceil(pts.length/16);
  return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block">'+grid+'<path d="'+area+'" fill="'+cor+'" fill-opacity=".10"/><path d="'+path+'" fill="none" stroke="'+cor+'" stroke-width="2.2" stroke-linejoin="round"/>'+
    pts.map((p,i)=>'<circle cx="'+x(i).toFixed(1)+'" cy="'+y(p.v).toFixed(1)+'" r="3" fill="'+(p.c||cor)+'"/>'+(p.v||pts.length<=20?'<text x="'+x(i).toFixed(1)+'" y="'+(y(p.v)-6).toFixed(1)+'" font-size="9" text-anchor="middle" fill="#0F172A" font-weight="700">'+(p.txt!=null?p.txt:p.v)+'</text>':'')+
      (i%passo===0||i===pts.length-1?'<text x="'+x(i).toFixed(1)+'" y="'+(H-8)+'" font-size="9" text-anchor="middle" fill="#64748B">'+esc(p.l)+'</text>':'')).join("")+'</svg>';}
function diasCorridos(n,fimTs){const out=[],f=new Date(fimTs||Date.now());f.setHours(0,0,0,0);for(let i=n-1;i>=0;i--){const d=new Date(f);d.setDate(d.getDate()-i);out.push(d);}return out;}
function fxFull(t,body){return '<div style="margin-top:10px">'+fxCard(t,body)+'</div>';}
function fxRotRows(){const src=(FECH.dados&&Array.isArray(FECH.dados.rotina)&&FECH.dados.rotina.length)?FECH.dados.rotina:ROTINA;const [de,ate]=fxPeriodo();
  return src.map(rotObj).filter(o=>{const t=o.d?dayStart(o.d):0;return t>=de&&t<ate&&!RUAS_FORA.has(o.rua);});}

/* ---- Ruas ---- */
function fxRuas(){const rows=fxNoPeriodo(FECH.dados&&FECH.dados.ruas),tit="Qualidade de Ruas — Fechamento de Ciclo";
  const pr=ciclos(rows.map(normRec)),ult={};Object.entries(pr).forEach(([r,cs])=>ult[r]=cs[cs.length-1]);
  const qRua={};Object.entries(ult).forEach(([r,c])=>qRua[r]=c.q);const qs=Object.values(qRua);const qm=qs.length?qs.reduce((a,b)=>a+b,0)/qs.length:null;
  const nCiclos=Object.values(pr).reduce((a,cs)=>a+cs.length,0),ocorr=rows.filter(r=>pbool(r.Possui_NC)).length,totRuas=Object.keys(ruaTotMap()).length;
  const crit=Object.entries(ult).filter(([r,c])=>c.q<.85).sort((a,b)=>a[1].q-b[1].q);const val=rows.reduce((a,r)=>a+(pbool(r.Possui_NC)?pnum(r.Valor_Divergencia):0),0);
  const reps=QUADRO.filter(q=>q.ruas.length).map(q=>{const v=q.ruas.filter(r=>!RUAS_FORA.has(r)).map(r=>qRua[r]).filter(x=>x!=null);return {q,acc:v.length?v.reduce((a,b)=>a+b,0)/v.length:null};}).filter(x=>x.acc!=null).sort((a,b)=>b.acc-a.acc);
  const aud={};rows.forEach(r=>{const n=r.Nome_Auditor||r.Matricula_Auditor||"—";(aud[n]=aud[n]||new Set()).add(unz(r.Rua)||String(fmtAddr(r.Endereco)).split("-")[0]);});
  const tipos=[["Picking errado (6)","Erro_Produto","#6366F1"],["Avaria (4)","Avaria","#F97316"],["Vencimento (3)","Prox_Vencimento","#EAB308"],["Sem saldo (2)","Sem_Saldo","#EF4444"]].map(([l,k,c])=>({l,v:rows.filter(r=>pbool(r[k])).length,c}));
  const valRua={};rows.forEach(r=>{if(!pbool(r.Possui_NC))return;const k=unz(r.Rua);valRua[k]=(valRua[k]||0)+pnum(r.Valor_Divergencia);});
  const porD={};Object.values(pr).flat().forEach(c=>{const k=fxDiaKey(c.ts);(porD[k]=porD[k]||[]).push(c.q);});
  const linha=diasCorridos(30,FECH.ate?dayStart(FECH.ate):Date.now()).map(d=>{const L=porD[fxDiaKey(d.getTime())];const m=L?L.reduce((a,b)=>a+b,0)/L.length:null;return {l:fxDia(d.getTime()),v:m==null?0:m,txt:m==null?"":pc0(m),c:m==null?"#CBD5E1":FXC[fxCls(m)]};});
  return fxHead(tit,rows.length)+
    fxKpis([{t:"Auditorias",v:nCiclos},{t:"Qualidade média",v:pc1(qm),c:qm==null?"#64748B":FXC[fxCls(qm)]},{t:"Ocorrências",v:ocorr,c:"#DC2626"},
      {t:"Ruas auditadas",v:Object.keys(ult).length,c:"#0F172A",s:"de "+totRuas+" possíveis"},{t:"Ruas críticas <85%",v:crit.length,c:"#DC2626",s:"requer ação",sc:"#DC2626"},{t:"Valor em divergência",v:BRL0(val),c:"#B45309"}])+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Mapa de qualidade por bloco",fxMapa(qRua,"Qualidade = 1 − (pontos ÷ endereços da rua). Pesos: picking errado 6, avaria 4, vencimento 3, sem saldo 2."))+'</div>'+
    '<div class="fx-col">'+fxCard("Ruas críticas (&lt;85%)",fxChips(crit.map(([r,c])=>[r,c.q,blocoDe(r)])))+
      fxCard("Repositores — acuracidade",fxBars(reps.map(x=>({l:x.q.mat+" - "+curto(nomeC(x.q.mat)),v:x.acc,txt:pc1(x.acc),c:FXC[fxCls(x.acc)]})),{max:1}))+'</div></div>'+
    '<div class="fx-g3" style="margin-top:10px">'+fxCard("Ocorrências por tipo (peso)",fxDonut(tipos))+
      fxCard("Auditores — ruas inspecionadas",fxBars(Object.entries(aud).sort((a,b)=>b[1].size-a[1].size).map(([n,s])=>({l:curto(n),v:s.size,txt:s.size+" rua"+(s.size>1?"s":""),c:"#3B82F6"}))))+
      fxCard("Maiores divergências por rua (R$)",fxBars(Object.entries(valRua).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([r,v])=>({l:"Rua "+r,v,txt:BRL0(v),c:"#B45309"}))))+'</div>'+
    fxFoot("Qualidade de Ruas");}

/* ---- Retorno ---- */
function fxRet(){const rows=fxNoPeriodo(FECH.dados&&FECH.dados.retorno).filter(r=>!RUAS_FORA.has(unz(r.Rua))).filter(r=>!RUAS_FORA.has(unz(r.Rua))).map(r=>Object.assign(r,{_nc:pbool(r.Possui_NC),_rua:unz(r.Rua),_qe:pnum(r.Qtd_Etiqueta),_qf:pnum(r.Qtd_Fisico),_vd:pnum(r.Valor_Divergencia),_du:pnum(r.Divergencia_Un)})),tit="Auditoria de Retorno — Fechamento";
  const rot=fxRotRows();const conf=rows.filter(r=>!r._nc).length,q=rows.length?conf/rows.length:null,vd=rows.reduce((a,r)=>a+r._vd,0),venc=rows.filter(r=>pbool(r.Prox_Vencimento)).length;
  const porRua={};const PR=k=>porRua[k]=porRua[k]||{n:0,c:0,vd:0,os:0};
  rows.forEach(r=>{const x=PR(r._rua);x.n++;if(!r._nc)x.c++;x.vd+=r._vd;});rot.forEach(o=>{PR(o.rua).os++;});
  const qRua={};Object.entries(porRua).forEach(([r,x])=>{if(x.n)qRua[r]=x.c/x.n;});
  const crit=Object.entries(qRua).filter(([r,v])=>v<.85).sort((a,b)=>a[1]-b[1]);
  const reps=QUADRO.filter(x=>x.ruas.length).map(x=>{let n=0,c=0;x.ruas.forEach(r=>{if(porRua[r]){n+=porRua[r].n;c+=porRua[r].c;}});return {x,n,acc:n?c/n:null};}).filter(o=>o.acc!=null).sort((a,b)=>b.acc-a.acc||b.n-a.n);
  const aud={};rows.forEach(r=>{const k=r.Nome_Auditor||r.Matricula_Auditor||"—";aud[k]=(aud[k]||0)+1;});const audNomes=Object.keys(aud).map(curto).join(", ")||"—";
  const div=rows.filter(r=>r._du!==0).length,manual=rows.filter(r=>r._nc&&r._du===0&&!pbool(r.Prox_Vencimento)).length;
  const top=rows.filter(r=>r._vd).sort((a,b)=>Math.abs(b._vd)-Math.abs(a._vd)).slice(0,8);
  const tabela=(function(){const H=[{t:"Rua"},{t:"O.S.",n:1},{t:"Retornos contados",n:1},{t:"% conferido",n:1}];
    const L=Object.entries(porRua).filter(([k])=>k).sort((a,b)=>(+a[0])-(+b[0])).map(([k,x])=>{const p=x.os?Math.min(1,x.n/x.os):null;return ['<b>'+esc(k)+'</b>',x.os,x.n,p==null?'—':'<b style="color:'+FXC[fxCls(p)]+'">'+pc0(p)+'</b>'];});
    if(!L.length)return '<p class="fx-e">Sem dados no período.</p>';const nb=L.length>27?4:L.length>12?3:1,n=Math.ceil(L.length/nb);
    return '<div class="fx-cmp" style="display:grid;grid-template-columns:repeat('+nb+',1fr);gap:8px;align-items:start">'+Array.from({length:nb},(_,i)=>L.slice(i*n,(i+1)*n)).filter(x=>x.length).map(x=>fxTable(H,x)).join("")+'</div>'+
      '<p class="fx-e" style="margin-top:6px">O.S. = retornos da rotina 8457 na rua (RUA_O). Retornos contados = itens auditados na rua. % conferido = retornos contados ÷ O.S. da rotina.</p>';})();
  return fxHead(tit,rows.length).replace('Total de registros:','Auditores: <b>'+esc(audNomes)+'</b><br>Total de registros:')+
    fxKpis([{t:"Itens auditados",v:rows.length},{t:"Conformidade",v:pc1(q),c:q==null?"#64748B":FXC[fxCls(q)],s:conf+" conformes"},{t:"Não conformidades",v:rows.length-conf,c:"#DC2626",s:venc+" vencendo · "+div+" com divergência"},
      {t:"O.S. auditadas × rotina",v:rows.length+" / "+rot.length,c:"#0E7490",s:rot.length?pc1(Math.min(1,rows.length/rot.length))+" das O.S. da rotina":"rotina 8457 não importada"},
      {t:"Ruas com retorno",v:Object.values(porRua).filter(x=>x.n).length,c:"#0F172A",s:crit.length+" abaixo de 85%",sc:crit.length?"#DC2626":"#64748B"},
      {t:"Valor da divergência",v:BRL0(vd),c:vd<0?"#DC2626":vd>0?"#B45309":"#16A34A"}],true)+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Conformidade do retorno por bloco",fxMapa(qRua,"Percentual = itens conformes ÷ itens auditados na rua."))+'</div>'+
    '<div class="fx-col">'+fxCard("Auditorias por auditor",fxCols(Object.entries(aud).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([n,v])=>({l:curto(n),v,txt:String(v),c:"#2563EB"}))).replace('height:140px','height:110px'))+
      fxCard("Ruas críticas (&lt;85%)",fxChips(crit.map(([r,v])=>[r,v,blocoDe(r)])))+
      fxCard("Repositores — acuracidade do retorno",fxBars(reps.map(o=>({l:o.x.mat+" - "+curto(nomeC(o.x.mat))+" ("+o.n+")",v:o.acc,txt:pc1(o.acc),c:FXC[fxCls(o.acc)]})),{max:1}))+'</div></div>'+
    fxFull("Retornos por rua — O.S. da rotina × retornos contados",tabela)+
    '<div class="fx-g2" style="margin-top:10px">'+fxCard("Ocorrências",fxDonut([{l:"Divergência de quantidade",v:div,c:"#EF4444"},{l:"Próximo do vencimento",v:venc,c:"#EAB308"},{l:"Retorno não conforme",v:manual,c:"#6366F1"},{l:"Conforme",v:conf,c:"#16A34A"}]))+
      fxCard("Maiores divergências",fxTable([{t:"Rua"},{t:"Item"},{t:"Etiq.",n:1},{t:"Fís.",n:1},{t:"Valor",n:1}],top.map(r=>[esc(r._rua),esc(r.Produto+" – "+String(r.Descricao_Produto||"").slice(0,26)),r._qe,r._qf,'<b style="color:'+(r._vd<0?"#DC2626":"#B45309")+'">'+BRL0(r._vd)+'</b>'])))+'</div>'+fxFoot("Auditoria de Retorno");}

/* ---- Cargas ---- */
function fxCar(){const rows=fxNoPeriodo(FECH.dados&&FECH.dados.cargas).map(r=>Object.assign(r,{_q:pnum(r.Quantidade),_v:pnum(r.Valor_Total)})),tit="Auditoria de Cargas — Fechamento";
  const todas=fxRows(FECH.dados&&FECH.dados.cargas);
  const MOT=[["Falta","#EF4444"],["Avaria","#F97316"],["Abastecimento","#6366F1"],["Sobras","#CA8A04"],["Produto trocado","#DB2777"]];
  const m={};MOT.forEach(([k])=>m[k]={n:0,q:0,v:0});rows.forEach(r=>{const x=m[r.Motivo];if(x){x.n++;x.q+=r._q;x.v+=r._v;}});
  const oss=new Set(rows.map(r=>r.Numero_OS)),tot=rows.reduce((a,r)=>a+r._v,0),pct=v=>tot?" · "+Math.round(v/tot*100)+"% do valor":"";
  const itens={};rows.forEach(r=>{const k=r.Codigo_Produto;const x=itens[k]=itens[k]||{d:r.Descricao_Produto,n:0,q:0,v:0,mot:{}};x.n++;x.q+=r._q;x.v+=r._v;x.mot[r.Motivo]=(x.mot[r.Motivo]||0)+1;});
  const rankItens=Object.entries(itens).sort((a,b)=>b[1].n-a[1].n||b[1].v-a[1].v).slice(0,8);
  const pessoas=tipo=>{const o={};rows.filter(r=>r.Causador===tipo).forEach(r=>{const k=r.Matricula_Causador||r.Nome_Causador;const x=o[k]=o[k]||{n:r.Nome_Causador||k,i:0,v:0};x.i++;x.v+=r._v;});return Object.values(o).sort((a,b)=>b.i-a.i||b.v-a.v).slice(0,7);};
  const seps=pessoas("Separador"),confs=pessoas("Conferente");
  const audA={};rows.forEach(r=>{const k=r.Nome_Auditor||"—";const x=audA[k]=audA[k]||{os:new Set(),i:0};x.os.add(r.Numero_OS);x.i++;});
  const porD={};todas.forEach(r=>{const k=fxDiaKey(r.ts);const x=porD[k]=porD[k]||{ts:r.ts,n:0};x.n++;});
  const linha=Object.keys(porD).sort().slice(-30).map(k=>({l:fxDia(porD[k].ts),v:porD[k].n,txt:String(porD[k].n)}));
  return fxHead(tit,rows.length)+
    fxKpis([{t:"O.S. auditadas",v:oss.size,s:(oss.size?(rows.length/oss.size).toFixed(1).replace(".",","):"0")+" ocorr. por O.S."},{t:"Ocorrências",v:rows.length,c:"#DC2626",s:rows.reduce((a,r)=>a+r._q,0)+" unidades"},
      {t:"Valor total",v:BRL0(tot),c:"#B45309",s:"média "+BRL0(oss.size?tot/oss.size:0)+" por O.S."},
      {t:"Faltas",v:BRL0(m.Falta.v),c:"#DC2626",s:m.Falta.n+" ocorr. · "+m.Falta.q+" un"+pct(m.Falta.v)},{t:"Avarias",v:BRL0(m.Avaria.v),c:"#EA580C",s:m.Avaria.n+" ocorr. · "+m.Avaria.q+" un"+pct(m.Avaria.v)},
      {t:"Abastecimento",v:BRL0(m.Abastecimento.v),c:"#4F46E5",s:m.Abastecimento.n+" ocorr. · "+m.Abastecimento.q+" un"+pct(m.Abastecimento.v)},{t:"Sobras",v:BRL0(m.Sobras.v),c:"#CA8A04",s:m.Sobras.n+" ocorr. · "+m.Sobras.q+" un"+pct(m.Sobras.v)},{t:"Produto trocado",v:BRL0(m["Produto trocado"].v),c:"#DB2777",s:m["Produto trocado"].n+" ocorr. · "+m["Produto trocado"].q+" un"+pct(m["Produto trocado"].v)}],true)+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Itens que mais dão divergência",fxTable([{t:"#"},{t:"Item"},{t:"Motivos"},{t:"Ocorr.",n:1},{t:"Un",n:1},{t:"Valor",n:1}],
        rankItens.map(([k,x],i)=>[i+1,esc(k+" – "+String(x.d||"").slice(0,28)),esc(Object.entries(x.mot).map(([mm,n])=>mm+(n>1?" ("+n+")":"")).join(", ")),'<b>'+x.n+'</b>',x.q,BRL0(x.v)])))+
      '<div class="fx-g2">'+fxCard("Separadores com mais ocorrências",fxBars(seps.map(x=>({l:curto(x.n),v:x.i,txt:x.i+" · "+BRL0(x.v),c:"#7C3AED"}))))+
      fxCard("Conferentes com mais ocorrências",fxBars(confs.map(x=>({l:curto(x.n),v:x.i,txt:x.i+" · "+BRL0(x.v),c:"#0EA5E9"}))))+'</div></div>'+
    '<div class="fx-col">'+fxCard("O.S. auditadas por auditor",fxCols(Object.entries(audA).sort((a,b)=>b[1].os.size-a[1].os.size).slice(0,8).map(([n,x])=>({l:curto(n),v:x.os.size,txt:x.os.size+" O.S.",c:"#2563EB"}))).replace('height:140px','height:120px'))+
      fxCard("Ocorrências por motivo",fxDonut(MOT.map(([k,c])=>({l:k,v:m[k].n,c}))))+'</div></div>'+
    fxFull("Ocorrências lançadas por dia (somente dias com auditoria)",fxLine(linha,"#2563EB"))+fxFoot("Auditoria de Cargas");}

/* ---- Retorno × Rotina ---- */
function rotinaRows(){const src=(FECH.dados&&Array.isArray(FECH.dados.rotina)&&FECH.dados.rotina.length)?FECH.dados.rotina:ROTINA;return src.map(rotObj);}
function fxRot(){const marg=+FECH.margem||6,tit="Retorno × Rotina (8457) — Qualidade por rua";
  const [de,ate]=fxPeriodo();const rot=rotinaRows().filter(o=>{const t=o.d?dayStart(o.d):0;return t>=de&&t<ate;});
  const aud=fxNoPeriodo(FECH.dados&&FECH.dados.retorno).map(r=>Object.assign(r,{_rua:unz(r.Rua),_qe:pnum(r.Qtd_Etiqueta),_qf:pnum(r.Qtd_Fisico),_os:String(r.Numero_OS||"").trim(),_cod:String(r.Produto||"").trim()}));
  const usados=new Set();const byOS={};rot.forEach((o,i)=>{(byOS[o.os]=byOS[o.os]||[]).push(i);});
  aud.forEach(a=>{let idx=-1;if(a._os&&byOS[a._os])idx=byOS[a._os].find(i=>!usados.has(i)&&(!a._cod||rot[i].cod===a._cod));if(idx==null||idx<0)idx=byOS[a._os]?byOS[a._os].find(i=>!usados.has(i)):-1;
    if(idx==null||idx<0)idx=rot.findIndex((o,i)=>!usados.has(i)&&o.cod===a._cod&&o.rua===a._rua);
    if(idx==null||idx<0)idx=rot.findIndex((o,i)=>!usados.has(i)&&o.cod===a._cod);
    if(idx>=0){usados.add(idx);a._rot=rot[idx];}
    a._dif=a._qf-a._qe;a._ok=Math.abs(a._dif)<=marg;});
  const ruas={};const R=k=>ruas[k]=ruas[k]||{os:0,aud:0,ok:0,qe:0,qf:0,cob:0,qr:0};
  rot.forEach(o=>{const x=R(o.rua);x.os++;x.qr+=o.qtd||0;});aud.forEach(a=>{const k=a._rot?a._rot.rua:a._rua;const x=R(k);x.aud++;if(a._ok)x.ok++;x.qe+=a._qe;x.qf+=a._qf;if(a._rot)x.cob++;});
  Object.keys(ruas).forEach(k=>{if(RUAS_FORA.has(k))delete ruas[k];});const qRua={};Object.entries(ruas).forEach(([k,x])=>{if(x.aud)qRua[k]=x.ok/x.aud;});
  const ruaDe=a=>a._rot?a._rot.rua:a._rua;
  const repNomes=r=>repsDaRua(r).map(m=>curto(nomeC(m))).join(" e ")||"—";
  const reps={};const P=m=>reps[m]=reps[m]||{n:nomeC(m),m,os:0,aud:0,ok:0,dif:0,ruas:new Set()};
  rot.forEach(o=>{if(RUAS_FORA.has(o.rua))return;repsDaRua(o.rua).forEach(m=>{const x=P(m);x.os++;x.ruas.add(o.rua);});});
  aud.forEach(a=>{const r=ruaDe(a);if(RUAS_FORA.has(r))return;repsDaRua(r).forEach(m=>{const x=P(m);x.aud++;if(a._ok)x.ok++;x.dif+=a._dif;x.ruas.add(r);});});
  QUADRO.forEach(q=>{const ru=q.ruas.filter(r=>!RUAS_FORA.has(r));if(ru.length&&!reps[q.mat]){const x=P(q.mat);ru.forEach(r=>x.ruas.add(r));}});
  const nAud=aud.length,nOk=aud.filter(a=>a._ok).length,nMatch=aud.filter(a=>a._rot).length,q=nAud?nOk/nAud:null,cob=rot.length?nMatch/rot.length:null;
  const fora=aud.filter(a=>!a._ok).sort((a,b)=>Math.abs(b._dif)-Math.abs(a._dif)).slice(0,10);
  const audT={};aud.forEach(a=>{const k=a.Nome_Auditor||"—";audT[k]=(audT[k]||0)+1;});
  const repsL=Object.values(reps);const totQr=Object.values(ruas).reduce((a,x)=>a+x.qr,0),totQf=Object.values(ruas).reduce((a,x)=>a+x.qf,0),pQ=totQr?totQf/totQr:null;
  return fxHead(tit,nAud)+
    fxKpis([{t:"OS na rotina",v:rot.length,c:"#0F172A",s:"retornos lançados no período"},{t:"Retornos auditados",v:nAud},{t:"Cobertura",v:pc1(cob),c:"#0E7490",s:nMatch+" OS encontradas na rotina"},
      {t:"Dentro da margem (±"+marg+")",v:pc1(q),c:q==null?"#64748B":FXC[fxCls(q)],s:nOk+" de "+nAud+" auditorias"},{t:"Qtd. retornada × auditada",v:totQf.toLocaleString("pt-BR")+" / "+totQr.toLocaleString("pt-BR"),c:"#0F172A",s:(pQ==null?"—":pc1(pQ))+" das unidades auditadas · "+(nAud-nOk)+" fora da margem",sc:"#64748B"},
      {t:"Repositores avaliados",v:repsL.filter(x=>x.aud).length,c:"#0F172A",s:"de "+repsL.length+" no quadro"}])+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Qualidade do retorno por rua (margem ±"+marg+" un)",fxMapa(qRua,"Qualidade = auditorias com |contagem − etiqueta| ≤ "+marg+" ÷ auditorias da rua. Rua pela coluna RUA_O da rotina; repositor pelo quadro de repositores."))+
      fxCard("Retornos por rua — quantidade retornada × auditada",(function(){const H=[{t:"Rua"},{t:"O.S.",n:1},{t:"Aud.",n:1},{t:"Qtd. ret.",n:1},{t:"Qtd. aud.",n:1},{t:"Qual.",n:1}];
        const L=Object.entries(ruas).filter(([k])=>k).sort((a,b)=>(+a[0])-(+b[0])).map(([k,x])=>['<b>'+esc(k)+'</b>',x.os,x.aud,x.qr.toLocaleString("pt-BR"),x.qf.toLocaleString("pt-BR"),x.aud?'<b style="color:'+FXC[fxCls(x.ok/x.aud)]+'">'+pc0(x.ok/x.aud)+'</b>':'—']);
        if(L.length<=10)return '<div class="fx-cmp">'+fxTable(H,L)+'</div>';const n=Math.ceil(L.length/3);return '<div class="fx-g3 fx-cmp">'+[0,1,2].map(i=>L.slice(i*n,(i+1)*n)).filter(x=>x.length).map(x=>fxTable(H,x)).join("")+'</div>';})())+'</div>'+
    '<div class="fx-col">'+fxCard("Repositores — qualidade do retorno",fxBars(repsL.filter(x=>x.aud).sort((a,b)=>b.ok/b.aud-a.ok/a.aud||b.aud-a.aud).map(x=>({l:curto(x.n)+" · ruas "+[...x.ruas].sort((a,b)=>a-b).join(",")+" ("+x.aud+"/"+x.os+" OS)",v:x.ok/x.aud,txt:pc1(x.ok/x.aud),c:FXC[fxCls(x.ok/x.aud)]})),{max:1}))+
      fxCard("Quantidade retornada × auditada (unidades)",(function(){const L=Object.entries(ruas).filter(([k,x])=>k&&(x.qr||x.qf)).sort((a,b)=>b[1].qr-a[1].qr).slice(0,10);if(!L.length)return '<p class="fx-e">Sem dados no período.</p>';const mx=Math.max(...L.map(([k,x])=>Math.max(x.qr,x.qf)),1);
        return '<div class="fx-bars">'+L.map(([k,x])=>'<div class="fx-br fx-br2"><span class="n"></span><span class="l">Rua '+esc(k)+'</span><span><span class="t"><i style="width:'+Math.max(1,Math.round(x.qr/mx*100))+'%;background:#94A3B8"></i></span><span class="t" style="margin-top:2px"><i style="width:'+Math.max(x.qf?1:0,Math.round(x.qf/mx*100))+'%;background:#2563EB"></i></span></span><b>'+x.qf.toLocaleString("pt-BR")+' / '+x.qr.toLocaleString("pt-BR")+'</b></div>').join("")+'</div><p class="fx-e" style="margin-top:6px"><i style="display:inline-block;width:10px;height:8px;background:#94A3B8;border-radius:2px"></i> retornado na rotina &nbsp; <i style="display:inline-block;width:10px;height:8px;background:#2563EB;border-radius:2px"></i> contado na auditoria</p>';})())+
      fxCard("Repositores sem retorno auditado no período",(function(){const L=repsL.filter(x=>!x.aud).sort((a,b)=>b.os-a.os);return L.length?'<div class="fx-chips">'+L.map(x=>'<span class="s-na">'+esc(curto(x.n))+' · ruas '+[...x.ruas].sort((a,b)=>a-b).join(",")+' · '+x.os+' OS</span>').join("")+'</div>':'<p class="fx-e">Todos os repositores tiveram retorno auditado.</p>';})())+
      fxCard("Auditorias fora da margem",fxTable([{t:"Rua"},{t:"OS"},{t:"Item"},{t:"Repositor"},{t:"Etiq.",n:1},{t:"Cont.",n:1},{t:"Dif.",n:1}],
        fora.map(a=>[esc(ruaDe(a)),esc(a._rot?a._rot.os:(a._os||"—")),esc(a._cod),esc(repNomes(ruaDe(a))),a._qe,a._qf,'<b style="color:#DC2626">'+(a._dif>0?"+":"")+a._dif+'</b>'])))+
      fxCard("Auditores — retornos auditados",fxBars(Object.entries(audT).sort((a,b)=>b[1]-a[1]).map(([n,v])=>({l:n,v,txt:v+" ret.",c:"#3B82F6"}))))+'</div></div>'+fxFoot("Retorno × Rotina 8457");}

/* ---- tela ---- */
const FX_TIT={ruas:"Qualidade de Ruas",retorno:"Auditoria de Retorno",rotina:"Retorno x Rotina",cargas:"Auditoria de Cargas"};
const FX_TAB={ruas:"Ruas",retorno:"Retorno",rotina:"Retorno × Rotina",cargas:"Cargas",aero:"Aéreo",setores:"Setores"};FX_TIT.aero="Auditoria Aereo";FX_TIT.setores="Setores";
function fxRelatorio(){return FECH.tipo==="setores"?fxSetores():FECH.tipo==="aero"?fxAero():FECH.tipo==="retorno"?fxRet():FECH.tipo==="cargas"?fxCar():FECH.tipo==="rotina"?fxRot():fxRuas();}
function renderFech(){const box=$("fech");if(!box)return;if(FECH.tipo==="rotina"||(FECH.tipo==="setores"?!ehAdm():!podeVer(FECH.tipo)))FECH.tipo=["ruas","retorno","cargas","aero"].find(k=>podeVer(k))||"ruas";
  const bar='<div class="fxbar"><div class="seg fx-tabs" role="group" aria-label="Tipo de auditoria">'+["ruas","retorno","cargas","aero","setores"].filter(k=>k==="setores"?ehAdm():podeVer(k)).map(k=>'<button type="button" data-fx="'+k+'" aria-pressed="'+(FECH.tipo===k)+'">'+FX_TAB[k]+'</button>').join("")+'</div>'+
    '<label>De <input class="in" type="date" id="fx-de" value="'+FECH.de+'"></label><label>Até <input class="in" type="date" id="fx-ate" value="'+FECH.ate+'"></label>'+
    '<button type="button" class="btn" id="fx-upd">Atualizar</button><button type="button" class="save" id="fx-pr" style="margin:0;min-height:44px;font-size:1.1rem;width:auto;padding:0 18px">Imprimir / PDF</button></div>'+
    '<p class="note" id="fx-info" style="margin:0 0 10px">'+esc(FECH.info||"")+'</p>';
  if(!FECH.dados){box.innerHTML=bar+'<div class="empty">'+(FECH.busy?"Carregando a planilha…":"Toque em Atualizar para carregar os dados da planilha.")+'</div>';bindFech();return;}
  box.innerHTML=bar+'<div class="fxwrap"><div class="pd fx" id="fx-rel">'+fxRelatorio()+'</div></div>';bindFech();}
function bindFech(){document.querySelectorAll("[data-fx]").forEach(b=>b.onclick=()=>{FECH.tipo=b.dataset.fx;renderFech();});
  $("fx-de").onchange=e=>{FECH.de=e.target.value;if(FECH.ate&&FECH.ate<FECH.de)FECH.ate=FECH.de;renderFech();};
  $("fx-ate").onchange=e=>{FECH.ate=e.target.value;renderFech();};
  $("fx-upd").onclick=()=>carregarFech(true);
  const mg=$("fx-mg");if(mg)mg.onchange=e=>{FECH.margem=Math.max(0,parseInt(e.target.value,10)||0);renderFech();};
  $("fx-pr").onclick=()=>{if(!FECH.dados){toast("Carregue os dados primeiro.");return;}const tit=FX_TIT[FECH.tipo];
    openDoc({html:'<div class="pd fx">'+fxRelatorio()+'</div>',multi:false,land:true,name:"Fechamento_"+tit.replace(/\s+/g,"_")+"_"+FECH.de+"_a_"+FECH.ate+".pdf",title:"Fechamento – "+tit,
      short:"Fechamento – "+tit+" – "+fdISO(FECH.de)+" a "+fdISO(FECH.ate),text:"*FECHAMENTO – "+tit.toUpperCase()+"*\nPeríodo: "+fdISO(FECH.de)+" a "+fdISO(FECH.ate)});};}
async function carregarFech(manual){if(FECH.busy)return;
  if(DEMO||!SHEET_URL){FECH.info="O fechamento lê a planilha pelo site, com login de administrador.";renderFech();return;}
  if(!navigator.onLine){FECH.info=FECH.dados?"Sem internet: mostrando a última cópia da planilha.":"Sem internet.";renderFech();return;}
  FECH.busy=true;if(!FECH.dados)renderFech();const inf=$("fx-info");if(inf)inf.textContent="Atualizando com a planilha…";
  try{const r=await fetch(SHEET_URL+(SHEET_URL.includes("?")?"&":"?")+"acao=fechamento&token="+encodeURIComponent((LOGIN&&LOGIN.token)||"")+"&t="+Date.now(),{cache:"no-store"});const j=await r.json();
    if(j&&j.ok&&j.ruas){FECH.dados=j;aplicarQuadroPlanilha(j.quadro);FECH.info="Planilha Google · atualizado "+fmtDT(new Date()).slice(0,16)+" · Ruas "+((j.ruas.registros||[]).length)+" · Retorno "+((j.retorno&&j.retorno.registros||[]).length)+" · Cargas "+((j.cargas&&j.cargas.registros||[]).length)+" · Rotina "+((j.rotina||[]).length)+" linhas";
      IDB.set("fech_cache",{dados:j,info:FECH.info}).catch(()=>{});if(manual)toast("Fechamento atualizado.");}
    else FECH.info=(j&&j.erro)||"Atualize o Apps Script para a versão 12 para usar o fechamento.";
  }catch(e){FECH.info=FECH.dados?"Sem conexão com a planilha: mostrando a última cópia.":"Sem conexão com a planilha.";}
  FECH.busy=false;renderFech();}
IDB.get("fech_cache").then(c=>{if(c&&c.dados&&!FECH.dados){FECH.dados=c.dados;FECH.info="Última cópia da planilha: "+String(c.info||"").replace(/^Planilha Google · atualizado /,"");}}).catch(()=>{});

// impressão de todas as NCs da planilha (somente ADM)
function regPeriodo(){const pv=$("f-periodo").value;let from=0,to=Infinity,lab="todo o histórico";
  if(pv==="d"){const de=$("f-de").value,ate=$("f-ate").value||de;if(de){from=dayStart(de);to=dayStart(ate)+864e5;lab=de.split("-").reverse().join("/")+(ate!==de?" a "+ate.split("-").reverse().join("/"):"");}}
  else{const days=+pv;if(days){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(days-1));from=d.getTime();lab=days===1?"hoje":"últimos "+days+" dias";}}
  return {from,to,lab};}
function ncPlanHTML(j,per){const sel=r=>r.ts>=per.from&&r.ts<per.to;
  const ruas=fxRows(j.ruas).filter(sel).filter(r=>pbool(r.Possui_NC)).sort((a,b)=>a.ts-b.ts);
  const ret=fxRows(j.retorno).filter(sel).filter(r=>pbool(r.Possui_NC)).sort((a,b)=>a.ts-b.ts);
  const car=fxRows(j.cargas).filter(sel).sort((a,b)=>a.ts-b.ts);
  const oc=r=>[pbool(r.Erro_Produto)?"Lugar errado"+(r.Endereco_Correto?" (correto "+fmtAddr(r.Endereco_Correto)+")":""):"",pbool(r.Prox_Vencimento)?"Vencimento"+(r.Data_Vencimento?" "+r.Data_Vencimento:""):"",pbool(r.Sem_Saldo)?"Sem saldo":"",pbool(r.Avaria)?"Avaria"+(r.Tipo_Avaria?" ("+r.Tipo_Avaria+")":""):""].filter(Boolean).join("; ");
  const dt=r=>String(r.DataHora||"").slice(0,16);const soma=(L,k)=>L.reduce((a,r)=>a+pnum(r[k]),0);
  const sec=(tit,head,rows,tot)=>'<div class="fx-c" style="margin-top:10px"><h3>'+tit+' <span style="float:right;color:#64748B">'+rows.length+' registro'+(rows.length===1?'':'s')+(tot?' · '+tot:'')+'</span></h3>'+fxTable(head,rows)+'</div>';
  return '<div class="fx-h"><div><h1>Não conformidades — planilha Google</h1><p>Período: <b>'+esc(per.lab)+'</b></p></div><div class="r">Gerado: <b>'+fmtDT(new Date())+'</b><br>Por: <b>'+esc(nomeAud())+'</b></div></div>'+
    fxKpis([{t:"Ruas",v:ruas.length,c:"#DC2626",s:BRL0(soma(ruas,"Valor_Divergencia"))},{t:"Retorno",v:ret.length,c:"#DC2626",s:BRL0(soma(ret,"Valor_Divergencia"))},{t:"Cargas",v:car.length,c:"#DC2626",s:BRL0(soma(car,"Valor_Total"))},{t:"Total de NCs",v:ruas.length+ret.length+car.length,c:"#0F172A"}])+
    sec("Auditoria de ruas",[{t:"Data"},{t:"Endereço"},{t:"Item"},{t:"Ocorrência"},{t:"Qtd.",n:1},{t:"Valor",n:1},{t:"Repositor"},{t:"Auditor"},{t:"Status"}],
      ruas.map(r=>[dt(r),'<b>'+esc(fmtAddr(r.Endereco))+'</b>',esc((r.Produto||"")+(r.Descricao_Produto?" – "+String(r.Descricao_Produto).slice(0,30):"")),esc(oc(r)),pnum(r.Qtd_Divergencia_Un),BRL0(pnum(r.Valor_Divergencia)),esc(curto(r.Nome_Colaborador_NC||"")),esc(curto(r.Nome_Auditor||"")),esc(r.Status_NC||"")]),BRL0(soma(ruas,"Valor_Divergencia")))+
    sec("Auditoria de retorno",[{t:"Data"},{t:"Rua"},{t:"O.S."},{t:"Item"},{t:"Etiq.",n:1},{t:"Fís.",n:1},{t:"Dif.",n:1},{t:"Valor div.",n:1},{t:"Ocorrência"},{t:"Responsável"},{t:"Status"}],
      ret.map(r=>{const d=pnum(r.Divergencia_Un);return [dt(r),esc(unz(r.Rua)),esc(r.Numero_OS||""),esc(r.Produto+" – "+String(r.Descricao_Produto||"").slice(0,30)),pnum(r.Qtd_Etiqueta),pnum(r.Qtd_Fisico),(d>0?"+":"")+d,BRL0(pnum(r.Valor_Divergencia)),esc([d?"Divergência":"",pbool(r.Prox_Vencimento)?"Vencimento":""].filter(Boolean).join("; ")||"Não conforme"),esc(curto(r.Nome_Colaborador_NC||"")),esc(r.Status_NC||"")];}),BRL0(soma(ret,"Valor_Divergencia")))+
    sec("Auditoria de cargas",[{t:"Data"},{t:"O.S."},{t:"Box"},{t:"Item"},{t:"Motivo"},{t:"Qtd.",n:1},{t:"Valor",n:1},{t:"Causador"},{t:"Conferente"}],
      car.map(r=>[dt(r),esc(r.Numero_OS),esc(r.Box),esc(r.Codigo_Produto+" – "+String(r.Descricao_Produto||"").slice(0,30)),esc(r.Motivo),pnum(r.Quantidade),BRL0(pnum(r.Valor_Total)),esc((r.Causador?r.Causador+": ":"")+curto(r.Nome_Causador||"")),esc(curto(r.Nome_Conferente||""))]),BRL0(soma(car,"Valor_Total")))+
    '<div class="fx-f"><span>Não conformidades da planilha · '+esc(per.lab)+'</span><span>Santa Therezinha</span></div>';}
async function imprimirNCsPlanilha(){if(!temPerm("aud_adm")){toast("Somente administradores.");return;}
  if(DEMO||!SHEET_URL){toast("Use o site com login para ler a planilha.");return;}if(!navigator.onLine){toast("Sem internet: a impressão lê a planilha Google.");return;}
  const bt=$("x-nc");bt.disabled=true;const old=bt.textContent;bt.textContent="Lendo a planilha…";
  try{const r=await fetch(SHEET_URL+(SHEET_URL.includes("?")?"&":"?")+"acao=fechamento&token="+encodeURIComponent(LOGIN.token)+"&t="+Date.now(),{cache:"no-store"});const j=await r.json();
    if(!j||!j.ok||!j.ruas)throw new Error((j&&j.erro)||"Atualize o Apps Script para a versão 13.");
    const per=regPeriodo();openDoc({html:'<div class="pd fx">'+ncPlanHTML(j,per)+'</div>',multi:true,land:true,name:"Nao_conformidades_"+todayISO()+".pdf",title:"Não conformidades – planilha",
      short:"Não conformidades da planilha – "+per.lab,text:"*NÃO CONFORMIDADES – PLANILHA*\nPeríodo: "+per.lab});}
  catch(e){toast(e.message||"Não foi possível ler a planilha.");}
  finally{bt.disabled=false;bt.textContent=old;}}
