async function excluirRegistro(id,aba){if(!temPerm("aud_adm"))return;if(!confirm("Excluir este registro do aparelho e da planilha Google? Não dá para desfazer."))return;
  let ok=true;if(!DEMO&&SHEET_URL){if(!navigator.onLine){toast("Sem internet: não dá para excluir da planilha agora.");return;}
    try{const r=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({acao:"admin_excluir",token:LOGIN.token,aba,id}),redirect:"follow",cache:"no-store"});const j=await r.json();if(!j.ok){ok=false;toast(j.erro||"Não foi possível excluir na planilha.");}}catch(e){ok=false;toast("Não foi possível falar com a planilha.");}}
  if(!ok)return;HIST.delete(id);IDB.del(id).catch(()=>{});const qi=queue.findIndex(x=>x.rec.ID_Auditoria===id);if(qi>=0){queue.splice(qi,1);saveQueue();}
  remote.ruas=remote.ruas.filter(r=>r.ID_Auditoria!==id);REG._ver=(REG._ver||0)+1;
  if(REG.rows){["ruas","retorno","cargas"].forEach(k=>{const b=REG.rows[k];if(b&&b.registros){const i0=b.colunas.indexOf("ID_Auditoria");b.registros=b.registros.filter(x=>String(x[i0])!==id);}});}
  toast("Registro excluído.");renderRecords();}
$("f-fonte").onchange=()=>{if(regFonte()==="planilha"&&!REG.rows)carregarReg();renderRecords();};
$("x-pr").onclick=imprimirLista;

// impressão dos documentos originais (como os auditores imprimem)
function sessaoDe(r,L){if(r.Sessao)return r.Sessao;const f=L[0];
  if(r._aba==="cargas")return {id:r.ID_Sessao||("OS"+r.Numero_OS),os:r.Numero_OS,box:r.Box,conf:f.Matricula_Conferente,confNome:f.Nome_Conferente,aud:f.Matricula_Auditor,audNome:f.Nome_Auditor};
  const rua=unz(r.Rua)||String(fmtAddr(r.Endereco)).split("-")[0];const nc=L.find(x=>pbool(x.Possui_NC)&&x.Matricula_Colaborador_NC);const rm=nc?nc.Matricula_Colaborador_NC:(repsDaRua(rua)[0]||"");
  return {id:r.ID_Sessao||("R"+rua+"-"+String(r.DataHora||"").slice(0,10)),rua,rep:rm,repNome:nc?nc.Nome_Colaborador_NC:nomeC(rm),repFun:nc?(nc.Funcao_Colaborador_NC||""):(cIdx.has(rm)?C.fun[cIdx.get(rm)]:""),aud:f.Matricula_Auditor,audNome:f.Nome_Auditor};}
function docsOriginais(lista,base){const docs=[],feitos=new Set();const asc=lista.slice().sort((a,b)=>a.ts-b.ts);
  const doGrupo=(r,aba)=>{const L=base.filter(x=>(x._aba||"ruas")===aba&&x.ID_Sessao===r.ID_Sessao).sort((a,b)=>a.ts-b.ts);return L.length?L:[r];};
  asc.forEach(r=>{const aba=r._aba||"ruas";
    if(aba==="ruas"){if(r.ID_Sessao){if(feitos.has("s"+r.ID_Sessao))return;feitos.add("s"+r.ID_Sessao);const L=doGrupo(r,"ruas");docs.push({html:sessDocHTML(sessaoDe(r,L),L.slice().reverse()),multi:true});}
      else if(pbool(r.Possui_NC))docs.push({html:docHTML(r),multi:false});}
    else if(aba==="retorno"){if(pbool(r.Possui_NC))docs.push({html:retNcDocHTML(r),multi:false});}
    else if(aba==="aero"){const k="a"+(r.Matricula_Operador||r.Operador)+"|"+String(r.DataHora||r.Data||"").slice(0,10);if(feitos.has(k))return;feitos.add(k);
      const L=base.filter(x=>x._aba==="aero"&&(x.Matricula_Operador||x.Operador)===(r.Matricula_Operador||r.Operador)&&String(x.DataHora||x.Data||"").slice(0,10)===String(r.DataHora||r.Data||"").slice(0,10));docs.push({html:aerDocHTML(L),multi:true});}
    else if(aba==="cargas"){const k="c"+(r.ID_Sessao||r.Numero_OS);if(feitos.has(k))return;feitos.add(k);const L=base.filter(x=>x._aba==="cargas"&&(r.ID_Sessao?x.ID_Sessao===r.ID_Sessao:x.Numero_OS===r.Numero_OS)).sort((a,b)=>a.ts-b.ts);if(L.some(x=>x.Causador==="Conferente"))docs.push({html:carDocHTML(sessaoDe(r,L),L),multi:true});}});
  return docs;}
async function makePdfLista(docs){if(!window.html2canvas)await loadScript(H2C);if(!(window.jspdf&&window.jspdf.jsPDF))await loadScript(JSPDF);
  const pdf=new window.jspdf.jsPDF({unit:"mm",format:"a4",orientation:"portrait"});let primeira=true;
  for(const d of docs){const host=document.createElement("div");host.style.cssText="position:fixed;left:-10000px;top:0;width:794px;background:#fff;padding:34px 45px;box-sizing:border-box";host.innerHTML=d.html;document.body.appendChild(host);
    await Promise.all([...host.querySelectorAll("img")].map(i=>i.complete?0:new Promise(ok=>{i.onload=i.onerror=ok;})));
    try{const cv=await window.html2canvas(host,{scale:1.6,backgroundColor:"#ffffff",logging:false});const pageH=Math.floor(cv.width*297/210);
      if(!d.multi||cv.height<=pageH){if(!primeira)pdf.addPage();let w=210,h=cv.height*w/cv.width;if(h>297){h=297;w=cv.width*h/cv.height;}pdf.addImage(cv.toDataURL("image/jpeg",.85),"JPEG",(210-w)/2,0,w,h);primeira=false;}
      else{const pc=document.createElement("canvas");pc.width=cv.width;const ctx=pc.getContext("2d");let y=0;
        while(y<cv.height){const h=Math.min(pageH,cv.height-y);pc.height=h;ctx.fillStyle="#fff";ctx.fillRect(0,0,pc.width,h);ctx.drawImage(cv,0,y,cv.width,h,0,0,cv.width,h);
          if(!primeira)pdf.addPage();pdf.addImage(pc.toDataURL("image/jpeg",.85),"JPEG",0,0,210,h*210/cv.width);primeira=false;y+=pageH-60;}}}
    finally{host.remove();}}
  return pdf.output("blob");}
async function imprimirOriginais(){const L=filtered();if(!L.length){toast("Nada para imprimir com estes filtros.");return;}
  const base=regFonte()==="planilha"?sheetRecs():allRecs();
  if(regFonte()==="planilha"){const ids=new Set(L.map(r=>r.ID_Sessao).filter(Boolean));await carregarFotosPlanilha(base.filter(r=>L.includes(r)||(r.ID_Sessao&&ids.has(r.ID_Sessao))));}const docs=docsOriginais(L,base);
  if(!docs.length){toast("Nenhuma não conformidade com documento nestes filtros.");return;}
  if(docs.length>60&&!confirm(docs.length+" documentos. Pode demorar para gerar. Continuar?"))return;
  const per=regPeriodo();
  openDoc({html:docs.map(d=>'<div class="docsep">'+d.html+'</div>').join(""),pdfDocs:docs,multi:true,name:"NC_originais_"+todayISO()+".pdf",title:"Não conformidades – documentos",
    short:"Documentos de não conformidade – "+per.lab+" – "+docs.length+" documentos",text:"*NÃO CONFORMIDADES – DOCUMENTOS*\nPeríodo: "+per.lab+"\n"+docs.length+" documentos"});
  toast(docs.length+" documento"+(docs.length>1?"s":"")+" pronto"+(docs.length>1?"s":"")+" para imprimir.");}
$("x-orig").onclick=imprimirOriginais;


/* ---- Aéreo ---- */
function fxAero(){const rows=fxNoPeriodo(FECH.dados&&FECH.dados.aero).map(r=>Object.assign(r,{_q:pnum(r.Quantidade),_v:pnum(r["Vlr. Total"])})),tit="Auditoria Aéreo (operador) — Fechamento";
  const ops={};rows.forEach(r=>{const k=r.Matricula_Operador||r.Operador;const x=ops[k]=ops[k]||{n:r.Operador||k,i:0,q:0,v:0};x.i++;x.q+=r._q;x.v+=r._v;});
  const tipos={};rows.forEach(r=>{const k=String(r["Tipo de O.S"]||"—");tipos[k]=(tipos[k]||0)+1;});const ruas={};rows.forEach(r=>{const k=unz(r.Rua)||"—";ruas[k]=(ruas[k]||0)+1;});
  const aud={};rows.forEach(r=>{const k=r.Nome_Auditor||"—";aud[k]=(aud[k]||0)+1;});const itens={};rows.forEach(r=>{const k=r["Código"];const x=itens[k]=itens[k]||{d:r["Descrição"],i:0,q:0,v:0};x.i++;x.q+=r._q;x.v+=r._v;});
  const tot=rows.reduce((a,r)=>a+r._v,0),nOp=Object.keys(ops).length,maior=rows.slice().sort((a,b)=>b._v-a._v)[0],cores=["#2563EB","#7C3AED","#0EA5E9","#F97316","#16A34A","#CA8A04","#DC2626","#64748B"];
  const opTop=Object.values(ops).sort((a,b)=>b.i-a.i)[0];
  const porD={};rows.forEach(r=>{const k=fxDiaKey(r.ts);const x=porD[k]=porD[k]||{ts:r.ts,n:0};x.n++;});const linha=Object.keys(porD).sort().map(k=>({l:fxDia(porD[k].ts),v:porD[k].n,txt:String(porD[k].n)}));
  return fxHead(tit,rows.length)+
    fxKpis([{t:"Não conformidades",v:rows.length,c:"#DC2626",s:Object.keys(porD).length+" dia"+(Object.keys(porD).length===1?"":"s")+" com NC"},{t:"Operadores com NC",v:nOp,c:"#0F172A",s:nOp?(rows.length/nOp).toFixed(1).replace(".",",")+" NC por operador":""},
      {t:"O.S. auditadas",v:new Set(rows.map(r=>r["O.S"])).size},{t:"Valor médio por NC",v:BRL0(rows.length?tot/rows.length:0),c:"#B45309",s:maior?"maior: "+BRL0(maior._v)+" · "+curto(maior.Operador||""):""},
      {t:"Valor total",v:BRL0(tot),c:"#B45309",s:opTop?"mais NCs: "+curto(opTop.n)+" ("+opTop.i+")":""}],true)+
    '<div class="fx-row" style="grid-template-columns:1fr 1fr">'+
      fxCard("NCs por operador",fxBars(Object.values(ops).sort((a,b)=>b.i-a.i||b.v-a.v).slice(0,8).map(x=>({l:curto(x.n),v:x.i,txt:x.i+" NC · "+BRL0(x.v),c:"#DC2626"}))).replace(/class="fx-bars"/,'class="fx-bars fx-bars-w"'))+
      fxCard("Ruas com mais ocorrências",fxBars(Object.entries(ruas).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>({l:"Rua "+k,v,txt:v+" NC",c:"#0EA5E9"}))))+'</div>'+
    '<div class="fx-row" style="grid-template-columns:1.7fr 1fr 1fr">'+
      fxCard("Itens com mais ocorrências",fxTable([{t:"Código"},{t:"Descrição"},{t:"Ocorr.",n:1},{t:"Un",n:1},{t:"Valor",n:1}],Object.entries(itens).sort((a,b)=>b[1].i-a[1].i||b[1].v-a[1].v).slice(0,6).map(([k,x])=>[esc(k),esc(String(x.d||"").slice(0,28)),x.i,x.q,BRL0(x.v)])))+
      fxCard("Tipo de O.S.",fxDonut(Object.entries(tipos).sort((a,b)=>b[1]-a[1]).map(([k,v],i)=>({l:"Tipo "+k,v,c:cores[i%cores.length]}))))+
      fxCard("Auditores — lançamentos",fxBars(Object.entries(aud).sort((a,b)=>b[1]-a[1]).map(([n,v])=>({l:curto(n),v,txt:String(v),c:"#3B82F6"}))).replace(/class="fx-bars"/,'class="fx-bars fx-bars-s"'))+'</div>'+
    fxFull("Lançamentos de não conformidade por dia (somente dias com auditoria)",fxLine(linha,"#DC2626",null,130))+fxFoot("Auditoria Aéreo");}

/* ---- Setores ---- */
function sobrasRows(){const src=(FECH.dados&&Array.isArray(FECH.dados.sobras)&&FECH.dados.sobras.length)?FECH.dados.sobras:SOBRAS;
  return dedupSobras(src).map(a=>({ts:pts(String(a[0]).replace(/^(\d{4})-(\d{2})-(\d{2})/,"$3/$2/$1")),os:a[1],cod:a[2],desc:a[3],q:pnum(a[4]),conf:a[6],sep:a[8],sepM:a[7],v:pnum(a[10]),tipo:a[12]||"Sobra"})).filter(o=>o.ts);}
/** Uma NC por separador + O.S. com sobra (regra da Expedição). */
function ncs8074(L){const m=new Map();L.filter(o=>o.tipo==="Sobra").sort((a,b)=>a.ts-b.ts).forEach(o=>{const k=(o.sepM||o.sep)+"|"+o.os;const x=m.get(k);if(x){x.itens++;x.q+=o.q;x.v+=o.v;}else m.set(k,{ts:o.ts,os:o.os,sep:o.sep,sepM:o.sepM,itens:1,q:o.q,v:o.v});});return [...m.values()];}
function fxPareto(S){const L=S.slice().sort((a,b)=>b.n-a.n),W=520,H=210,pl=12,pr=12,pt=18,pb=34,bw=(W-pl-pr)/L.length,mx=Math.max(1,...L.map(s=>s.n));
  return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block"><line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+(H-pb)+'" y2="'+(H-pb)+'" stroke="#E2E8F0"/>'+
    L.map((s,i)=>{const h=s.n/mx*(H-pt-pb),x=pl+bw*i+bw*.18;return '<rect x="'+x+'" y="'+(H-pb-h)+'" width="'+(bw*.64)+'" height="'+h+'" rx="3" fill="'+s.c+'"/><text x="'+(x+bw*.32)+'" y="'+(H-pb-h-5)+'" font-size="11" font-weight="700" text-anchor="middle" fill="#0F172A">'+s.n+'</text>'+
      '<text x="'+(x+bw*.32)+'" y="'+(H-pb+14)+'" font-size="9.5" text-anchor="middle" fill="#334155">'+esc(s.cur)+'</text>';}).join("")+'</svg>'+
    '<p class="fx-e" style="margin-top:2px">Não conformidades por setor, do maior para o menor.</p>';}
function fxSetores(){const tit="Não conformidades por setor — Fechamento";const [de,ate]=fxPeriodo();const len=Math.max(864e5,(isFinite(ate)?ate:Date.now())-de),pde=de-len;
  const ruasA=fxRows(FECH.dados&&FECH.dados.ruas).filter(r=>pbool(r.Possui_NC)),retA=fxRows(FECH.dados&&FECH.dados.retorno).filter(r=>pbool(r.Possui_NC)),carA=fxRows(FECH.dados&&FECH.dados.cargas),aerA=fxRows(FECH.dados&&FECH.dados.aero),s8=sobrasRows().filter(o=>o.tipo==="Sobra"),sobA=s8;
  const def=[{k:"rep",l:"Reposição — ruas",cur:"Repos. ruas",c:"#16A34A",rows:ruasA,val:r=>pnum(r.Valor_Divergencia),pes:r=>r.Nome_Colaborador_NC},
    {k:"ret",l:"Reposição — retorno",cur:"Repos. retorno",c:"#0E7490",rows:retA,val:r=>Math.abs(pnum(r.Valor_Divergencia)),pes:r=>r.Nome_Colaborador_NC},
    {k:"conf",l:"Cargas — conferência",cur:"Conferência",c:"#0EA5E9",rows:carA.filter(r=>r.Causador!=="Separador"),val:r=>pnum(r.Valor_Total),pes:r=>r.Nome_Causador||r.Nome_Conferente},
    {k:"sep",l:"Separação — cargas + sobras 8074",cur:"Separação",c:"#7C3AED",rows:carA.filter(r=>r.Causador==="Separador").concat(sobA),val:r=>r.Codigo_Produto!==undefined?pnum(r.Valor_Total):r.v,pes:r=>r.Nome_Causador||r.sep},
    {k:"aer",l:"Aéreo — operador",cur:"Aéreo",c:"#DC2626",rows:aerA,val:r=>pnum(r["Vlr. Total"]),pes:r=>r.Operador}];
  const S=def.map(d=>{const cur=d.rows.filter(r=>r.ts>=de&&r.ts<ate),ant=d.rows.filter(r=>r.ts>=pde&&r.ts<de);const v=cur.reduce((a,r)=>a+d.val(r),0);
    const p={};cur.forEach(r=>{const n=d.pes(r);if(n)p[n]=(p[n]||0)+1;});const topP=Object.entries(p).sort((a,b)=>b[1]-a[1])[0];
    return Object.assign({},d,{n:cur.length,ant:ant.length,v,med:cur.length?v/cur.length:0,pessoas:Object.keys(p).length,top:topP,cur:d.cur});});
  const tot=S.reduce((a,s)=>a+s.n,0),totV=S.reduce((a,s)=>a+s.v,0),totAnt=S.reduce((a,s)=>a+s.ant,0),ord=S.slice().sort((a,b)=>b.n-a.n),pior=ord[0];
  const varTxt=(n,a)=>a?((n-a)/a*100>0?"▲ ":"▼ ")+Math.abs(Math.round((n-a)/a*100))+"%":n?"novo":"—";const varCor=(n,a)=>n>a?"#DC2626":n<a?"#16A34A":"#64748B";
  const pessoas={};S.forEach(s=>s.rows.filter(r=>r.ts>=de&&r.ts<ate).forEach(r=>{const n=s.pes(r);if(!n)return;const x=pessoas[n+"|"+s.k]=pessoas[n+"|"+s.k]||{n,s,i:0,v:0};x.i++;x.v+=s.val(r);}));
  const sobPer=sobA.filter(r=>r.ts>=de&&r.ts<ate);
  return fxHead(tit,tot)+
    fxKpis(S.map(s=>({t:s.l,v:s.n,c:s.c,s:BRL0(s.v)+" · "+(tot?Math.round(s.n/tot*100):0)+"% · "+varTxt(s.n,s.ant),sc:varCor(s.n,s.ant)})).concat([{t:"Total de NCs",v:tot,c:"#0F172A",s:BRL0(totV)+" · "+varTxt(tot,totAnt)+" vs período anterior",sc:varCor(tot,totAnt)}]),true)+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Não conformidades por setor",fxPareto(S))+'</div>'+
    '<div class="fx-col">'+fxCard("Setor com mais NCs",pior&&pior.n?'<p style="margin:2px 0 4px;font-size:24px;font-weight:700;color:'+pior.c+'">'+esc(pior.l)+'</p><p class="fx-e" style="color:#0F172A;font-size:12px">'+pior.n+' NCs · '+(tot?pc0(pior.n/tot):"")+' do total · '+BRL0(pior.v)+'<br>Maior ofensor: <b>'+esc(pior.top?curto(pior.top[0])+" ("+pior.top[1]+")":"—")+'</b> · '+varTxt(pior.n,pior.ant)+' vs período anterior</p>':'<p class="fx-e">Sem NCs no período.</p>')+
      fxCard("Participação no total",fxDonut(S.map(s=>({l:s.cur,v:s.n,c:s.c}))))+'</div></div>'+
    fxFull("Comparativo por setor",fxTable([{t:"Setor"},{t:"NCs",n:1},{t:"% do total",n:1},{t:"Valor",n:1},{t:"Valor médio/NC",n:1},{t:"Pessoas com NC",n:1},{t:"Maior ofensor"},{t:"Período anterior",n:1},{t:"Variação",n:1}],
      ord.map(s=>['<b style="color:'+s.c+'">'+esc(s.l)+'</b>','<b>'+s.n+'</b>',tot?pc0(s.n/tot):"—",BRL0(s.v),BRL0(s.med),s.pessoas,esc(s.top?curto(s.top[0])+" ("+s.top[1]+")":"—"),s.ant,'<b style="color:'+varCor(s.n,s.ant)+'">'+varTxt(s.n,s.ant)+'</b>'])))+
    '<div class="fx-g3" style="margin-top:10px">'+fxCard("Valor por setor",fxBars(S.slice().sort((a,b)=>b.v-a.v).map(s=>({l:s.cur,v:s.v,txt:BRL0(s.v),c:s.c}))))+
      fxCard("Colaboradores com mais NCs",fxBars(Object.values(pessoas).sort((a,b)=>b.i-a.i||b.v-a.v).slice(0,7).map(x=>({l:curto(x.n)+" · "+x.s.cur,v:x.i,txt:String(x.i),c:x.s.c}))))+
      fxCard("Sobras 8074 por separador (contagem)",(function(){const o={};sobPer.forEach(s=>{const k=s.sepM||s.sep||"—";const x=o[k]=o[k]||{n:s.sep||k,i:0,q:0,os:new Set()};x.i++;x.q+=s.q;x.os.add(s.os);});
        const L=Object.values(o).sort((a,b)=>b.i-a.i||b.q-a.q).slice(0,10);
        return fxBars(L.map(x=>({l:curto(x.n)+" · "+x.os.size+" O.S.",v:x.i,txt:x.i+" sobra"+(x.i===1?"":"s"),c:"#7C3AED"})))+'<p class="fx-e" style="margin-top:6px">Somente quantidade superior, sem duplicatas (mesma O.S. e hora; mesmo item na O.S.). '+sobPer.length+' sobras de '+Object.keys(o).length+' separadores no período.</p>';})())+'</div>'+fxFoot("Setores auditados");}

// auditoria aéreo (operadores de empilhadeira)
const ENC_AERO={nome:"ANTONIO MAICON TEIXEIRA DE OLIVEIRA",mat:"10002407"};
const AER_COLS=["ID_Auditoria","Data","DataHora","Matricula_Operador","Operador","Código","Descrição","Rua","O.S","Tipo de O.S","Quantidade","Vl_Ult_Entrada","Vlr. Total","Observacao","Matricula_Auditor","Nome_Auditor","Status_NC"];
function searchOper(q){const L=searchColab(q);return L.sort((a,b)=>(/EMPILHADEIRA/.test(b.s)?1:0)-(/EMPILHADEIRA/.test(a.s)?1:0));}
const AE={prod:null,fotos:[]};
async function addFotoAE(e){const f=e.target.files[0];e.target.value="";if(!f||AE.fotos.length>=3)return;try{AE.fotos.push(await compress(f));setErr("a-foto-f","");paintAE();}catch(x){toast("Não foi possível ler a foto.");}}
