const CG={prod:null,mot:"",fotos:[],cau:""};
const gProd=picker($("g-prod"),{ph:"Código ou descrição do produto",search:searchProd,describe:descProd,onPick:k=>{CG.prod=k;paintCG();if(k!=null)setTimeout(()=>QW.g&&QW.g.focus(),50);}});
