function carRecs(){return SC?allRecs().filter(r=>r._aba==="cargas"&&r.ID_Sessao===SC.id):[];}
function porMotivo(recs){const m={Falta:{n:0,q:0,v:0},Avaria:{n:0,q:0,v:0},Abastecimento:{n:0,q:0,v:0},Sobras:{n:0,q:0,v:0},"Produto trocado":{n:0,q:0,v:0}};recs.forEach(r=>{const x=m[r.Motivo];if(x){x.n++;x.q+=+r.Quantidade||0;x.v+=+r.Valor_Total||0;}});return m;}
function renderCS(){const box=$("cs-box");if(!box)return;
  if(!SC){$("cg-form").hidden=true;$("g-list").innerHTML="";if(box.dataset.mode==="start")return;box.dataset.mode="start";
    box.innerHTML='<h3>Conferência da carga</h3><p class="note" style="margin-top:0">Informe Box, O.S. e conferente uma vez e lance todos os itens com ocorrência. No fim, finalize para gerar o PDF.</p>'+
      '<div class="row3"><div class="field" id="cs-box-f"><label for="cs-boxn">Box</label><input class="in" id="cs-boxn" inputmode="numeric" placeholder="Ex.: 12"></div>'+
      '<div class="field" id="cs-os-f"><label for="cs-os">Número da O.S.</label><input class="in" id="cs-os" inputmode="numeric" placeholder="Ex.: 458812"></div></div>'+
      '<div class="field" id="cs-conf-f"><label>Conferente</label><div id="cs-conf"></div></div>'+
      '<button type="button" class="save" id="cs-go" style="margin-top:14px">Iniciar conferência</button>';
    const cp=picker($("cs-conf"),{ph:"Matrícula ou nome do conferente",search:searchColab,describe:descColab});
    $("cs-go").onclick=()=>{if(!auditor){toast("Faça login primeiro.");return;}
      const bx=$("cs-boxn").value.trim(),os=$("cs-os").value.trim();let bad=false;
      if(!bx){setErr("cs-box-f","Informe o box.");bad=true;}else setErr("cs-box-f","");
      if(!os){setErr("cs-os-f","Informe a O.S.");bad=true;}else setErr("cs-os-f","");
      if(cp.value==null){setErr("cs-conf-f","Informe o conferente.");bad=true;}else setErr("cs-conf-f","");
      if(bad)return;const ci=cp.value;
      SC={id:newId("CG"),box:bx,os,conf:C.mat[ci],confNome:C.nome[ci],aud:auditor,audNome:nomeAud(),ini:Date.now()};
      store.set("audcd_sessao_car",SC);resetCG();renderCS();toast("Conferência da O.S. "+os+" iniciada.");gProd.focus();};
    return;}
  box.dataset.mode="on";$("cg-form").hidden=false;
  const recs=carRecs(),m=porMotivo(recs),tot=recs.reduce((a,r)=>a+(+r.Valor_Total||0),0);
  box.innerHTML='<div class="sess-top"><div><h3>Box '+esc(SC.box)+' · O.S. '+esc(SC.os)+'</h3><div class="note" style="margin:4px 0 0">Conferente: <b>'+esc(SC.confNome)+'</b> · '+esc(SC.conf)+'</div></div></div>'+
    '<div class="cg-sum">'+Object.entries(m).map(([k,x])=>'<div><b>'+x.n+'</b><span>'+k+'</span></div>').join("")+'</div>'+
    '<div class="sess-stats" style="margin-top:8px"><span><b>'+recs.length+'</b> ite'+(recs.length===1?'m':'ns')+'</span><span><b>'+BRL.format(tot)+'</b> valor total</span></div>'+
    '<button type="button" class="save" id="cs-rel" style="margin-top:12px">Imprimir NC do conferente</button><button type="button" class="btn full" id="cs-end" style="margin-top:8px">Finalizar carga</button>'+
    '<p class="note" style="margin:6px 0 0">Só as ocorrências em que o <b>causador é o conferente</b> geram não conformidade impressa. As do separador ficam registradas para o fechamento.</p>';
  $("cs-rel").onclick=()=>{if(!recs.length){toast("Nenhum item lançado ainda.");return;}openCarDoc(SC,recs);};
  {const nConf=recs.filter(r=>r.Causador==="Conferente").length;$("cs-rel").textContent="Imprimir NC do conferente"+(nConf?" · "+nConf:"");}
  $("cs-end").onclick=()=>{if(!recs.length){if(confirm("Nenhum item lançado. Encerrar mesmo assim?")){SC=null;store.set("audcd_sessao_car",null);resetCG();renderCS();}return;}
    const s0=SC;openCarDoc(s0,recs,()=>{SC=null;store.set("audcd_sessao_car",null);resetCG();renderCS();toast("Conferência da O.S. "+s0.os+" finalizada.");});};
  $("g-list").innerHTML=recs.length?'<div class="block"><h3>Itens da O.S. '+esc(SC.os)+' <small>'+recs.length+'</small></h3>'+recs.map(r=>
      '<div class="li"><div><div class="d"><b>'+esc(r.Codigo_Produto)+'</b> – '+esc(r.Descricao_Produto)+'</div><div class="tags"><span class="tag '+(r.Motivo==="Sobras"?"":"nc")+'">'+esc(r.Motivo)+'</span>'+(r.Causador?'<span class="tag">'+esc(r.Causador)+': '+esc(curto(r.Nome_Causador))+'</span>':'')+((r.fotos||[]).length?'<span class="tag">'+r.fotos.length+' foto'+(r.fotos.length>1?'s':'')+'</span>':'')+'</div></div>'+
      '<div><div class="v">'+esc(r.Quantidade)+' un<br>'+BRL.format(+r.Valor_Total||0)+'</div><div class="act"><button type="button" class="btn sm" data-gx="'+esc(r.ID_Auditoria)+'">Excluir</button></div></div></div>').join("")+'</div>':"";
  $("g-list").querySelectorAll("[data-gx]").forEach(b=>b.onclick=()=>delRec(b.dataset.gx).then(()=>renderCS()));}
function paintCG(){if(!$("g-info"))return;if(window.QW&&QW.g)QW.g.refresh();renderCS();const k=CG.prod;
  if(k!=null){const pk=eByProd.get(P.cod[k]);$("g-info").innerHTML='<div class="rack" style="margin-top:10px"><div class="rack-body"><div class="d">'+esc(P.desc[k])+'</div><div class="m"><span>Cód. '+esc(P.cod[k])+'</span><span>R$ '+VL4.format(P.vl[k])+'/un</span>'+(pk!=null?'<span>Picking '+esc(E.id[pk])+'</span>':'')+'</div></div></div>';
    $("g-cx-h").textContent=pk!=null&&E.qt[pk]?"1 caixa = "+E.qt[pk]+" un":"";}else{$("g-info").innerHTML="";$("g-cx-h").textContent="";}
  const q=gq()||0,vl=k!=null?P.vl[k]:0;$("g-valor").textContent=BRL.format(q*vl);$("g-calc").textContent=q+" un × "+BRL.format(vl);
  document.querySelectorAll(".mot button[data-m]").forEach(b=>b.setAttribute("aria-checked",b.dataset.m===CG.mot));
  document.querySelectorAll(".cau button").forEach(b=>b.setAttribute("aria-checked",b.dataset.c===CG.cau));
  $("g-sep-w").hidden=CG.cau!=="Separador";
  $("g-cau-h").textContent=CG.cau==="Conferente"&&SC?"Ocorrência atribuída ao conferente "+curto(SC.confNome)+".":CG.cau==="Separador"?"Escolha quem separou o item.":"";
  $("g-foto-f").hidden=!CG.mot;
  const box=$("g-fotos");box.innerHTML=CG.fotos.map((s,i)=>'<div class="ph-it"><img src="'+s+'" alt="Foto '+(i+1)+'"><button type="button" data-i="'+i+'" aria-label="Remover foto">×</button></div>').join("");
  box.querySelectorAll("button").forEach(b=>b.onclick=()=>{CG.fotos.splice(+b.dataset.i,1);paintCG();});
  $("g-cam").hidden=$("g-gal").hidden=CG.fotos.length>=3;}
function resetCG(){gProd.clear();CG.prod=null;CG.mot="";CG.fotos=[];CG.cau="";gSep.clear();$("g-qtd").value="";if(window.QW&&QW.g)QW.g.reset();document.querySelectorAll("#v-cargas .field.bad").forEach(f=>setErr(f.id,""));paintCG();}
$("g-save").addEventListener("click",async()=>{
  if(!auditor){toast("Faça login primeiro.");return;}if(!SC){toast("Inicie a conferência primeiro.");return;}
  const errs=[],chk=(c,f,m)=>{setErr(f,c?m:"");if(c)errs.push(f);};const q=gq();
  chk(CG.prod==null,"g-prod-f","Escolha o item.");
  chk(!(q>0),"g-qtd-f","Informe a quantidade.");
  chk(!CG.mot,"g-mot-f","Escolha o motivo.");
  chk(!CG.cau,"g-cau-f","Escolha o causador da ocorrência.");
  chk(CG.cau==="Separador"&&gSep.value==null,"g-cau-f","Informe o separador.");
  chk(CG.mot&&!CG.fotos.length,"g-foto-f","Tire ao menos uma foto da ocorrência.");
  if(errs.length){$(errs[0]).scrollIntoView({block:"center",behavior:"smooth"});toast("Revise os campos marcados.");return;}
  const now=new Date(),k=CG.prod,vl=P.vl[k];
  const rec={_aba:"cargas",ID_Auditoria:newId("CG"),DataHora:fmtDT(now),ts:now.getTime(),Matricula_Auditor:auditor,Nome_Auditor:nomeAud(),
    Matricula_Conferente:SC.conf,Nome_Conferente:SC.confNome,Box:SC.box,Numero_OS:SC.os,Codigo_Produto:P.cod[k],Descricao_Produto:P.desc[k],
    Quantidade:q,Motivo:CG.mot,Causador:CG.cau,Matricula_Causador:CG.cau==="Separador"?C.mat[gSep.value]:SC.conf,Nome_Causador:CG.cau==="Separador"?C.nome[gSep.value]:SC.confNome,Valor_Total:Math.round(q*vl*100)/100,Vl_Unit:vl,Possui_NC:true,ID_Sessao:SC.id,
    Sessao:{id:SC.id,box:SC.box,os:SC.os,conf:SC.conf,confNome:SC.confNome,aud:SC.aud,audNome:SC.audNome},fotos:CG.fotos.slice()};
  $("g-save").disabled=true;const ok=await saveRec(rec);$("g-save").disabled=false;
  resetCG();window.scrollTo(0,0);toast((ok||dbState==="off"?"Item salvo":"Salvo neste aparelho, envio pendente")+" – "+rec.Motivo+".");gProd.focus();
});
// cargas: impressão somente das ocorrências causadas pelo conferente
const ehDoConf=r=>r.Causador==="Conferente";
const ENC_REPOSICAO={nome:"FABIO NYCKOLAS FIGUEIREDO BOTERO",mat:"10003993"},ENC_CARGAS={nome:"LUCAS HENRIQUE NUNES",mat:"10001917"};
function carDocHTML(S,recs){const L=recs.filter(ehDoConf).sort((a,b)=>a.ts-b.ts),tot=L.reduce((a,r)=>a+(+r.Valor_Total||0),0),un=L.reduce((a,r)=>a+(+r.Quantidade||pnum(r.Quantidade)||0),0);
  const row=(k,v)=>'<tr><td class="k">'+k+'</td><td>'+(v===""||v==null?"–":esc(v))+'</td></tr>';const first=L[0],last=L[L.length-1];
  return '<div class="pd"><div class="pd-h"><img src="'+LOGO_BLUE+'" alt="Santa Therezinha"><div class="r"><h1>Não conformidades do conferente – O.S. '+esc(S.os)+'</h1><p>Box '+esc(S.box)+' · Nº '+esc(S.id)+'</p></div></div>'+
   '<h2>Identificação</h2><table>'+row("Período",(first?first.DataHora:"")+(last&&last!==first?" a "+String(last.DataHora).slice(11):""))+row("Box",S.box)+row("Número da O.S.",S.os)+
   row("Conferente",S.confNome+" – matrícula "+S.conf)+row("Auditor",(S.audNome||"")+" – matrícula "+S.aud)+'</table>'+
   '<div class="sum"><div><b>'+L.length+'</b><span>ocorrências do conferente</span></div><div><b>'+un+'</b><span>unidades</span></div><div><b>'+BRL.format(tot)+'</b><span>valor</span></div><div><b>'+esc(S.box)+'</b><span>box</span></div></div>'+
   '<h2>Ocorrências em que o conferente foi o causador</h2><table class="lt"><thead><tr><th>Item</th><th>Motivo</th><th>Qtd. (un)</th><th>Vl. un.</th><th>Valor</th></tr></thead><tbody>'+
   L.map(r=>{const q=+r.Quantidade||pnum(r.Quantidade)||0,v=+r.Valor_Total||pnum(r.Valor_Total)||0;return '<tr><td>'+esc(r.Codigo_Produto+" – "+r.Descricao_Produto)+'</td><td>'+esc(r.Motivo)+'</td><td class="n">'+q+'</td><td class="n">'+BRL.format(+r.Vl_Unit||(q?v/q:0))+'</td><td class="n">'+BRL.format(v)+'</td></tr>';}).join("")+
   '</tbody><tfoot><tr><td colspan="2">Total</td><td class="n">'+un+'</td><td></td><td class="n">'+BRL.format(tot)+'</td></tr></tfoot></table>'+
   '<p class="decl" style="margin-top:6px">Valores pelo Vl. ult. entrada da base 286.</p>'+
   fotosHTML(L.flatMap(r=>(r.fotos||[]).map(s=>({s,c:r.Codigo_Produto+" · "+r.Motivo}))))+
   termoHTML([...new Set(L.map(r=>r.Motivo))].map(m=>TERMO_TXT["car_"+m]).filter(Boolean),tot)+
   '<p class="decl">Declaro ciência das não conformidades de minha responsabilidade registradas na auditoria da carga da O.S. '+esc(S.os)+', box '+esc(S.box)+'.</p>'+
   '<div class="sg"><div><b>Conferente</b>'+esc(S.confNome)+'<small>Matrícula '+esc(S.conf)+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Auditor</b>'+esc(S.audNome||"")+'<small>Matrícula '+esc(S.aud)+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Encarregado da equipe de cargas</b>'+ENC_CARGAS.nome+'<small>Matrícula '+ENC_CARGAS.mat+'</small><small>Data: ___/___/______</small></div></div></div>';}
function carText(S,recs){const L=recs.filter(ehDoConf),tot=L.reduce((a,r)=>a+(+r.Valor_Total||0),0),un=L.reduce((a,r)=>a+(+r.Quantidade||0),0);
  return ["*NC DO CONFERENTE – O.S. "+S.os+"*","Box "+S.box,"Conferente: "+S.confNome+" ("+S.conf+")","Auditor: "+(S.audNome||"")+" ("+S.aud+")",L.length+" itens · "+un+" un","*Valor: "+BRL.format(tot)+"*"].join("\n");}
function openCarDoc(S,recs,onClose){const F=recs.filter(ehDoConf);
  if(!F.length){toast("Nenhuma ocorrência causada pelo conferente: não há não conformidade para imprimir.");if(onClose)onClose();return;}
  const tot=F.reduce((a,r)=>a+(+r.Valor_Total||0),0);
  openDoc({html:carDocHTML(S,recs),multi:true,name:"NC_Conferente_OS"+S.os+"_"+S.id+".pdf",title:"NC do conferente – O.S. "+S.os,
    short:"NC do conferente – O.S. "+S.os+" – Box "+S.box+" – "+BRL.format(tot),text:carText(S,recs),onClose,closeLabel:onClose?"Concluir":"Fechar"});}



// quantidade em caixas + unidades (fator QTUNITCX da 8022)
window.QW={};
function fatorCx(k){if(k==null)return 0;const pk=eByProd.get(P.cod[k]);return pk!=null?(E.qt[pk]||0):0;}
function qtdCxUn(id,prodFn){const inp=$(id);if(!inp)return null;const st=inp.closest(".stepper");if(st)st.hidden=true;
  const w=document.createElement("div");w.className="cxun";
  const bloco=(k,lab)=>'<div><span class="cxl">'+lab+'</span><div class="stepper"><button type="button" data-d="-1" data-w="'+k+'" aria-label="Diminuir '+lab+'">−</button><input class="in" type="number" inputmode="numeric" min="0" step="1" data-w="'+k+'" placeholder="0" aria-label="'+lab+'"><button type="button" data-d="1" data-w="'+k+'" aria-label="Aumentar '+lab+'">+</button></div></div>';
  w.innerHTML='<div class="cxun-r">'+bloco("cx","Caixas")+bloco("un","Unidades")+'</div><div class="cxun-t"></div>';
  (st||inp).after(w);
  const cx=w.querySelector('input[data-w="cx"]'),un=w.querySelector('input[data-w="un"]'),tt=w.querySelector(".cxun-t");
  const val=i=>i.value===""?null:Math.max(0,parseInt(i.value,10)||0);
  function paintT(){const f=prodFn()!=null?fatorCx(prodFn()):0;const sem=prodFn()!=null&&!f;cx.disabled=sem;w.classList.toggle("semcx",sem);
    if(sem&&cx.value!==""){cx.value="";}
    const tot=inp.value===""?null:+inp.value,c=val(cx)||0,u=val(un)||0;
    tt.innerHTML=(f?'1 cx = <b>'+f+' un</b>':(prodFn()==null?'Escolha o item para usar caixas.':'Item sem qtd. por caixa na 8022: informe em unidades.'))+
      (tot!=null?' · Total: <b class="cxun-tot">'+tot+' un</b>'+(f&&c?' <small>('+c+' cx × '+f+(u?' + '+u+' un':'')+')</small>':''):'');}
  function sync(){const f=fatorCx(prodFn()),c=val(cx),u=val(un);const novo=(c==null&&u==null)?"":String((c||0)*f+(u||0));
    if(String(inp.value)!==novo){inp.value=novo;paintT();inp.dispatchEvent(new Event("input",{bubbles:true}));}else paintT();}
  cx.addEventListener("input",sync);un.addEventListener("input",sync);
  w.querySelectorAll("button[data-d]").forEach(b=>b.onclick=()=>{const i=b.dataset.w==="cx"?cx:un;if(i.disabled)return;i.value=Math.max(0,(parseInt(i.value,10)||0)+ +b.dataset.d);sync();});
  return {reset(){cx.value="";un.value="";inp.value="";paintT();},refresh(){if(cx.value!==""||un.value!=="")sync();else paintT();},focus(){(cx.disabled?un:cx).focus();},
    resumo(){const c=val(cx)||0,u=val(un)||0,f=fatorCx(prodFn());return f&&c?c+" cx"+(u?" + "+u+" un":""):"";}};}
QW.r=qtdCxUn("r-qtd",()=>R.prod);QW.a=qtdCxUn("a-qtd",()=>AE.prod);QW.qe=qtdCxUn("t-qe",()=>RT.prod);QW.qf=qtdCxUn("t-qf",()=>RT.prod);QW.g=qtdCxUn("g-qtd",()=>CG.prod);
Object.values(QW).forEach(q=>q&&q.reset());


