aplicarExtras();
function salvarExtra(m,n,f){const L=store.get("audcd_colab_extra",[]);const i=L.findIndex(x=>x.m===m);const o={m,n,f,sync:false};if(i>=0)L[i]=Object.assign(L[i],o);else L.push(o);store.set("audcd_colab_extra",L);}
async function enviarColabs(){const L=store.get("audcd_colab_extra",[]),pend=L.filter(x=>!x.sync);if(!pend.length||DEMO||!SHEET_URL||!navigator.onLine||!(LOGIN&&LOGIN.token))return;
  try{const r=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({acao:"colab_salvar",token:LOGIN.token,lista:pend.map(x=>[x.m,x.n,x.f])}),redirect:"follow",cache:"no-store"});const j=await r.json();
    if(j&&j.ok){const M=store.get("audcd_colab_extra",[]);M.forEach(x=>{if(pend.some(p=>p.m===x.m))x.sync=true;});store.set("audcd_colab_extra",M);}}catch(e){}}
const FUNCOES=()=>[...new Set(C.fun.filter(Boolean))].sort();
let NC_CB=null;
function novoColab(q,cb){NC_CB=cb;const s=String(q||"").trim();$("nc-mat").value=/^\d+$/.test(s)?s:"";$("nc-nome").value=/^\d+$/.test(s)?"":s.toUpperCase();$("nc-fun").value="";
  $("nc-funcs").innerHTML=FUNCOES().map(f=>'<option value="'+esc(f)+'">').join("");["nc-mat-f","nc-nome-f","nc-fun-f"].forEach(f=>setErr(f,""));
  $("nc-sheet").hidden=false;setTimeout(()=>($("nc-mat").value?$("nc-nome"):$("nc-mat")).focus(),60);}
$("nc-x").onclick=()=>{$("nc-sheet").hidden=true;NC_CB=null;};
$("nc-sheet").addEventListener("click",e=>{if(e.target.id==="nc-sheet"){$("nc-sheet").hidden=true;NC_CB=null;}});
$("nc-ok").onclick=()=>{const m=$("nc-mat").value.replace(/\D/g,""),n=$("nc-nome").value.trim().toUpperCase().replace(/\s+/g," "),f=$("nc-fun").value.trim().toUpperCase();let bad=false;
  if(m.length<4){setErr("nc-mat-f","Informe a matrícula.");bad=true;}else setErr("nc-mat-f","");
  if(n.length<3){setErr("nc-nome-f","Informe o nome completo.");bad=true;}else setErr("nc-nome-f","");
  if(!f){setErr("nc-fun-f","Informe a função.");bad=true;}else setErr("nc-fun-f","");
  if(bad)return;const existia=cIdx.has(m);const i=addC(m,n,f);salvarExtra(m,n,f);enviarColabs();
  $("nc-sheet").hidden=true;toast(existia?"Colaborador atualizado.":"Colaborador cadastrado: "+curtoNome(n)+".");
  const cb=NC_CB;NC_CB=null;if(cb)cb({key:i,t:C.nome[i],s:"Matrícula "+C.mat[i]+" · "+C.fun[i]});};

// base de funcionários (Quadro)
function parseQuadroWB(wb){const nomes=wb.SheetNames.slice().sort((a,b)=>(/quadro/i.test(b)?1:0)-(/quadro/i.test(a)?1:0));
  for(const sn of nomes){const rows=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:false,defval:""});
    const H=findHeader(rows,[x=>x.startsWith("MATRIC"),x=>x==="COLABORADOR"||x==="NOME"||x==="NOMECOLABORADOR"]);if(!H)continue;
    const im=H.h.findIndex(x=>x.startsWith("MATRIC")),in_=H.h.findIndex(x=>x==="COLABORADOR"||x==="NOME"||x==="NOMECOLABORADOR"),iff=H.h.findIndex(x=>x.startsWith("FUNC")||x==="CARGO");
    const out=[],seen=new Set();for(let r=H.i+1;r<rows.length;r++){const row=rows[r];const m=String(row[im]||"").trim().replace(/\.0+$/,""),n=String(row[in_]||"").trim().replace(/[\t\n\r]/g," ");if(!m||!n||seen.has(m))continue;seen.add(m);
      out.push(m+"\t"+n+"\t"+String(iff>=0?row[iff]:"").trim().replace(/[\t\n\r]/g," "));}
    if(out.length)return out.join("\n");}
  throw new Error("Não encontrei as colunas Matrícula e Colaborador (aba Quadro).");}
async function lerLivro(file){if(!window.XLSX){try{await loadScript(XLSX_URL_LOCAL());}catch(e){throw new Error("Para ler o Excel é preciso internet na primeira vez.");}}const buf=await file.arrayBuffer();return XLSX.read(buf,{type:"array",cellDates:true});}
function XLSX_URL_LOCAL(){return typeof XLSX_URL!=="undefined"?XLSX_URL:"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";}
$("bq-file").addEventListener("change",async e=>{const file=e.target.files[0];e.target.value="";if(!file)return;const msg=$("bq-msg");msg.style.color="";msg.textContent="Lendo "+file.name+"…";
  try{const wb=await lerLivro(file);const txt=parseQuadroWB(wb);loadC(txt);aplicarExtras();reposRotina();const info={ts:Date.now(),nome:file.name};BASEINFO.c=info;try{await IDB.set("base_c",{txt,info});}catch(x){}
    msg.textContent="Base atualizada: "+C.mat.length.toLocaleString("pt-BR")+" colaboradores.";paintBases();toast("Base de funcionários atualizada.");}
  catch(x){msg.style.color="var(--alert)";msg.textContent=x.message||"Não foi possível ler o arquivo.";}});

// rotina de retorno (8457)
let ROTINA=[],ROTINFO=null;
const rotObj=a=>Array.isArray(a)?{d:String(a[0]||""),os:String(a[1]||"").trim(),cod:String(a[2]||"").trim(),desc:a[3]||"",qtd:pnum(a[4]),rua:unz(String(a[5]||"").trim()),func:String(a[6]||"").trim(),nome:String(a[7]||"").trim()}:a;
function isoDe(v){if(v instanceof Date&&!isNaN(v))return v.getFullYear()+"-"+pad(v.getMonth()+1)+"-"+pad(v.getDate());const s=String(v||"").trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return m[1]+"-"+m[2]+"-"+m[3];
  m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);if(m){const y=m[3].length===2?"20"+m[3]:m[3];return y+"-"+pad(+m[2])+"-"+pad(+m[1]);}
  if(/^\d+(\.\d+)?$/.test(s)){const d=new Date(Math.round((+s-25569)*864e5));return d.getUTCFullYear()+"-"+pad(d.getUTCMonth()+1)+"-"+pad(d.getUTCDate());}return "";}
function parseRotinaWB(wb){for(const sn of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:""});
    const H=findHeader(rows,[x=>x==="NUMOS",x=>x==="CODPROD",x=>x==="RUAO",x=>x==="NOME"]);if(!H)continue;const ix=n=>H.h.indexOf(n);
    const iD=ix("DATA"),iO=ix("NUMOS"),iC=ix("CODPROD"),iDe=ix("DESCRICAO"),iQ=ix("QTD"),iR=ix("RUAO"),iF=ix("CODFUNCOS"),iN=ix("NOME");const out=[];
    for(let r=H.i+1;r<rows.length;r++){const row=rows[r];const os=String(row[iO]||"").trim().replace(/\.0+$/,"");if(!os||!/^\d+$/.test(os))continue;
      out.push([isoDe(row[iD]),os,String(row[iC]).trim().replace(/\.0+$/,""),String(iDe>=0?row[iDe]:"").trim(),cellNum(row[iQ]),String(row[iR]).trim().replace(/\.0+$/,""),String(iF>=0?row[iF]:"").trim().replace(/\.0+$/,""),String(row[iN]).trim()]);}
    if(out.length)return out;}
  throw new Error("Não encontrei as colunas NUMOS, CODPROD, RUA_O e NOME (relatório 8457).");}
function mesclarRotina(linhas){const k=a=>a[1]+"|"+a[2];const m=new Map(ROTINA.map(a=>[k(a),a]));linhas.forEach(a=>m.set(k(a),a));
  const lim=new Date();lim.setDate(lim.getDate()-90);const li=lim.getFullYear()+"-"+pad(lim.getMonth()+1)+"-"+pad(lim.getDate());
  ROTINA=[...m.values()].filter(a=>!a[0]||a[0]>=li);IDB.set("rotina",{rows:ROTINA,info:ROTINFO}).catch(()=>{});}
function rotinaPorOS(os){os=String(os||"").trim();return os?ROTINA.map(rotObj).filter(o=>o.os===os):[];}
function rotinaPorItem(cod,rua){const L=ROTINA.map(rotObj).filter(o=>o.cod===String(cod)&&(!rua||o.rua===String(rua)));return L.sort((a,b)=>a.d<b.d?1:-1);}
async function enviarRotina(linhas){if(DEMO||!SHEET_URL||!navigator.onLine||!(LOGIN&&LOGIN.token))return false;
  try{const r=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({acao:"rotina_salvar",token:LOGIN.token,linhas}),redirect:"follow",cache:"no-store"});const j=await r.json();if(!j.ok)throw new Error(j.erro);return j;}catch(e){toast("Rotina salva neste aparelho. Envio à planilha: "+(e.message||"falhou"));return false;}}
$("br-file").addEventListener("change",async e=>{const file=e.target.files[0];e.target.value="";if(!file)return;const msg=$("br-msg");msg.style.color="";msg.textContent="Lendo "+file.name+"…";
  try{const wb=await lerLivro(file);const linhas=parseRotinaWB(wb);ROTINFO={ts:Date.now(),nome:file.name};mesclarRotina(linhas);
    const dias=[...new Set(linhas.map(a=>a[0]).filter(Boolean))].sort();msg.textContent=linhas.length+" OS lidas ("+(dias.length?fdISO(dias[0])+(dias.length>1?" a "+fdISO(dias[dias.length-1]):""):"sem data")+"). Enviando à planilha…";paintBases();
    const j=await enviarRotina(linhas);msg.textContent=linhas.length+" OS lidas"+(j?" · "+j.adicionados+" novas gravadas na planilha (aba Rotina_Retorno).":" · guardadas neste aparelho.");toast("Rotina 8457 importada.");}
  catch(x){msg.style.color="var(--alert)";msg.textContent=x.message||"Não foi possível ler o arquivo.";}});
async function carregarApoio(){if(DEMO||!SHEET_URL||!navigator.onLine||!(LOGIN&&LOGIN.token))return;
  try{const r=await fetch(SHEET_URL+(SHEET_URL.includes("?")?"&":"?")+"acao=apoio&token="+encodeURIComponent(LOGIN.token)+"&t="+Date.now(),{cache:"no-store"});const j=await r.json();if(!j||!j.ok)return;
    (j.colaboradores||[]).forEach(a=>{if(a[0]&&a[1]){addC(String(a[0]),a[1],a[2]||"");const L=store.get("audcd_colab_extra",[]);if(!L.some(x=>x.m===String(a[0]))){L.push({m:String(a[0]),n:a[1],f:a[2]||"",sync:true});store.set("audcd_colab_extra",L);}}});
    if(Array.isArray(j.rotina)){ROTINA=j.rotina.map(a=>[isoDe(a[0]),String(a[1]),String(a[2]),a[3],a[4],String(a[5]),String(a[6]),a[7]]);ROTINFO={ts:Date.now(),nome:"planilha (aba Rotina_Retorno)"};IDB.set("rotina",{rows:ROTINA,info:ROTINFO}).catch(()=>{});}
    enviarColabs();paintBases();}catch(e){}}
function reposRotina(){}
IDB.get("base_c").then(c=>{if(c&&c.txt){loadC(c.txt);aplicarExtras();reposRotina();BASEINFO.c=c.info;}}).catch(()=>{}).then(()=>IDB.get("rotina")).then(c=>{if(c&&c.rows&&!ROTINA.length){ROTINA=c.rows;ROTINFO=c.info;reposRotina();}}).catch(()=>{});


// sessão de rua
function sessRecs(){return S?allRecs().filter(r=>r.ID_Sessao===S.id):[];}
function endSess(){S=null;store.set("audcd_sessao",null);setMode("prod");reset();renderSess();}
async function delRec(id){
  if(!confirm("Excluir este lançamento?"))return;
  HIST.delete(id);IDB.del(id).catch(()=>{});
  const qi=queue.findIndex(x=>x.rec.ID_Auditoria===id);
  if(qi>=0){queue.splice(qi,1);saveQueue();}
  else if(db){try{await db.collection("ruas").doc(id).delete();}catch(e){toast("Não foi possível excluir agora.");return;}}
  remote.ruas=remote.ruas.filter(r=>r.ID_Auditoria!==id);renderRecords();toast("Lançamento excluído.");
}
function renderSess(){
  const box=$("sess-box"),lst=$("sess-list");
  if(!S){
    $("r-save").textContent="Salvar auditoria";lst.innerHTML="";
    if(box.dataset.mode==="start")return;box.dataset.mode="start";
    box.innerHTML='<h3>Auditar uma rua inteira</h3><p class="note" style="margin-top:0">Informe a rua e o repositor uma vez e lance todos os endereços em sequência, quantos precisar.</p>'+
      '<div class="field" id="ss-rua-f"><label for="ss-rua">Rua</label><input class="in" id="ss-rua" type="text" inputmode="numeric" placeholder="Ex.: 44"></div>'+
      '<div class="field" id="ss-rep-f"><label>Repositor da rua</label><div id="ss-rep"></div><div class="hint" id="ss-rep-h">Preenchido pelo quadro de repositores ao digitar a rua.</div></div>'+
      '<button type="button" class="save" id="ss-go" style="margin-top:14px">Iniciar auditoria da rua</button>';
    const sp=picker($("ss-rep"),{ph:"Matrícula do repositor (ou nome)",search:searchColab,describe:descColab});
    $("ss-rua").addEventListener("input",()=>{const rua=String(parseInt($("ss-rua").value.replace(/\D/g,""),10)||"");const reps=repsDaRua(rua).filter(m=>cIdx.has(m));const hh=$("ss-rep-h");
      if(reps.length){sp.set(cIdx.get(reps[0]));hh.textContent="Pelo quadro: "+reps.map(m=>curto(nomeC(m))).join(" e ")+(reps.length>1?". Se for o outro, toque em Trocar.":".");}
      else hh.textContent=rua?"Rua sem repositor no quadro. Escolha o repositor.":"Preenchido pelo quadro de repositores ao digitar a rua.";});
    $("ss-go").onclick=()=>{
      if(!auditor){$("sheet").hidden=false;return;}
      const rua=String(parseInt($("ss-rua").value.replace(/\D/g,""),10)||"");let bad=false;
      if(!rua||!RUAS.has(rua)){setErr("ss-rua-f","Rua não encontrada na base de endereços.");bad=true;}else setErr("ss-rua-f","");
      if(sp.value==null){setErr("ss-rep-f","Informe o repositor da rua.");bad=true;}else setErr("ss-rep-f","");
      if(bad)return;
      const ci=sp.value;
      S={id:newId("R"+rua),rua,rep:C.mat[ci],repNome:C.nome[ci],repFun:C.fun[ci],aud:auditor,audNome:nomeAud(),ini:Date.now()};
      store.set("audcd_sessao",S);setMode("end");reset();renderSess();toast("Rua "+rua+" iniciada. Lance os endereços.");rEnd.focus();
    };
    return;
  }
  box.dataset.mode="on";
  const recs=sessRecs(),ncs=recs.filter(r=>r.Possui_NC),tot=ncs.reduce((a,r)=>a+(+r.Valor_Divergencia||0),0);
  const totRua=E.pt.filter(a=>a[0]===S.rua).length,done=new Set(recs.map(r=>fmtAddr(r.Endereco))).size;
  $("r-save").textContent="Salvar e lançar próximo";
  box.innerHTML='<div class="sess-top"><div><h3>Rua '+esc(S.rua)+'</h3><div class="note" style="margin:4px 0 0">Repositor: <b>'+esc(S.repNome)+'</b> · '+esc(S.rep)+'</div></div><button type="button" class="link" id="ss-chg">Trocar repositor</button></div>'+
    '<div class="prog" role="progressbar" aria-valuemin="0" aria-valuemax="'+totRua+'" aria-valuenow="'+done+'"><i style="width:'+Math.min(100,Math.round(done/Math.max(1,totRua)*100))+'%"></i></div>'+
    '<div class="sess-stats"><span><b>'+done+'</b> de '+totRua+' endereços</span><span><b>'+ncs.length+'</b> NC</span><span><b>'+BRL.format(tot)+'</b> em divergência</span></div>'+
    '<div id="ss-chg-box"></div>'+
    '<div class="row-btns"><button type="button" class="btn" id="ss-rel">Relatório da rua</button><button type="button" class="btn" id="ss-end">Encerrar rua</button></div>';
  $("ss-rel").onclick=()=>openSessDoc(S,recs);
  $("ss-end").onclick=()=>{
    if(!recs.length){if(confirm("Nenhum endereço lançado nesta rua. Encerrar mesmo assim?"))endSess();return;}
    const s0=S;openSessDoc(s0,recs,()=>{endSess();toast("Rua "+s0.rua+" encerrada.");});
  };
  $("ss-chg").onclick=()=>{const b=$("ss-chg-box");b.innerHTML='<div class="field"><label>Novo repositor</label><div id="ss-rep2"></div></div>';
    picker($("ss-rep2"),{ph:"Matrícula do repositor (ou nome)",search:searchColab,describe:descColab,onPick:k=>{if(k==null)return;
      S.rep=C.mat[k];S.repNome=C.nome[k];S.repFun=C.fun[k];store.set("audcd_sessao",S);rRep.set(k);renderSess();toast("Repositor alterado para os próximos lançamentos.");}}).focus();};
  lst.innerHTML=recs.length?'<div class="block"><h3>Lançamentos da rua '+esc(S.rua)+' <small>'+recs.length+(recs.length>1?' endereços':' endereço')+'</small></h3>'+
    recs.map(r=>{const id=esc(r.ID_Auditoria);return '<div class="li"><div><div class="a">'+esc(fmtAddr(r.Endereco))+'</div><div class="d">'+esc(r.Produto+" – "+r.Descricao_Produto)+'</div><div class="tags">'+
      (r.Possui_NC?ocList(r).map(([k])=>'<span class="tag nc">'+OC_TXT[k][0]+'</span>').join(""):'<span class="tag ok">Conforme</span>')+'</div></div>'+
      '<div><div class="v">'+(r.Possui_NC?esc(r.Qtd_Divergencia_Un)+' un<br>'+BRL.format(+r.Valor_Divergencia||0):'')+'</div><div class="act">'+
      (r.Possui_NC?'<button type="button" class="btn sm" data-p="'+id+'">NC</button>':'')+'<button type="button" class="btn sm" data-x="'+id+'">Excluir</button></div></div></div>';}).join("")+'</div>':'';
  lst.querySelectorAll("[data-p]").forEach(b=>b.onclick=()=>{const r=recs.find(x=>x.ID_Auditoria===b.dataset.p);if(r)openPrint(r);});
  lst.querySelectorAll("[data-x]").forEach(b=>b.onclick=()=>delRec(b.dataset.x));
}
