const OC_TXT={
 erro:["Produto no lugar errado","Item armazenado fora do endereço de picking cadastrado. Provoca ruptura no picking, erro de separação e pedidos incompletos, além de divergência no inventário e retrabalho para localizar o produto."],
 venc:["Próximo do vencimento","Produto com validade próxima no endereço. Sem tratativa imediata (giro FEFO, ação comercial ou devolução), vira perda por vencimento e há risco de enviar produto vencido ao cliente."],
 saldo:["Sem saldo / furo de estoque","O endereço não tem o produto que o sistema indica. Causa corte de pedidos e ruptura na separação, distorce o estoque físico x sistema e afeta diretamente o nível de serviço ao cliente."],
 avaria:["Avaria","Produto danificado no endereço. Precisa ser segregado de imediato para não ser expedido, evitando devolução do cliente, prejuízo financeiro e risco à imagem da empresa; o registro permite tratativa com fornecedor ou baixa."]};
function ocList(r){const o=[];if(r.Erro_Produto)o.push(["erro",r.Endereco_Correto?"Endereço correto do item: "+fmtAddr(r.Endereco_Correto)+".":""]);if(r.Prox_Vencimento)o.push(["venc",r.Data_Vencimento?"Vencimento encontrado: "+r.Data_Vencimento+".":""]);if(r.Sem_Saldo)o.push(["saldo",""]);if(r.Avaria)o.push(["avaria",r.Tipo_Avaria?"Tipo: "+r.Tipo_Avaria+".":""]);return o;}
function docHTML(r){
  const row=(k,v)=>'<tr><td class="k">'+k+'</td><td>'+(v===""||v==null?"–":esc(v))+'</td></tr>';
  const vl=Math.round((+r.Vl_Ult_Entrada||0)*100)/100,tot=Math.round((+r.Valor_Divergencia||0)*100)/100;
  return '<div class="pd"><div class="pd-h"><img src="'+LOGO_BLUE+'" alt="Santa Therezinha"><div class="r"><h1>Registro de não conformidade</h1><p>Auditoria de ruas · Nº '+esc(r.ID_Auditoria)+'</p></div></div>'+
   '<h2>Identificação</h2><table>'+row("Data/hora da auditoria",r.DataHora)+row("Auditor",r.Nome_Auditor+" – matrícula "+r.Matricula_Auditor)+
   row("Repositor da rua",(r.Nome_Colaborador_NC||"")+" – matrícula "+(r.Matricula_Colaborador_NC||"")+(r.Funcao_Colaborador_NC?" ("+r.Funcao_Colaborador_NC+")":""))+row("Status",r.Status_NC)+'</table>'+
   '<h2>Produto e endereço</h2><table>'+row("Endereço auditado",fmtAddr(r.Endereco))+'</table>'+
   '<h2>Ocorrências registradas</h2><ul class="ocx">'+ocList(r).map(([k,x])=>'<li><b>'+OC_TXT[k][0]+'</b>'+(x?' – '+esc(x):'')+'<p>'+OC_TXT[k][1]+'</p></li>').join("")+'</ul>'+
   '<h2>Divergência</h2><table>'+row("Item",r.Produto+" – "+r.Descricao_Produto)+row("Unidades encontradas",r.Qtd_Divergencia_Un+" un")+row("Valor unitário (últ. entrada)",BRL.format(vl))+'</table>'+
   '<div class="tot"><span>Valor real da divergência<br><small>'+esc(r.Qtd_Divergencia_Un)+' un × '+BRL.format(vl)+'</small></span><b>'+BRL.format(tot)+'</b></div>'+
   '<h2>Observação</h2><div class="obw"><div class="obs">'+esc(r.Observacao||"–")+'</div>'+((r.fotos&&r.fotos.length)||r.foto?'<div class="phs">'+((r.fotos&&r.fotos.length)?r.fotos:[r.foto]).map(s=>'<img class="ph" src="'+s+'" alt="Foto do endereço">').join("")+'</div>':'')+'</div>'+
   termoHTML(ocList(r).map(([k])=>[OC_TXT[k][0],OC_TXT[k][1]]),+r.Valor_Divergencia||pnum(r.Valor_Divergencia))+
   '<p class="decl">Declaro ciência da não conformidade registrada acima e das informações de quantidade e valor apuradas na auditoria.</p>'+
   '<div class="sg"><div><b>Repositor</b>'+esc(r.Nome_Colaborador_NC||"")+'<small>Matrícula '+esc(r.Matricula_Colaborador_NC||"")+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Auditor</b>'+esc(r.Nome_Auditor)+'<small>Matrícula '+esc(r.Matricula_Auditor)+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Encarregado do setor de reposição</b>FABIO NYCKOLAS FIGUEIREDO BOTERO<small>Matrícula 10003993</small><small>Data: ___/___/______</small></div></div></div>';
}
const FIT_JS='function stFit(el){var c=el.cloneNode(true);c.style.cssText="position:absolute;left:-9999px;top:0;width:186mm;max-width:none;padding:0;zoom:1;box-shadow:none";document.body.appendChild(c);var mm=c.getBoundingClientRect().width/186;var h=c.getBoundingClientRect().height;c.remove();var lim=275*mm;var f=h>lim?Math.max(.6,Math.floor(lim/h*100)/100):1;document.documentElement.style.setProperty("--fit",f);return f;}';
(new Function(FIT_JS+';window.stFit=stFit;'))();
function fitWhenReady(el,cb){const imgs=[...el.querySelectorAll("img")].filter(i=>!i.complete);let n=imgs.length;const go=()=>{window.stFit(el);cb&&cb();};if(!n){go();return;}imgs.forEach(i=>{i.onload=i.onerror=()=>{if(--n===0)go();};});}
