const SCSS='.pd .termo{border:1px solid #F3CFCB;background:#FDF3F2;border-radius:6px;padding:6px 12px 8px;margin-top:10px;break-inside:avoid;-webkit-print-color-adjust:exact;print-color-adjust:exact}.pd .termo h2{margin:4px 0 4px;color:#9F1D14}.pd .termo p{margin:4px 0}.pd .termo ul{margin:4px 0 4px 18px;padding:0}.pd .termo li{margin:2px 0}.pd .sg{row-gap:40px}.pd .fg{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.pd .fg figure{margin:0;page-break-inside:avoid;break-inside:avoid}.pd .fg img{display:block;width:100%;height:36mm;object-fit:cover;border:1px solid #C9D6EA}.pd .fg figcaption{font-size:9.5px;color:#4F6380;margin-top:2px;line-height:1.2}'+
 '.pd .sum{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:8px}.pd .sum div{border:1px solid #C9D6EA;padding:6px;text-align:center}.pd .sum b{display:block;font-size:16px;color:#0A4DA2}.pd .sum span{font-size:10px;color:#4F6380}'+
 '.pd .lt th{background:#0A4DA2;color:#fff;font-size:10.5px;text-align:left;padding:4px 6px;-webkit-print-color-adjust:exact;print-color-adjust:exact}.pd .lt td{font-size:10.5px}.pd .lt tr{page-break-inside:avoid}.pd .lt td.n{text-align:right;white-space:nowrap}.pd .lt tfoot td{font-weight:bold;background:#F2F6FC}'+
 '.pd .leg li{border-left-width:3px}';
(function(){const s=document.createElement("style");s.textContent=SCSS;document.head.appendChild(s);})();
function sessDocHTML(S,recs){
  const ncs=recs.filter(r=>r.Possui_NC),conf=recs.length-ncs.length,tot=ncs.reduce((a,r)=>a+(+r.Valor_Divergencia||0),0);
  const first=recs.length?recs[recs.length-1]:null,last=recs.length?recs[0]:null;
  const ruaTot=E.pt.filter(a=>a[0]===String(S.rua)).length;
  const used={};ncs.forEach(r=>ocList(r).forEach(([k])=>used[k]=1));
  const ocShort=r=>ocList(r).map(([k,x])=>OC_TXT[k][0]+(x?" ("+x.replace(/\.$/,"")+")":"")).join("; ");
  const row=(k,v)=>'<tr><td class="k">'+k+'</td><td>'+(v===""||v==null?"–":esc(v))+'</td></tr>';
  return '<div class="pd"><div class="pd-h"><img src="'+LOGO_BLUE+'" alt="Santa Therezinha"><div class="r"><h1>Não conformidades – Rua '+esc(S.rua)+'</h1><p>Auditoria de ruas · Nº '+esc(S.id)+'</p></div></div>'+
   '<h2>Identificação</h2><table>'+row("Período da auditoria",(first?first.DataHora:"")+(last&&last!==first?" a "+last.DataHora.slice(11):""))+row("Auditor",S.audNome+" – matrícula "+S.aud)+
   row("Repositor da rua",S.repNome+" – matrícula "+S.rep+(S.repFun?" ("+S.repFun+")":""))+'</table>'+
   '<div class="sum"><div><b>'+recs.length+(ruaTot?' / '+ruaTot:'')+'</b><span>endereços auditados</span></div><div><b>'+conf+'</b><span>conformes</span></div><div><b>'+ncs.length+'</b><span>não conformidades</span></div><div><b>'+BRL.format(tot)+'</b><span>valor total da divergência</span></div></div>'+
   '<h2>Não conformidades registradas</h2>'+(ncs.length?'<table class="lt"><thead><tr><th>Endereço</th><th>Item</th><th>Ocorrência</th><th>Un</th><th>Vl. un.</th><th>Valor</th></tr></thead><tbody>'+
     ncs.slice().reverse().map(r=>'<tr><td>'+esc(fmtAddr(r.Endereco))+'</td><td>'+esc(r.Produto+" – "+r.Descricao_Produto)+'</td><td>'+esc(ocShort(r))+'</td><td class="n">'+esc(r.Qtd_Divergencia_Un)+'</td><td class="n">'+BRL.format(+r.Vl_Ult_Entrada||0)+'</td><td class="n">'+BRL.format(+r.Valor_Divergencia||0)+'</td></tr>').join("")+
     '</tbody><tfoot><tr><td colspan="3">Total</td><td class="n">'+ncs.reduce((a,r)=>a+(+r.Qtd_Divergencia_Un||0),0)+'</td><td></td><td class="n">'+BRL.format(tot)+'</td></tr></tfoot></table>':'<div class="obs">Nenhuma não conformidade nesta rua.</div>')+
   (function(){const pics=[];recs.slice().reverse().forEach(r=>{const fs=(r.fotos&&r.fotos.length)?r.fotos:(r.foto?[r.foto]:[]);fs.forEach(s=>pics.push({s,a:fmtAddr(r.Endereco),i:r.Produto,nc:r.Possui_NC}));});
     return pics.length?'<h2>Registro fotográfico</h2><div class="fg">'+pics.map(x=>'<figure><img src="'+x.s+'" alt="Foto do endereço '+esc(x.a)+'"><figcaption><b>'+esc(x.a)+'</b> · '+esc(x.i)+(x.nc?' · NC':' · conforme')+'</figcaption></figure>').join("")+'</div>':'';})()+
   (Object.keys(used).length?'<h2>Por que cada ocorrência importa</h2><ul class="ocx leg">'+Object.keys(used).map(k=>'<li><b>'+OC_TXT[k][0]+'</b><p>'+OC_TXT[k][1]+'</p></li>').join("")+'</ul>':'')+
   termoHTML(Object.keys(used).map(k=>[OC_TXT[k][0],OC_TXT[k][1]]),tot)+
   '<p class="decl">Declaro ciência das não conformidades registradas acima e das informações de quantidade e valor apuradas na auditoria da rua '+esc(S.rua)+'.</p>'+
   '<div class="sg"><div><b>Repositor</b>'+esc(S.repNome)+'<small>Matrícula '+esc(S.rep)+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Auditor</b>'+esc(S.audNome)+'<small>Matrícula '+esc(S.aud)+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Encarregado do setor de reposição</b>FABIO NYCKOLAS FIGUEIREDO BOTERO<small>Matrícula 10003993</small><small>Data: ___/___/______</small></div></div></div>';
}
const WA_NUM="5561986170228";
function waText(r){const vl=Math.round((+r.Vl_Ult_Entrada||0)*100)/100;
  return ["*NÃO CONFORMIDADE – Auditoria de Ruas*","Nº "+r.ID_Auditoria,"Data: "+r.DataHora,"Auditor: "+r.Nome_Auditor+" ("+r.Matricula_Auditor+")","Repositor: "+(r.Nome_Colaborador_NC||"")+" ("+(r.Matricula_Colaborador_NC||"")+")",
   "Endereço auditado: "+fmtAddr(r.Endereco),"Item: "+r.Produto+" – "+r.Descricao_Produto,
   "Ocorrências: "+ocList(r).map(([k,x])=>OC_TXT[k][0]+(x?" ("+x.replace(/\.$/,"")+")":"")).join("; "),
   "Unidades: "+r.Qtd_Divergencia_Un+" un × "+BRL.format(vl),"*Valor da divergência: "+BRL.format(Math.round((+r.Valor_Divergencia||0)*100)/100)+"*",
   r.Observacao?"Obs.: "+r.Observacao:"","Status: "+r.Status_NC].filter(Boolean).join("\n");}
function sessText(S,recs){const ncs=recs.filter(r=>r.Possui_NC),tot=ncs.reduce((a,r)=>a+(+r.Valor_Divergencia||0),0);
  return ["*NÃO CONFORMIDADES – Rua "+S.rua+"*","Nº "+S.id,"Auditor: "+S.audNome+" ("+S.aud+")","Repositor: "+S.repNome+" ("+S.rep+")",recs.length+" endereços auditados · "+ncs.length+" NC","*Valor total: "+BRL.format(tot)+"*"].join("\n");}
const waURLt=t=>"https://wa.me/"+WA_NUM+"?text="+encodeURIComponent(t);
const H2C="lib/html2canvas.min.js";
const JSPDF="lib/jspdf.umd.min.js";
function loadScript(src){return new Promise((res,rej)=>{const s=document.createElement("script");s.src=src;s.onload=res;s.onerror=()=>{s.remove();rej(new Error("load"));};document.head.appendChild(s);});}
async function makePdf(html,multi,land){
  if(!window.html2canvas)await loadScript(H2C);if(!(window.jspdf&&window.jspdf.jsPDF))await loadScript(JSPDF);
  const PW=land?297:210,PH=land?210:297;
  const host=document.createElement("div");host.style.cssText="position:fixed;left:-10000px;top:0;width:"+(land?1123:794)+"px;background:#fff;padding:"+(land?"0":"34px 45px")+";box-sizing:border-box";
  host.innerHTML=html;document.body.appendChild(host);
  await Promise.all([...host.querySelectorAll("img")].map(i=>i.complete?0:new Promise(ok=>{i.onload=i.onerror=ok;})));
  try{
    const cv=await window.html2canvas(host,{scale:2,backgroundColor:"#ffffff",logging:false,windowWidth:land?1200:900});
    const pdf=new window.jspdf.jsPDF({unit:"mm",format:"a4",orientation:land?"landscape":"portrait"});
    const pageH=Math.floor(cv.width*PH/PW);
    if(!multi||cv.height<=pageH){let w=PW,h=cv.height*w/cv.width;if(h>PH){h=PH;w=cv.width*h/cv.height;}pdf.addImage(cv.toDataURL("image/jpeg",.92),"JPEG",(PW-w)/2,0,w,h);}
    else{const pc=document.createElement("canvas");pc.width=cv.width;const ctx=pc.getContext("2d");let y=0,first=true;
      while(y<cv.height){const h=Math.min(pageH,cv.height-y);pc.height=h;ctx.fillStyle="#fff";ctx.fillRect(0,0,pc.width,h);ctx.drawImage(cv,0,y,cv.width,h,0,0,cv.width,h);
        if(!first)pdf.addPage();pdf.addImage(pc.toDataURL("image/jpeg",.92),"JPEG",0,0,PW,h*PW/cv.width);first=false;y+=pageH-60;}}
    return pdf.output("blob");
  }finally{host.remove();}
}
async function saveBlob(blob,name){
  if(downloads){try{await downloads.save({filename:name,data:blob});return true;}catch(e){if(e&&(e.code==="declined"||e.code==="rate_limited"))return false;}}
  const u=URL.createObjectURL(blob);const l=document.createElement("a");l.href=u;l.download=name;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),8000);return true;
}
function waFallback(name,text){const p=$("print");let b=$("pv-wafb");if(!b){b=document.createElement("div");b.id="pv-wafb";
  b.style.cssText="max-width:190mm;margin:0 auto 10px;background:#fff;border:2px solid #1E8E4E;border-radius:10px;padding:12px;font:15px/1.4 Arial,sans-serif;color:#0F2341";p.insertBefore(b,p.querySelector(".pd"));}
  b.innerHTML='<b>PDF baixado.</b> Abra a conversa e anexe o arquivo <i>'+esc(name)+'</i> (clipe → Documento).<a href="'+esc(waURLt(text))+'" target="_blank" rel="noopener" style="display:flex;align-items:center;justify-content:center;margin-top:10px;min-height:46px;border-radius:8px;background:#1E8E4E;color:#fff;font-weight:700;text-decoration:none">Abrir conversa (61) 98617-0228</a>';
  p.scrollTop=0;}
let CUR=null;
async function sendWA(btn){const D=CUR;if(!D)return;
  if(!navigator.onLine){toast("Sem internet agora. Use Baixar PDF e envie quando a conexão voltar.");return;}
  const old=btn.textContent;btn.disabled=true;btn.textContent="Gerando PDF…";
  try{const blob=D.pdfDocs?await makePdfLista(D.pdfDocs):await makePdf(D.html,D.multi,D.land),file=new File([blob],D.name,{type:"application/pdf"});
    if(navigator.canShare&&navigator.canShare({files:[file]})){
      try{await navigator.share({files:[file],title:D.title,text:D.short});toast("Escolha WhatsApp e o contato (61) 98617-0228.");return;}
      catch(e){if(e&&e.name==="AbortError")return;}}
    if(await saveBlob(blob,D.name))waFallback(D.name,D.text);
  }catch(e){toast("Não foi possível gerar o PDF. Tente novamente.");}
  finally{btn.disabled=false;btn.textContent=old;}
}
function openDoc(D){CUR=D;const p=$("print");
  p.innerHTML='<div class="pv-bar"><button type="button" id="pv-x">'+(D.closeLabel||"Fechar")+'</button><button type="button" class="main" id="pv-p">Imprimir</button><button type="button" id="pv-dl">Baixar PDF</button><button type="button" class="wa" id="pv-wa">Enviar PDF no WhatsApp</button></div>'+D.html;
  p.classList.toggle("land",!!D.land);p.hidden=false;p.scrollTop=0;
  const pd=p.querySelector(".pd");
  let pg=$("pg-land");if(D.land){if(!pg){pg=document.createElement("style");pg.id="pg-land";pg.textContent="@page{size:A4 landscape;margin:0}";document.head.appendChild(pg);}}else if(pg)pg.remove();
  const fitLand=()=>{const h=pd.scrollHeight||1;document.documentElement.style.setProperty("--fit",Math.min(1,Math.floor(780/h*100)/100));};
  if(D.land&&!D.multi)setTimeout(fitLand,60);else if(D.multi)document.documentElement.style.setProperty("--fit",1);else fitWhenReady(pd);
  $("pv-x").onclick=()=>{p.hidden=true;p.innerHTML="";CUR=null;const g=$("pg-land");if(g)g.remove();p.classList.remove("land");D.onClose&&D.onClose();};
  $("pv-p").onclick=()=>{try{if(D.land&&!D.multi)fitLand();else if(!D.multi)window.stFit(pd);window.print();}catch(e){toast("Impressão bloqueada aqui. Use Baixar PDF.");}};
  $("pv-dl").onclick=async()=>{const bt=$("pv-dl");bt.disabled=true;bt.textContent="Gerando PDF…";
    try{const blob=D.pdfDocs?await makePdfLista(D.pdfDocs):await makePdf(D.html,D.multi,D.land);if(await saveBlob(blob,D.name))toast("PDF salvo: "+D.name);}
    catch(e){toast("Não foi possível gerar o PDF. Tente novamente.");}
    finally{bt.disabled=false;bt.textContent="Baixar PDF";}};
  $("pv-wa").onclick=()=>sendWA($("pv-wa"));
}
function openPrint(r){openDoc({html:docHTML(r),multi:false,name:"NC_"+r.ID_Auditoria+".pdf",title:"Não conformidade "+r.ID_Auditoria,
  short:"Não conformidade "+r.ID_Auditoria+" – "+(r.Nome_Colaborador_NC||"")+" – "+BRL.format(+r.Valor_Divergencia||0),text:waText(r)});}
function openSessDoc(S,recs,onClose){const ncs=recs.filter(r=>r.Possui_NC);
  openDoc({html:sessDocHTML(S,recs),multi:true,name:"NC_Rua"+S.rua+"_"+S.id+".pdf",title:"Não conformidades – Rua "+S.rua,
    short:"Não conformidades – Rua "+S.rua+" – "+ncs.length+" NC – "+BRL.format(ncs.reduce((a,r)=>a+(+r.Valor_Divergencia||0),0)),text:sessText(S,recs),onClose,closeLabel:onClose?"Concluir":"Fechar"});}
if(S){setMode("end");reset();}renderSess();paintFotos();paintConn();paintPend();aplicarPerms();renderRecords();
if(!DEMO&&!LOGIN){mostrarLogin();}else{go((location.hash||"").slice(1));setTimeout(revalidar,800);setTimeout(carregarApoio,1500);}

